/*================================================================================================
［機能］	PIC初期化起動タスク 
--------------------------------------------------------------------------------------------------
［引数］	なし
［戻値］	なし
［詳細］	PIC初期化起動タスク  
 [履歴]		2003/12/19 morikawa 
			04/05/20 morikawa 電源投入時に予期せぬIDREQのリセット処理を追加　		
			05/12/25 morikawa Mosel初版　Rhein1の不要な処理削除	
			06/07/12 yoshii   Mosel      省電力解除時のIR初期化完了通知対応追加 
			08/02/18 R.Suzuki Donau      PICと通信できない問題暫定対応 
			08/02/29 河村 Donau 上記対応はスレッド電源制御部に移動しました
			09/03/12 安田 Linux新規実装
================================================================================================*/
static void taskInitPIC()
{
	BE_TaskMessage be_TaskMessage; uintptr_t ul_Option;
	while( 1 ) {
		if( receiveMessage( TID_InitPIC, be_TaskMessage, ul_Option ) == False ) {	// タスク間メッセージの受信.
#ifndef TORNADO		// ＰＣシミュレータで有効.
			return;
#endif	// #ifdef TORNADO.
		}
		switch( be_TaskMessage ) {
			case TM_IRNotReadyNotice:		// 03/12/17 morikawa IR初期接完了通知受信.
				if( ul_Option == 0 )
				{
					if( bl_PowerOnStart == True ){				// 電源投入時.
						thePowerManagerTask.PowerOnStart2();	// 電源制御起動処理２実行.
					} else {
						thePowerManagerTask.PowerIRpowerCtl2();	// 省電力復帰時.
					}
				}
				break;
			default:
				break;	
		}
	}	
}

// 2020.02.19 【HeliosMLK】OP_BTS-20114 メモリ不足救済用タスクの新規追加 ->.
/*================================================================================================
［機能］	メモリ救済用処理タスク.
--------------------------------------------------------------------------------------------------
［引数］	なし
［戻値］	なし
［詳細］	メモリ救済用処理タスク.
 [履歴]		2020/02/19 Sky 新規作成.
================================================================================================*/
static void taskMemoryRelief()
{
	BE_TaskMessage be_TaskMessage;
	char           sc_cmd[35] = {0};
	int32_t        si_Result  = 0;

	while( 1 ) {
		if( SYSF_msgQReceive( msgQID_MemoryRelief, (char*)&be_TaskMessage, sizeof(BE_TaskMessage), WAIT_FOREVER ) == ERROR ) {
#ifdef SIMULATOR		// シミュレータで有効.
		// ＰＣシミュレータで有効.
			return;
#endif	// #ifdef TORNADO.
		}
		switch( be_TaskMessage ) {
			case TM_PageAllocFailureIsKmalloc:			// Kernelから:kmallocの失敗.

				printf( "[%s] drop_caches exec.\n", __FUNCTION__ );
				sync();

				SYSF_taskDelay((SYSF_sysClkRateGet() * 10) / 1000);	// 10msec状態移行待ち.

				memset( sc_cmd, 0x00, sizeof( sc_cmd ) );
				snprintf( sc_cmd, sizeof( sc_cmd ), "echo 3 > /proc/sys/vm/drop_caches" );

				si_Result = system( sc_cmd );
				if( WEXITSTATUS( si_Result ) > 1 ) {
					printf( "%s: ERR: cmd:%s\n", __FUNCTION__, sc_cmd );
				}
				printf( "[%s] drop_caches ended.\n", __FUNCTION__ );

				break;

			default:
				break;
		}
	}
}
