CC_MultiThreadProfile::~CC_MultiThreadProfile()
{
	delete pc_TransCtrl;
	// リソースクラス開放.
	ushort us_Index = 0;
	for( us_Index = 0; us_Index < THRE_DmaId_Num; us_Index++ ){
		delete pc_DmaResMan[us_Index];
	}
	
	// 2014/02/26 山下(日立JTE) CQ381656 静的解析対応.
	if( NULL != pque_endTransMsgQue )
	{
		delete pque_endTransMsgQue;
	}
}

