/*================================================================================================
［機能］	【ＩＦ関数】バッファメモリ開放（ＡＣＳ結果単位）
--------------------------------------------------------------------------------------------------
［引数］
	ST_ThreadComPara	thread.hに定義
	THRE_TaskID: ＡＣＳ結果が確定したスレッドID
	Bool True:カラー決定　False：モノクロ決定
［戻値］
	なし
［詳細］
	・ＡＣＳの結果に基づき、バッファメモリからカラー成分orモノクロ成分を削除する
	・スレッド状態変化通知を送信する
［ｳｫｰｸｽﾙｰ］	実施未：2003/5/8：morikawa
［履歴］	2005/01/05 yokoi 連続領域確保中では、不要なカラーの開放を行わずにアレイの上書きとなっていたので、アレイの交換となるように修正
			2006/02/28 橋本昌 ACSの際、不要な色を削除する処理を追加
			2009/03/12 安田 Linux新規実装 
			2013/12/19 伊藤史. CQ384186 BufToFile完了メッセージ遅延バグ対策. deleteColorInfo引数 uc_OneThreadId は、BufToFile のIDが必要.
================================================================================================*/
void CC_MultiThreadProfile::rptReleaseMemResultACS( const ST_ThreadComPara& rs_ThreadComPara, THRE_ThrID en_ThreadID, Bool bl_Color )
{
	//2009/03/30 newInstance対応 comMemoryManagerのインスタンス生成.
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();

	ThBeforeRptReleaseMemResultACS( rs_ThreadComPara, en_ThreadID, bl_Color );

	THRL_SetThLog( 88, THRE_DebugLogType_MTCtrLog, 11, True,
		rs_ThreadComPara.c_ThreadIF.ul_ProcessID,
		bl_Color );

	THRL_ThAssert( (rs_ThreadComPara.c_ThreadIF.pc_Leaf != NULL), "CC_MultiThreadProfile::rptReleaseMemResultACS Leaf NULL" , 0, 0, 0, 0, CFA14_DetailCode0x03BD );
	THRL_ThAssert( (rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() != NULL), "CC_MultiThreadProfile::rptReleaseMemResultACS Image NULL" , 0, 0, 0, 0, CFA14_DetailCode0x03BE );
//	THRL_ThAssert( (rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ec_ColorMode != TYPE_ColorModeUnselect),.
//		"CC_MultiThreadProfile::rptReleaseMemResultACS ec_ColorMode = %d Error", rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ec_ColorMode );	// ScmImpColorの問題が対策されるまでコメントアウト 橋本 2006/03/02.
	
	THRL_Dbg_ImgParamMon( rs_ThreadComPara, THRE_TaskID_InputIR, en_ThreadID, True );	// 画像パラメータログ出力デバッグ.

	// ACSの決定が圧縮完了前に行われている場合はここでカラー情報削除 06/02/28 橋本昌.
	// 2013/12/19 伊藤史. CQ384186 BufToFile完了メッセージ遅延バグ対策. deleteColorInfo引数 uc_OneThreadId は、BufToFile のIDが必要.
	//   THRE_ExtToBufID_ScanIFInput->THRE_BufToFileID_ScanIfInput.
	comMemoryManager.deleteColorInfo( (IMGC_ThreadIF*)(&rs_ThreadComPara.c_ThreadIF),
									  THRE_ThrID_BufToFile, (uchar)THRE_BufToFileID_ScanIfInput );	// スレッドIDは THRE_ThrID_BufToFile 固定.

}

/*================================================================================================
［機能］	【内部】スレッド実行履歴設定処理 
--------------------------------------------------------------------------------------------------
［引数］	CC_OneImgTransInfo* pcc_OneImgTransInf
［戻値］	無し
［履歴］	2004/06/22 新規作成 橋本昌 
================================================================================================*/
void CC_MultiThreadProfile::setTransExecHist( CC_OneImgTransInfo* pcc_OneImgTransInfo )
{
	// 履歴を繰り上げ i: 0 新しい、 N 古い.
	for( uchar i = DEF_TransExecHistoryMaxNum-1; i > 0; i-- ){
		st_TransExecHist[ i ] = st_TransExecHist[ i-1 ];
	}
	st_TransExecHist[ 0 ].en_TaskID = pcc_OneImgTransInfo->en_TaskID;			//　タスクID.
	st_TransExecHist[ 0 ].ul_JobID = pcc_OneImgTransInfo->ul_JobID;						//	ジョブID.
	st_TransExecHist[ 0 ].en_AppIDSelThread = pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread;	//　アプリ種別.
	st_TransExecHist[ 0 ].en_ThreadID = pcc_OneImgTransInfo->en_ThreadID;				//　スレッドID.
	st_TransExecHist[ 0 ].bl_PageTrans = pcc_OneImgTransInfo->bl_PageTrans;		// ページ単位指定の時True,バンド単位の時False.
	
	if( pcc_OneImgTransInfo->en_TaskID == TID_OutputEng && pcc_OneImgTransInfo->en_ThreadID == TID_FileToBuf ){
		uc_BandCnt_BetweenEngPageOut = 0;	// エンジン出力のページとページの間にバンド転送を行った回数 初期化.
	}
	if( pcc_OneImgTransInfo->en_TaskID != TID_OutputEng 
		&& ( pcc_OneImgTransInfo->en_ThreadID == TID_BufToFile 
			|| pcc_OneImgTransInfo->en_ThreadID == TID_AppToFile 
			|| pcc_OneImgTransInfo->en_ThreadID == TID_AppToBufAndFile 
			|| pcc_OneImgTransInfo->en_ThreadID == TID_FileToBuf 
			|| pcc_OneImgTransInfo->en_ThreadID == TID_FileToApp )
		&& pcc_OneImgTransInfo->bl_PageTrans == False ){
		uc_BandCnt_BetweenEngPageOut++;	// エンジン出力のページとページの間にバンド転送を行った回数 インクリメント.
		
		if( uc_BandCnt_BetweenEngPageOut >= DEF_MAX_BandTransNum_BetweenEngOutPage+1 ){	//【修正:橋本昌】2004/08/06 Emperorプリント大量ページ対策 問題点 12656.
			// uc_BandCnt_BetweenEngPageOut が大きくなり過ぎないように上限を設定.
			uc_BandCnt_BetweenEngPageOut = DEF_MAX_BandTransNum_BetweenEngOutPage+1;
		}
	}
}

/*================================================================================================
［機能］	【ＩＦ関数】定期起床
--------------------------------------------------------------------------------------------------
［引数］なし
［戻値］なし
［詳細］
	・スレッド状態変化通知を送信するために、taskImageの定期メッセージ受信からコールされる
［ｳｫｰｸｽﾙｰ］	実施未：2003/5/8：morikawa
［履歴］	04/06/09：arakawa 不要な処理を削除 
			07/08/17：morikawa Donau CT検証用にSimWinでシーケンス実行後にこの関数でブレークして変数をdebugLogの番号に書き換えることにより
								ログを出力できるようにする。さらに、不要な処理を削除　 
            19/06/17：Sky合屋  [EagleH]OP_BTS-7616 A800 DDR異常画像問題暫定対策の削除対応.
            21/12/17：日立		OP_BTS-36869：【SYSQA-MSSBK_028】スリープ復帰ランニング中にC-FE51発生問題対応.
================================================================================================*/
int32_t debug_log = 0;	// ログ出力用のデバッグ用変数.
extern void _dbgLog( int32_t mode, int32_t on, uint32_t* buf );
int32_t debug_AllocFAT = 0;	// HDDフルチェック用のデバッグ変数.
int32_t debug_Para1 = 0;
int32_t debug_Para2 = 0;
int32_t debug_Para3 = 0;
extern void _debugAllocFAT( ushort mode, uint32_t on, int32_t num );
//Str【OP_BTS-36869：【SYSQA-MSSBK_028】スリープ復帰ランニング中にC-FE51発生問題対応 : 2021.12.17】.
static short ss_MemoryClearWaitCntLimit = 50;		// TimeOut=5sec.
static short ss_MemoryClearWaitCnt = 0;
void setMemoryClearWaitCntLimit( short ss_Cnt )
{
	ss_MemoryClearWaitCntLimit = ss_Cnt;
}
//End【OP_BTS-36869：【SYSQA-MSSBK_028】スリープ復帰ランニング中にC-FE51発生問題対応 : 2021.12.17】.
void CC_MultiThreadProfile::procTimerWakeUp()
{
	if( debug_log != 0 ) {
		_dbgLog( debug_log, 1, 0);
		debug_log = 0;
	}
	if( debug_AllocFAT != 0 ) {
		_debugAllocFAT( (ushort)debug_Para1, (uint32_t)debug_Para2, (int32_t)debug_Para3);
		debug_AllocFAT = 0;
	}
// 2013/07/02 KM(Morikawa) SoC LinuxSim JFM Merge.
#ifdef FUM_LINUX
	THRF_ThreadSimWinRun();	
#endif // #ifdef FUM_LINUX.

	if( comMultiThreadProfile.getMemoryClearReqState() == EN_MemoryClearEndWait ) {
		// taskThreadManager()から100ms間隔で定期起床コールされる.
		if( ss_MemoryClearWaitCnt >= 0 ) {
			ss_MemoryClearWaitCnt++;
			if( ss_MemoryClearWaitCnt >= ss_MemoryClearWaitCntLimit ) {
				printf(">>>EN_MemoryClearEndWaitTimeOut 5sec!!.\n");
				ss_MemoryClearWaitCnt = 0;	// カウンタクリア.
				setWaitMemClrCmp( 0 );
			}
		}
	} else {
		ss_MemoryClearWaitCnt = 0;
	}
}

