// ================================================================================================.
Bool CC_MultiThreadProfile::selUnitNextTimingExtMemToExt( ST_selUnitNTPara* pst_selUnitNTPara )
{
	// ◆注意　Fieryのスキャンアウト　PIC1200Sの制御含めて要検討.
	// 転送単位と次画像転送可能タイミング計算結果を画像転送管理情報に格納.
	return( selAnsUnitNextTiming( pst_selUnitNTPara ) );
}

/*================================================================================================
［機能］	【内部関数】実行開始確認時の次画像転送可能タイミング補正 
--------------------------------------------------------------------------------------------------
［引数］ST_ThreadComPara : スレッド共通パラメータ
［戻値］Bool True:動作可能、False：動作禁止
［詳細］ 画像転送モード取得に次画像転送可能タイミングは決定されるが、ファイル→バッファ画像転送の
		 ときは、実行開始確認を行うときに決定されるクリア有無の情報がひつようなため、
		 実行開始確認でクリア有無が決定されたあと、次画像転送可能タイミング補正を行う 
［ｳｫｰｸｽﾙｰ］	実施未：2003/10/23：橋本昌
［履歴］	04/06/09：arakawa 不要な処理を削除 
================================================================================================*/
Bool CC_MultiThreadProfile::chkUnitNextTiming( const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool bl_Ans = True;	// 戻り値を正常終了で初期化.
	
	short ss_TransIndexNum = rs_ThreadComPara.ss_TransIndexNum;	//  画像転送管理情報のインデックス番号.
	THRE_ThrID en_SelThreadID = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_TransIndexNum ][DEF_OutputThread][0].en_ThreadID;		// 	選択スレッドID.

	if( en_SelThreadID != THRE_ThrID_FileToBuf ){
		// ファイルメモリ→バッファメモリ以外は補正なし.
		return bl_Ans;
	}
	
	// 転送単位、次画像転送可能タイミング選択関数の引数構造体に決定値の初期値を設定.
	ST_selUnitNTPara st_selUnitNTPara;	// 転送単位、次画像転送可能タイミング選択関数の引数構造体.

	st_selUnitNTPara.st_ThreadComPara = rs_ThreadComPara;
	st_selUnitNTPara.pcc_OneImgTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_TransIndexNum ][DEF_OutputThread][0];
	st_selUnitNTPara.st_SelUnitNextComAns.bl_AllColor = True;	// 全色指定.
	st_selUnitNTPara.st_SelUnitNextComAns.bl_PageTrans = True;	// ページ単位指定.
	st_selUnitNTPara.st_SelUnitNextComAns.uc_UnitBandTrans = 0;	// 転送完了もページ単位で返すとして0で初期化しておく.
	st_selUnitNTPara.st_SelUnitNextComAns.en_NextEnableNumMode = EN_NextEnableNone;
	st_selUnitNTPara.st_SelUnitNextComAns.en_EngOutRoot = EN_EngOutRootNone;
	
	bl_Ans = selUnitNextTimingFileToBuf( &st_selUnitNTPara );
	
	return bl_Ans;
}

// ================================================================================================.
//! <!--機能--> 【内部関数】転送ライン管理クラスの、連続動作スレッド内でのリンク付け.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param short ss_Num ......................... 画像転送管理情報インデックス.
//! \param ST_ThreadComPara& rs_ThreadComPara ... スレッドパラメータ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  05/05/31 yokoi	 新規作成.
// ================================================================================================.
void CC_MultiThreadProfile::setLinkTransLineMan( short ss_Num, const ST_ThreadComPara& rs_ThreadComPara )
{
	uchar uc_InOutThread;				// 入力or出力判定.
	THRC_InspectDebugLog* pc_DebugLog = (THRC_InspectDebugLog*)THRC_InspectDebugLog::getInstance();

	// 入力 or 出力 を決定.
	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ) {
			uc_InOutThread = DEF_InputThread;
	} else {
			uc_InOutThread = DEF_OutputThread;
	}

	for( uchar uc_BusyIdx = 0; uc_BusyIdx < THRD_MaxThreadBusy; uc_BusyIdx++ ){
		CC_OneImgTransInfo* pc_TransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ss_Num][uc_InOutThread][uc_BusyIdx];
		if( pc_TransInfo->en_ThreadID != THRE_ThrID_None ){
			// AR1012299調査用.
			if ( ( THRE_ThrID_FileToBuf == pc_TransInfo->en_ThreadID ) && ( TID_OutputApp == pc_TransInfo->en_TaskID ) ){ // FileToBuf(App出力以外もあるのでApp出力に限定する).
				if ( NULL != pc_DebugLog ) {
					pc_DebugLog->InspectLogSet( THRD_InspectLogSetAR1012299,"[AR1012299][setLinkTransLineMan][1]\t pc_TransInfo[%08x]\t ul_JobID[%u]\t en_TaskID[%d]\t en_ThreadID[%d]\t TransLineMan[%08x]\n", (uintptr_t)pc_TransInfo, pc_TransInfo->ul_JobID, pc_TransInfo->en_TaskID, pc_TransInfo->en_ThreadID, pc_TransInfo->c_TransLineMan.getMyId() );
				}
			}
			pc_TransInfo->c_TransLineMan.init();
			// 前の転送スレッドとリンク.
			if( uc_BusyIdx != 0 ){
				// AR1012299調査用.
				if ( THRE_ThrID_BufToApp == pc_TransInfo->en_ThreadID ) { // BufToApp.
					if ( NULL != pc_DebugLog ) {
						pc_DebugLog->InspectLogSet( THRD_InspectLogSetAR1012299,"[AR1012299][setLinkTransLineMan][2]\t pc_TransInfo[%08x]\t ul_JobID[%u]\t en_TaskID[%d]\t en_ThreadID[%d]\t NowTransLineMan[%08x]\t PreTransLineMan[%08x]\n", (uintptr_t)pc_TransInfo, pc_TransInfo->ul_JobID, pc_TransInfo->en_TaskID, pc_TransInfo->en_ThreadID, pc_TransInfo->c_TransLineMan.getMyId(), CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ss_Num][uc_InOutThread][uc_BusyIdx-1].c_TransLineMan.getMyId() );
					}
				}
				pc_TransInfo->c_TransLineMan.setPreLink( &(CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ss_Num][uc_InOutThread][uc_BusyIdx-1].c_TransLineMan) );
			}
			// 後の転送スレッドとリンク.
			if( (uc_BusyIdx < (THRD_MaxThreadBusy-1)) && (CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ss_Num][uc_InOutThread][uc_BusyIdx+1].en_ThreadID != THRE_ThrID_None) ){
				pc_TransInfo->c_TransLineMan.setPostLink( &(CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ss_Num][uc_InOutThread][uc_BusyIdx+1].c_TransLineMan) );
			}
		}
	}
}

// ================================================================================================.
//! <!--機能--> 【内部関数】パラメータ確認処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... チェックする画像転送管理情報.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... スレッドパラメータ.
//! <!--戻値-->.
//! \return True:動作可能、False：動作禁止.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  06/03/13 yokoi	 新規作成.
//	09/09/11 陰山		Soc対応.
//	13/08/22 山下(日立JTE) CQ382598 分割保存完了状態のチェックを追加.
//	13/08/30 国吉(日立JTE) CQ382662 白紙挿入紙の場合に、分割転送をしない様にチェックを追加.
//				pc_ImageがNULLであれば例外処理として、Fatal出力(FA14)するよう変更.
//	13/09/09 岡部朋(日立JTE) 静的解析対応.
//	14/05/09 山下(日立JTE) 次世代アーキ スワップ分割読出対応.
//	14/06/27 岡部朋(日立JTE) CQ500800 HDD転送完了時に分割保存のHDD転送の優先度を下げる.
//	14/08/07 岡部朋(日立JTE) CQ500800 マルチ動作時、FA14が発生する問題の対策.
//  14/08/07 伊藤史. CQ501415 レポート画像生成時画像削除バグ修正. b_SplitTransStatusをIMGE_SplitTransNoneに設定してから削除する.
//  14/12/12 伊藤史. CQ507268 Ng-144でAppToApp停止する問題対策. 判定するThInfoを自身にする.
//  15/01/20 伊藤史. CQ507950 分割読出時、事前画像削除不具合修正. IMGE_SplitTransReadEnd を追加.
//  15/04/07 伊藤史. CQ511264 プレビュー画像分割読出キャンセル対応.
//  15/06/19 伊藤史. CQ514801 CQ511264でチェックインした箇所の不要コメント整理. 
// ================================================================================================.
Bool CC_MultiThreadProfile::chkParam( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkParam OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03E9 );

	Bool b_Ans = True;
	IMGC_Image* pc_Image = NULL;

	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ){
		if( rs_ThreadComPara.c_ThreadIF.pc_Leaf == NULL ){
			// 入力画像のパラメータ異常.
			b_Ans = False;
			_dbg_setChkTransExecNGPoint( 115 );	// 画像なし.
		}
	} else {
		CC_OneExpandMode* pc_OEM = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode;
		if( pc_OEM == NULL ){
			// エンジン出力時のキャンセルにて、次ページもキャンセル予定だが、.
			// その前に実行開始確認が動いてしまった場合もここにくる.
			// (ComParaが初期化されるため).
			b_Ans = False;
			_dbg_setChkTransExecNGPoint( 117 );	// 初期化されたパラメータ.
		} else {
			// 出力画像チェック.
			if( (pc_OEM->isNonPrint() == False) // 白紙でなく.
				&& ((pc_OEM->getOneInputPagePtr() == NULL) || (rs_ThreadComPara.c_ThreadIF.pc_Leaf == NULL)) // Leafが無ければ.
				){
				// 無印字でないのに、Leafが無い(Assertにしてもいいかも).
				b_Ans = False;
				_dbg_setChkTransExecNGPoint( 116 );	// 出力画像なし.
			}

			// 白紙挿入紙の場合に分割転送の判定は行わない.
			if( NULL != rs_ThreadComPara.c_ThreadIF.pc_Leaf ){

				// 出力時に分割保存が終わっていない場合、NGとする.
				pc_Image = rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage();
				THRL_ThAssert( (NULL != pc_Image), "CC_MultiThreadProfile::chkParam pc_Image is NULL." , 0, 0, 0, 0, CFA14_DetailCode0x0BFE );
				//  14/12/12 伊藤史. CQ507268 Ng-144でAppToApp停止する問題対策. 判定するThInfoを自身にする.
				//  さらに AppToAppは除外する.
				if( True == pcc_OneImgTransInfo->b_SplitTrans )
				{
					if( (IMGE_SplitTransWriteEnd_Image > pc_Image->c_ImageInfo.b_SplitTransStatus) &&
						(IMGE_SplitTransNone != pc_Image->c_ImageInfo.b_SplitTransStatus) && 
						(THRE_ThrID_AppToApp != pcc_OneImgTransInfo->en_ThreadID) ){
						// 分割保存のHDD転送が完了していない.
						_dbg_setChkTransExecNGPoint( 144 );
						b_Ans = False;
						
					}
				}

				// スワップ分割読出　パラメータ判定.
				IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();
				if( ( True == pcc_OneImgTransInfo->b_SplitTrans )
					&& ( pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_FileToBuf )
					&& ( pcc_OneImgTransInfo->en_ThreadImgProcMode == THRE_ImgProcMode_PreConvert )
					&& ( pcc_OneImgTransInfo->us_RepeatPageEndNum == 0 ) ){

					// 分割読出 1次伸張のページ開始時.
					for( uchar uc_index = 0; uc_index < InputPageNumMax; uc_index++ ){
						DOCC_Leaf* pc_Leaf = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[uc_index].pOIP;
						if( NULL != pc_Leaf ) {
							IMGC_Image* pc_Image_III = pc_Leaf->getImage();
							if( NULL != pc_Image_III ){
								
								// 画像の格納場所の判定.
								if( ( True == pc_Image_III->c_ImageInfo.b_SplitTrans ) && 
									( (IMGE_ImagePlace_MemoryAndHDD == pc_Image_III->c_ImageInfo.ec_ImagePlace) || (IMGE_ImagePlace_SplitCancel == pc_Image_III->c_ImageInfo.ec_ImagePlace) ) ) {
									// 2014/08/07 伊藤史. CQ501415 レポート画像生成時画像削除バグ修正. b_SplitTransStatusをIMGE_SplitTransNoneに設定してから削除する.
									// 2015/01/20 伊藤史. CQ507950 分割読出時、事前画像削除不具合修正. IMGE_SplitTransReadEnd を追加.
									if( (IMGE_SplitTransWriteEnd_Image == pc_Image_III->c_ImageInfo.b_SplitTransStatus) ||
										(IMGE_SplitTransReadEnd == pc_Image_III->c_ImageInfo.b_SplitTransStatus) ){
										pc_Image_III->c_ImageInfo.b_SplitTransStatus = IMGE_SplitTransNone;
									}
									comMemoryManager.releaseImage( pc_Image_III, IMGE_DeleteMode_Memory );
									pc_Image_III->c_ImageInfo.b_SplitTransStatus = IMGE_SplitTransReadWait;
								}

								// 2部目動作の考慮.
								if( rs_ThreadComPara.ss_BandID == 1 ) {
									// 初回バンドの場合.
									if( pc_Image_III->c_ImageInfo.b_SplitTransStatus == IMGE_SplitTransReadExec ) {
										// 1部目の分割読出が実行中の場合NG.
										_dbg_setChkTransExecNGPoint( 164 );
										b_Ans = False;
										break;
									}

									if( pc_Image_III->c_ImageInfo.b_SplitTrans != pcc_OneImgTransInfo->b_SplitTrans ) {
										// 1部目の最終バンドの分割転送完了前にGetTransModeで2部目の分割転送判定が行われた場合.
										// フラグの設定をしなおす.									
										pc_Image_III->c_ImageInfo.b_SplitTrans = pcc_OneImgTransInfo->b_SplitTrans;
									}
									
									if( ( pc_Image_III->c_ImageInfo.b_SplitTransStatus >= IMGE_SplitTransReadEnd )
										&& ( pc_Image_III->c_ImageInfo.b_SplitTransStatus != IMGE_SplitTransNg) ) {
										// 分割読出の待ち状態まで戻す.
										pc_Image_III->c_ImageInfo.b_SplitTransStatus = IMGE_SplitTransReadWait;
									}
								}
								
								if( IMGE_ImagePlace_MemoryToHDD == pc_Image_III->c_ImageInfo.ec_ImagePlace ) {
									// HDD転送が完了していないため、分割読出不可.
									_dbg_setChkTransExecNGPoint( 165 );
									b_Ans = False;
								}else{
									// HDD転送完了時、スワップ保存の優先度を下げる.
									comMemoryManager.setSwapMode_MemoryToHDD_SlowDown( pcc_OneImgTransInfo->b_SplitTrans );
								}
							}
						}
					}
				} else if( ( THRE_ThrID_FileToBuf == pcc_OneImgTransInfo->en_ThreadID )
						&& ( 0 == pcc_OneImgTransInfo->us_RepeatPageEndNum ) ){
					// 2015/04/07 伊藤史. CQ511264 プレビュー画像分割読出キャンセル対応.
					for( uchar uc_index = 0; uc_index < InputPageNumMax; uc_index++ ){
						DOCC_Leaf* pc_Leaf = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[uc_index].pOIP;
						if( NULL != pc_Leaf ) {
							IMGC_Image* pc_Image_III = pc_Leaf->getImage();
							if( NULL != pc_Image_III ){

											// 画像の格納場所の判定.
								if( IMGE_ImagePlace_SplitCancel == pc_Image_III->c_ImageInfo.ec_ImagePlace ) {
									pc_Image_III->c_ImageInfo.b_SplitTransStatus = IMGE_SplitTransNone;

									comMemoryManager.releaseImage( pc_Image_III, IMGE_DeleteMode_Memory );
									pc_Image_III->c_ImageInfo.b_SplitTransStatus = IMGE_SplitTransReadWait;
								}
							}
						}
					}
				}

			}

			// アウトライン使用確認.
			if ( ( theModeInfoLib.chkExecMode( THRE_ChkMode_Date, rs_ThreadComPara ) == True )	// 日付／時刻.
				|| ( theModeInfoLib.chkExecMode( THRE_ChkMode_Page, rs_ThreadComPara ) == True )	// ページ番号.
				|| ( theModeInfoLib.chkExecMode( THRE_ChkMode_HeaderFooter, rs_ThreadComPara ) == True ) ) {	// ヘッダ・フッタ.
#if (defined(COSIM) && defined(THR_SIMWIN)) 
			//COSIM1st.検証では、上位未実装の為下記処理を行わない。.
#else				
				if ( APIC_OutlineFont::newInstance()->checkFont3Data() == TYPE_Font3DataSetting ) {
					setDelayMessage( TID_ThreadManager, TM_CheckOutLineFontLoaded, 0, 100 );	// アウトラインフォント実行開始チェック 2008/04/22t-kasahara 新規追加.
					b_Ans = False;
					_dbg_setChkTransExecNGPoint( 125 );		// アウトラインフォントデータメモリがメモリに設定されていない.
				}
#endif
			}
		}
	}

	return ( b_Ans );
}

// ================================================================================================.
//! <!--機能--> 【内部関数】出力開始確認処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... 画像転送管理情報へのポインタ.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... スレッド共通パラメータ.
//! <!--戻値-->.
//! \return True:動作可能、False：動作禁止.
//! <!--詳細-->.
//! バッファからの出力の時、出力開始可能かどうか判断する\n.
//! 入力の時は無条件に可能とする\n.
//! ファイルからの出力の時は要検討\n.
//! <!--履歴-->.
//  05/05/25 yokoi	 新規作成.
//  2019/04/01 KM(Morikawa) AR:1074541 PCプリントでBOX保存した画像をIFAX送信すると送信画像の左下に黄色い線が載る場合があるの問題修正.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkStartOutput( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkStartOutput OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03EA );

	Bool b_Ans = True;
//	CC_OneImgTransInfo* pcc_BufInOneImg;.

	if( pcc_OneImgTransInfo->bl_ExecBusy == True ){
		// 既に動作中(前のバンドが動作しているハズなので、追い越し禁止).
		b_Ans = False;
		_dbg_setChkTransExecNGPoint( 105 );
	}


	if( pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_BufToExt ) {
		uchar uc_ThInorOutNum, uc_ThBusyNum;
		// 動作中のスレッドＩＤのインデックス番号取得.
		CC_ImgTransInfoSingletonIf::newInstance().getOneImgIndexNumFromTh( uc_ThInorOutNum, uc_ThBusyNum, rs_ThreadComPara, THRE_ThrID_BufToExt );
		// エンジン出力が、連続動作の先頭スレッドでなければ.
		if( uc_ThBusyNum != 0 ) {
			if( CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][uc_ThBusyNum-1].bl_NextEnableRptEnd == False ) {
				b_Ans = False;		// バッファ→外部の時に１つ前がファイル→バッファでかつ次画像転送可能通知がまだ未送信の時は待つ.
				_dbg_setChkTransExecNGPoint( 3 );	// 【修正:橋本昌】2004/05/28 デバッグ用 実行開始確認NG ログ取得.
			 }
		}
	}

	if( pcc_OneImgTransInfo->bl_FileMemOverFlowOccured ){	// 【修正:橋本昌】2004/07/24 メモリオーバーフロー対策.
		// メモリオーバーフローが発生しているとき.
		b_Ans = False;	// 実行開始確認NG.
		_dbg_setChkTransExecNGPoint( 22 );	// デバッグ用 実行開始確認NG ログ取得.
	}

	// 2006/04/27 yokoi Rheinからのマージ対応.
	// 2006/02/22 伊藤(史)：問題点52584：R40対策.
	// FAX送信のExtToBufは、FAX着呼から画像送信開始まで 停止する。.
	// ソフトSW 70 の 1 で機能を有効化する。: 実際は 3 の 1.
	// デバッグ：bl_dbg_FAX_RedZone_StopScan=2は強制停止.
	if( (CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_InputThread][0].st_TransModePara.en_AppIDSelThread == THRE_AppID_FaxSend)
		&& (pcc_OneImgTransInfo->b_IsAllocedResource == False)
		&& (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_ExtToBuf) ){

#ifndef COSIM
		APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();	// DipSw（API）.
		if( pc_SoftDipSw->getSoftDipSwBit( 3, 1 ) == True ){
			if( APIC_FaxDevice::newInstance()->isFaxPhB() == True ||
				bl_dbg_FAX_RedZone_StopScan == 2 ){

			    //(通信状態の判定、回線状態の判定よりFAX通信中を判定).
				b_Ans = False;
				_dbg_setChkTransExecNGPoint( 48 );
			}
		}
#endif
	}

// 2019/04/01 KM(Morikawa) AR:1074541 問題対策.
	if( b_Ans == True 
	 && pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread != THRE_AppID_Preview	
	 && pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_FileToBuf
	 && pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_OutputApp
	 && pcc_OneImgTransInfo->en_ThreadImgProcMode == THRE_ImgProcMode_PreOutPut ) {	
	
	 	TYPC_Point<int32_t> ct_PointImageSize;
	 	TYPC_Point<int32_t>	ct_PointOutputSize;
		uchar ucIdx;
		CC_OneExpandMode* pc_OEM = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode;
		for( ucIdx=0; ucIdx < InputPageNumMax; ucIdx++ ){
			// 入力ページ情報を取得.
			if ( pc_OEM->III[ucIdx].pOIP != NULL ) {
				//! アプリ出力は解像度1200dpiの場合はないので.直接解像度で変換.
				ct_PointImageSize.y = MMtoDOT( pc_OEM->III[ucIdx].ct_ImageSize.y, pc_OEM->c_Resolution.getDpi().y );
				ct_PointOutputSize.y = MMtoDOT( pc_OEM->ct_OutputSize.y, pc_OEM->c_Resolution.getDpi().y );
				break;
			}
		}
	 	
 		if( ct_PointOutputSize.y > ct_PointImageSize.y ) {
 			
 			// 出力サイズがImageサイズよりも大きい時のみ、トリミング領域外でメモリクリヤできない不具合対策.
	
 			if( pcc_OneImgTransInfo->us_RepeatExecNum >= 3
 			 && ( (pcc_OneImgTransInfo->us_RepeatExecNum - 2) == pcc_OneImgTransInfo->us_RepeatEndNum ) ) {
				
 			 	// 今から伸張しようとするブロックの１回前の伸張ブロック領域が、リングバッファの次の周回が最終バンドの端数になる時.
				uchar uc_ThInorOutNum, uc_ThBusyNum;
 			 	ushort us_WaitRepeatEndNum = ( pcc_OneImgTransInfo->us_RepeatExecNum - 2 ) * DEF_BasicCompExpLine/DEF_BasicTransLine;
 			 	
				// 動作中のスレッドＩＤのインデックス番号取得.
				CC_ImgTransInfoSingletonIf::newInstance().getOneImgIndexNumFromTh( uc_ThInorOutNum, uc_ThBusyNum, rs_ThreadComPara, THRE_ThrID_FileToBuf );
				// 次のBufToAppが、前の伸張ブロックで動作中かどうか判断.
				if( CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][uc_ThBusyNum+1].en_ThreadID == THRE_ThrID_BufToApp ) {
					// 念のために、次のスレッドがBufToAppであることを確認.
					if( CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][uc_ThBusyNum+1].us_RepeatEndNum 
					 < us_WaitRepeatEndNum ) {
						// 動作中の判断はせずに、最後のBufToAppがリングバッファの次の周回が最終バンドの端数になる伸張ブロックの読み出しが完了していない時は待つ.
						b_Ans = False;		
						_dbg_setChkTransExecNGPoint( 176 );		// 追加。デバッグ用 実行開始確認NG ログ取得.
					} 	
				} 
			} 
 		} 	
	}
	
	return( b_Ans );
}

// ================================================================================================.
//! <!--機能--> 【内部関数】禁止組み合わせチェック処理（ＤＭＡ）.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... 画像転送管理情報へのポインタ.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... スレッド共通パラメータ.
//! <!--戻値-->.
//! \return True:動作可能、False：動作禁止.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  05/05/25 yokoi	 新規作成.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkCombinationDMA( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkCombinationDMA OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03EB );

	Bool b_Ans = True; // 動作可能で初期化.

	// 同時禁止組み合わせは無いので、とりあえず常にOKとする.
	return( b_Ans );
}

static CC_OneImgTransInfo c_OneImgTransInfo;	// 仮のデータ実態.
// ================================================================================================.
//! <!--機能--> 【内部関数】禁止組み合わせチェック処理（ＤＭＡ）.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... 画像転送管理情報へのポインタ.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... スレッド共通パラメータ.
//! <!--戻値-->.
//! \return True:動作可能、False：動作禁止.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  05/05/25 yokoi	 新規作成.
//  06/03/24 yokoi	 スレッド内色変換処理を削除.
//  07/09/05 takamoto	白紙対応.
//  09/07/16 yashiro Emperorプリント1200dpi対応.
//  09/08/05 yashiro CT1対応 - Gaia問題点リストのNo.36.
//  09/10/22 nakagawa	転送ライン管理データは確保後、破棄してはいけないので、c_OneImgTransInfoを.
//                      グローバル変数に変更.
//  12/08/07 OPS1-Sky佐藤宏 [Archi][パフォーマンス改善]getImageコール回数削減対応.
//  12/08/30 Gonsho	 静的解析対応 pc_Image(getImage)のNULLチェックを追加.
//  13/03/26 Sky ZeusS対応 アクセラレータの条件を変更.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkCalBufPlaneNum( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool b_Ans = False;
	Bool b_1200dpi = False;

	//モノクロ画像へのカラー連番印字対応 [追加] kuroda 04/04/12.
	IMGE_ImageColor		ec_ImageColor;
	ec_ImageColor = getImageColorFromThInfo( pcc_OneImgTransInfo, rs_ThreadComPara );

	//! 入力と出力で切り分けて、1200dpiを判定する.
	b_1200dpi = chk1200DpiWrapInOut( rs_ThreadComPara );

	/////////// 画像変換前の画像情報の設定.
	//if( chk1bitMode( rs_ThreadComPara.c_ThreadIF.pc_Leaf ) == True ) {.
	if( chk1bitMode( pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara ) == True ) {
		// ２値の時.
		//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追.
		b_Ans = calBufPlaneNum1bit( pcc_OneImgTransInfo, ec_ImageColor, b_1200dpi );

	} else {
		// 多値の時.
		if( (rs_ThreadComPara.pcc_OneImageOutputMode != NULL )
		 && (rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->isNonPrint() == True)
		){
			// 白紙の場合.
			//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
			b_Ans = calBufPlaneNumMulti( pcc_OneImgTransInfo, ec_ImageColor, IMGE_ImageCompress_Non, b_1200dpi );
		}else{
			//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
			b_Ans = calBufPlaneNumMulti( pcc_OneImgTransInfo, ec_ImageColor, getImageCompress( rs_ThreadComPara.c_ThreadIF.pc_Leaf ), b_1200dpi );
		}
	}
	
	/////////// 画像変換後の画像情報の設定.
	if( pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_BufToBuf 
		&& ( theModeInfoLib.chkExecMode( THRE_ChkMode_ChgColor, rs_ThreadComPara ) == True 
			|| theModeInfoLib.chkExecMode( THRE_ChkMode_ChgTone, rs_ThreadComPara ) == True ) ){
			// 画像データ変換 ( 色変換、２値多値変換 )あり.
			register DOCC_Leaf* pc_LocalLeaf = CC_ImgTransInfoSingletonIf::newInstance().getLocalLeaf( pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara );	// ローカルな入力画像情報(Leaf)取得 変換後の画像情報.
			
			register Bool b_TmpAns = False;
			IMGC_Image* pc_Image = pc_LocalLeaf->getImage();
			THRL_ThAssert( pc_Image != NULL, "chkCalBufPlaneNum pc_Image is NULL(1)." , 0, 0, 0, 0, CFA14_DetailCode0x0A60 );
			if( chk1bitMode( pc_LocalLeaf ) == True ) {
				//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
				b_TmpAns = calBufPlaneNum1bit( &c_OneImgTransInfo, pc_Image->c_ImageInfo.ec_ImageColorResult, b_1200dpi );
			} else {
				//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
				b_TmpAns = calBufPlaneNumMulti( &c_OneImgTransInfo, pc_Image->c_ImageInfo.ec_ImageColorResult, 
					pc_Image->c_ImageInfo.ec_ImageCompressResult, b_1200dpi );
			}
			
			THRL_ThAssert( b_TmpAns, "CC_MultiThreadProfile::chkCalBufPlaneNum error" , 0, 0, 0, 0, CFA14_DetailCode0x03EC );
			
			pcc_OneImgTransInfo->uc_DstAllPlaneNum = c_OneImgTransInfo.uc_AllPlaneNum;			// 全プレーン数.
			pcc_OneImgTransInfo->uc_DstAllColorNum = c_OneImgTransInfo.uc_AllColorNum;			// 全色数.
			pcc_OneImgTransInfo->uc_DstAllAttNum = c_OneImgTransInfo.uc_AllAttNum;				// 全属性プレーン数.
			
			b_Ans = (Bool)(b_Ans | b_TmpAns);
	} else if ( THRE_ImgProcMode_AppInConvDiv == pcc_OneImgTransInfo->en_ThreadImgProcMode) {

			// 11/09/30 窪川 アクセラレータオプション基板搭載時のアプリ入力系では画像変換(色変換)を行う場合があるので.
			// 出力側のプレーン数は、resultをセットする(画像変換しない場合もこちらを通るので注意).

			register Bool b_TmpAns = False;
			IMGC_Image* pc_Image = rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage();
			THRL_ThAssert( pc_Image != NULL, "chkCalBufPlaneNum pc_Image is NULL(2)." , 0, 0, 0, 0, CFA14_DetailCode0x0A97 );
			if( chk1bitMode( rs_ThreadComPara.c_ThreadIF.pc_Leaf ) == True ) {
				//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
				b_TmpAns = calBufPlaneNum1bit( &c_OneImgTransInfo, pc_Image->c_ImageInfo.ec_ImageColorResult, b_1200dpi );
			} else {
				//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加.
				b_TmpAns = calBufPlaneNumMulti( &c_OneImgTransInfo, pc_Image->c_ImageInfo.ec_ImageColorResult, 
					pc_Image->c_ImageInfo.ec_ImageCompressResult, b_1200dpi );
			}
			
			THRL_ThAssert( b_TmpAns, "CC_MultiThreadProfile::chkCalBufPlaneNum error" , 0 , 0, 0, 0, CFA14_DetailCode0x09A9 );
			
			pcc_OneImgTransInfo->uc_DstAllPlaneNum = c_OneImgTransInfo.uc_AllPlaneNum;			// 全プレーン数.
			pcc_OneImgTransInfo->uc_DstAllColorNum = c_OneImgTransInfo.uc_AllColorNum;			// 全色数.
			pcc_OneImgTransInfo->uc_DstAllAttNum = c_OneImgTransInfo.uc_AllAttNum;				// 全属性プレーン数.

			b_Ans = (Bool)(b_Ans | b_TmpAns);

	} else {
		// 画像データ変換なし.
		pcc_OneImgTransInfo->uc_DstAllPlaneNum = pcc_OneImgTransInfo->uc_AllPlaneNum;			// 全プレーン数.
		pcc_OneImgTransInfo->uc_DstAllColorNum = pcc_OneImgTransInfo->uc_AllColorNum;			// 全色数.
		pcc_OneImgTransInfo->uc_DstAllAttNum = pcc_OneImgTransInfo->uc_AllAttNum;				// 全属性プレーン数.
	}

	// 同時禁止組み合わせは無いので、とりあえず常にOKとする.
	return( b_Ans );
}

/*================================================================================================
［機能］	【内部関数】ファイルメモリ確保可能かどうか判断し、可能であればファイルメモリ確保を実行する 
--------------------------------------------------------------------------------------------------
［引数］
	CC_OneImgTransInfo* : 画像転送管理情報へのポインタ
	short: バンドID
	ST_ThreadComPara:　
［戻値］
	Bool True:確保可能、False：不可能　
［詳細］
［ｳｫｰｸｽﾙｰ］	実施未：
［履歴］	05/03/10：yokoi 新規作成
			06/03/28：yokoi 変倍Nin1対応 
		06/06/12：morikawa スレッドローカルでファイルメモリを確保するときにその他の要因で実行開始確認NGとなった場合に
				すでに確保されたImageに対してさらにallocPageを呼びたくないためにpcImageImpColor->isExistImageInfo() == False
				の条件を入れていたが、これがためにメモリ確保失敗でも再度この関数が呼ばれた時に誤ってメモリ確保成功としていた
				不具合修正　
		07/05/09：yokoi chkEnableExpand/chkEnableCompressは、内部でNgPointを設定しているので、戻り値がFalseでも
						NgPointを設定しないように修正。(33,35,36 を廃止した)
		08/10/18 takamoto	CQ-311887 1次伸張のFileToBuf時に先行変倍用のファイルメモリ確保チェックを追加.
		09/02/12 kurachi Donau3/Amur CQ:314487対策.
							画像退避するジョブ（I-Fax受信）を含む3次元マルチで、ファイルメモリの空きがなくなったとき、.
							メモリ確保成功して状態変化通知を送ったにも関わらず、実行開始確認にて、.
							再度メモリ確保実行してしまっていて、いっこうにメモリ確保できない状態になっていた。.
							対策として、確保済みでない場合のみAllocPageWithWait()をコールするようにする。.

		09/03/12 安田 Linux新規実装
		09/07/03 世古 Emperorプリント1200dpi対応：オーバーレイ.
		11/08/25 tadamasa 静的解析修正.
		12/08/07 OPS1-Sky佐藤宏 [Archi][パフォーマンス改善]getImageコール回数削減対応.
		14/06/02 ogura		CQ.390862 セマフォログ追加.
		14/05/09 山下(日立JTE)次世代アーキスワップ分割読出対応.
		15/06/05 伊藤史. CQ512749 同時両面ファイルメモリ事前確保対応. chkEnableCompress 引数追加.
		15/10/26 Sky		システム統合SoC(S800)対応.
================================================================================================*/
Bool CC_MultiThreadProfile::chkEnableFileAllocExec( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	//2009/03/30 newInstance対応 comMemoryManagerのインスタンス生成.
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();

	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkEnableFileAllocExec OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03ED );

	Bool b_Ans = True;	// 戻り値、確保可能で初期化.

	// FileMemoryの操作を行うので、セマフォロック.
// 2015/05/04 morikawa.入力のBufToFileとAppToAppは何もしないので、セマフォにぎらない。	
	if( pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_AppToApp ) {
		return( True );
 	} 	
 	
	comMemoryManager.semTake_FileMemAlloc( WAIT_FOREVER, THRD_SemLog_MultiThread_chkEnableFileAllocExec );

	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ){
		///////////////// 入力の時 ///////////////.
		switch( pcc_OneImgTransInfo->en_ThreadID ){
			case THRE_ThrID_ExtToBuf:// 入力の時点で確保しておく.
				// ファイルメモリ確保タイミング変更有効/無効判定.
				if( True == isAllocFileMemoryTimingChange() ){
					if( pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_InputIRDup ){
						// 裏面IR入力の場合は、確保チェックしない.
					}else{
						// 表面IR入力/Fiery入力.
						// 圧縮用のFileMemoryが確保できるかチェック.
						b_Ans = chkEnableCompress( pcc_OneImgTransInfo, rs_ThreadComPara.c_ThreadIF.pc_Leaf, rs_ThreadComPara.b_1PassDuplexJob );
					}
				}else{
					// 圧縮用のFileMemoryが確保できるかチェック.
					b_Ans = chkEnableCompress( pcc_OneImgTransInfo, rs_ThreadComPara.c_ThreadIF.pc_Leaf, rs_ThreadComPara.b_1PassDuplexJob );
				}
				break;
			case THRE_ThrID_AppToBuf:// 入力の時点で確保しておく.
			case THRE_ThrID_AppToFile:
				// 圧縮側.
				// 圧縮用のFileMemoryが確保できるかチェック.
				b_Ans = chkEnableCompress( pcc_OneImgTransInfo, rs_ThreadComPara.c_ThreadIF.pc_Leaf, rs_ThreadComPara.b_1PassDuplexJob );
				break;
			case THRE_ThrID_BufToFile:
				if( IMGE_BlockSizeConvertStatePushImage == IMGG_getBlockSizeConvertRestoreDataState() ){
					// 圧縮用のFileMemoryが確保できるかチェック.
					b_Ans = chkEnableCompress( pcc_OneImgTransInfo, rs_ThreadComPara.c_ThreadIF.pc_Leaf, rs_ThreadComPara.b_1PassDuplexJob );
					break;
				}
				// ファイルメモリ確保タイミング変更有効/無効判定.
				if( True == isAllocFileMemoryTimingChange() ){
					if( pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_InputIRDup ){
						// 裏面IR入力の場合は、BufToFileのタイミングで確保チェックする.
						// 圧縮用のFileMemoryが確保できるかチェック.
						b_Ans = chkEnableCompress( pcc_OneImgTransInfo, rs_ThreadComPara.c_ThreadIF.pc_Leaf, rs_ThreadComPara.b_1PassDuplexJob );
					}else{
						// 表面IR入力/Fiery入力の場合は、既にExtToBufの時点で確保済み.
					}
				}
				break;
			default:
				// FileMemory確保チェックは必要なし。.
				break;
		}
	} else {
		///////////////// 出力のとき ///////////////.
		//DOCC_Leaf* pc_LocalLeaf = NULL; 2006/02/20 Koshino(Sky) 不要な宣言なので削除する.
		CC_OneExpandMode* pc_LocalOneExpandMode = NULL;
		IMGC_ImageImp*	pcImageImpColor = NULL;
		uchar i = 0;
		uint32_t ul_usedFileMem = 0;			// CQ-311887 先行変倍用の使用ファイルメモリサイズ.

		switch( pcc_OneImgTransInfo->en_ThreadID ){
			case THRE_ThrID_BufToFile:	// データ変換後の圧縮.
				// 変倍Nin1時は、最初に全て確保するので、1回目のみ処理を行う.
				if( pcc_OneImgTransInfo->us_RepeatPageEndNum == 0 ){
					// ローカルなOEMに対してファイルメモリ確保が必要.
					pc_LocalOneExpandMode = CC_ImgTransInfoSingletonIf::newInstance().getLocalOneExpandMode( pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara );
					IMGC_Image* pc_Image = NULL;
					// まずは画像の管理情報確保及びHDDとの容量の兼ね合いをチェックする(1回のみ).
					for( i = 0; i < InputPageNumMax; i++ ){
						DOCC_Leaf* pc_Leaf = pc_LocalOneExpandMode->III[i].pOIP;
						if( pc_Leaf != NULL ){
							pc_Image = pc_Leaf->getImage();
							THRL_ThAssert( ( pc_Image != NULL ), "TCC_MultiThreadProfile::chkEnableFileAllocExec(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x03EE );
							// 出力時BufToFileのLocalOneExpandModeの分割転送フラグを折る.
							pc_Image->c_ImageInfo.b_SplitTrans = False;
							pcImageImpColor = ( pc_Image->m_IMGC_ImageImp );
							// 確保済みでない場合のみメモリ確保チェックをする.
							if( pcImageImpColor->c_ArrayGetMemory == (uintptr_t)NULL ){
								if( comMemoryManager.AllocPageWithWait( pc_Image->c_ImageInfo.ul_ImageProcessID, pc_Image->c_ImageInfo.e_ImageType, pc_Image, pcImageImpColor->ul_CompressSize, True ) != IMGD_ImgOk ){
									if( comMemoryManager.isHDDReady() == True ){
										// Swap領域不足なので待つ.
									} else {
										// メモリ不足.
										THRL_ThAssert( False, "chkEnableFileAllocExec alloc error!" , 0, 0, 0, 0, CFA14_DetailCode0x03EF );
									}
									b_Ans = False;
									_dbg_setChkTransExecNGPoint( 112 );
									break;
								}
							}
						}
					}
					if( b_Ans == True ){
						b_Ans = chkEnableCompress( pc_LocalOneExpandMode, pcc_OneImgTransInfo );
					}
				}
				break;
			case THRE_ThrID_FileToBuf:
				// CQ-311887 先行変倍対象の場合は、先行変倍後のファイルメモリ確保チェックを行う.
				if( pcc_OneImgTransInfo->en_ThreadImgProcMode == THRE_ImgProcMode_PreConvert			// 一次伸張での変換.
					|| theModeInfoLib.getOverlayType( rs_ThreadComPara ) == THRE_OverlayType_Binarize ){// または2値化オーバーレイ.
					// CQ-311887 先行変倍対象は、FileToBufの画像変換前モード.
					if( chkPreCnvMode( rs_ThreadComPara ) == True ){
						// CQ-311887 先行変倍対象.
						DOCC_Leaf* pc_PreCnvLeaf = getPreCnvLocalLeaf();
						if( pc_PreCnvLeaf != NULL ){
							IMGC_Image* pc_PreCnvImage = pc_PreCnvLeaf->getImage();
							THRL_ThAssert( (pc_PreCnvImage!=NULL), "chkEnableFileAllocExec pc_PreCnvImage NULL error!" , 0, 0, 0, 0, CFA14_DetailCode0x094f );
							// 確保済みでない場合のみメモリ確保チェックをする.
							if( pc_PreCnvImage->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL ){
								if( comMemoryManager.AllocPageWithWait( pc_PreCnvImage->c_ImageInfo.ul_ImageProcessID, pc_PreCnvImage->c_ImageInfo.e_ImageType, pc_PreCnvImage, pc_PreCnvImage->m_IMGC_ImageImp->ul_CompressSize, True ) != IMGD_ImgOk ){
									if( comMemoryManager.isHDDReady() == True ){
										// CQ-311887 Swap領域不足なので待つ.
									} else {
										// CQ-311887 メモリ不足.
										THRL_ThAssert( False, "chkEnableFileAllocExec PreCnv alloc error!" , 0, 0, 0, 0, CFA14_DetailCode0x03F0 );
									}
									b_Ans = False;
								}
								if( b_Ans == True ){
									// CQ-311887 変倍後の圧縮用ファイルメモリ確保チェック.
									b_Ans = chkEnableCompress( pcc_OneImgTransInfo, pc_PreCnvLeaf, False );
									if( (b_Ans == True) && (pcc_OneImgTransInfo->ul_usedFileMem > 0) ){
										ul_usedFileMem = pcc_OneImgTransInfo->ul_usedFileMem;
										s_WaitResState.ul_File[ pcc_OneImgTransInfo->e_MPID ] += ul_usedFileMem;
									}
								}
							}
						}else{
							// CQ-311887 先行変倍時に先行変倍用のローカルLeafがなければAssert.
							THRL_ThAssert( False, "chkEnableFileAllocExec pc_PreCnvLeaf Null error!" , 0, 0, 0, 0, CFA14_DetailCode0x03F1 );
						}
					}
				}
				if( b_Ans == False ){
					_dbg_setChkTransExecNGPoint( 140 );
					break;
				}else{
					// ここではbreakしない.
				}
			case THRE_ThrID_FileToApp:
				// 伸張側.
				pc_LocalOneExpandMode = CC_ImgTransInfoSingletonIf::newInstance().getLocalOneExpandMode( pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara );
				if( pc_LocalOneExpandMode->bl_ExpandInComp == True ){
					// 圧縮伸張同期モード中は、OnMemoryで動作するのでチェックしない.
					b_Ans = True;
				} else {
					// 伸張用のFileMemoryが確保できる、または既にメモリ上にあるかチェック.
					b_Ans = chkEnableExpand( pc_LocalOneExpandMode, pcc_OneImgTransInfo );
					// CQ-311887 確保可能且つ先行変倍がある場合はファイルメモリの使用サイズを変更する.
					if( (b_Ans == True) && (pcc_OneImgTransInfo->ul_usedFileMem == 0) && (ul_usedFileMem != 0) ){
						pcc_OneImgTransInfo->ul_usedFileMem += ul_usedFileMem;
					}
					if( ul_usedFileMem != 0 ){
						s_WaitResState.ul_File[ pcc_OneImgTransInfo->e_MPID ] -= ul_usedFileMem;
					}
				}
				break;
			default:
				// FileMemory確保チェックは必要なし。.
				break;
		}
	}
	
	comMemoryManager.semGive_FileMemAlloc( THRD_SemLog_MultiThread_chkEnableFileAllocExec );

	return ( b_Ans );
}

// ================================================================================================.
//! <!--機能--> 【内部関数】ファイルメモリ確保.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... ファイルメモリを確保する管理情報.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  06/09/08 yokoi	 新規作成.
//  07/05/08 yokoi	 semTake/semGiveが対になっていなかったのを修正(takeしていないのにgiveする事があった).
//  07/09/25 yokoi	 伸張用に確保する際、上位のOEM情報を元に確保してしまっていた問題を修正.
//  08/10/18 takamoto	CQ-311887 先行変倍用のファイルメモリ確保処理を追加.
//  09/03/12 安田 Linux新規実装.
//  09/07/03 世古 Emperorプリント1200dpi対応：オーバーレイ.
//	14/06/02 ogura		CQ.390862 セマフォログ追加.
//  14/05/09 山下(日立JTE) 次世代アーキ スワップ分割読出対応.
//	15/06/05 伊藤史. CQ512749 同時両面ファイルメモリ事前確保対応.
//	15/09/28 下垣. CQ516737 516889 同時両面読み込み表紙あり時にページのペアリングがずれる不具合対応.
//	15/10/26 Sky		システム統合SoC(S800)対応.
//  17/04/26 日立       OP/PP共通化 工程スキャン対応.
//  17/05/19 Sky PP Fiery+両面出力対応 OP/PP共通化.ページモード時のファイルメモリ確保処理のスキップ.
// ================================================================================================.
Bool CC_MultiThreadProfile::AllocFileMemory( const ST_ThreadComPara& rs_ThreadComPara, CC_OneImgTransInfo* pcc_OneImgTransInfo )
{
	//2009/03/30 newInstance対応 comMemoryManagerのインスタンス生成.
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();

	Bool b_Ret = True;	// 便宜上、確保できたかどうかの戻り値を用意しているが、確保失敗は今のところ考慮しない。.
	ushort usIdx = 0;
	short ss_DupPage = 0;

	// OP/PP共通化 工程スキャン対応.
	if( NULL == pcc_OneImgTransInfo ){
		return( False );
	}
	
	// OP/PP共通化 工程スキャン対応. ＆　ページモード対応.
	if( ( THRE_AppID_RawImageScan== pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread )
	 || ( True == rs_ThreadComPara.b_isPageMode) ){
		// アプリケーションIDが工程スキャン時はファイルメモリ確保しないので即リターンする.
		return( b_Ret );
	}

	if( pcc_OneImgTransInfo->ul_usedFileMem > 0 ){
		// FileMemoryの操作を行うので、セマフォロック.
		comMemoryManager.semTake_FileMemAlloc( WAIT_FOREVER, THRD_SemLog_MultiThread_AllocFileMemory );
		// ★注意！以下の、確保するスレッドIDを変更する際は、chkEnableFileAllocExec()の確保サイズ確定するスレッドIDも変更する事！.
		if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ){
			///////////////// 入力の時 ///////////////.
			// 圧縮シーケンス.
			THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf != NULL), "AllocRes OIP error" , 0, 0, 0, 0, CFA14_DetailCode0x03F2 );
			THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() != NULL ), "CC_MultiThreadProfile::AllocFileMemory(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x03F3 );
			switch( pcc_OneImgTransInfo->en_ThreadID ){
#ifdef COSIM
				case THRE_ThrID_BufToFile:// Cosim検証のため。.
#endif
				case THRE_ThrID_AppToBuf:// 入力の時点で確保しておく.
				case THRE_ThrID_AppToFile:
					comMemoryManager.AllocCompressImage( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
					break;
				case THRE_ThrID_ExtToBuf:// 入力の時点で確保しておく.
					// ファイルメモリ確保タイミング変更有効/無効判定.
					if( True == isAllocFileMemoryTimingChange() ){
						// ファイルメモリ確保タイミング変更有効.
						if( pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_InputIRDup ){
							// 裏面IR入力の場合は、確保しない.
						}else{
							// 表面IR入力/Fiery入力の場合、確保する.
							comMemoryManager.AllocCompressImage( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
						}
					}else{
						// 2015/06/05 伊藤史. CQ512749 同時両面ファイルメモリ事前確保対応.
						if( True == rs_ThreadComPara.b_1PassDuplexJob ){
							// 同時両面.
							if( True == isPreAllocFilemem( pcc_OneImgTransInfo->ul_JobID, pcc_OneImgTransInfo->ss_InPageID, pcc_OneImgTransInfo->en_ThreadID ) ){
								// 事前確保済み.
								assignPreAllocFilemem( pcc_OneImgTransInfo->ul_JobID, pcc_OneImgTransInfo->ss_InPageID, pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
							} else {
								// 2面の確保.
								comMemoryManager.AllocCompressImage( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
								ss_DupPage = pcc_OneImgTransInfo->ss_InPageID;
								if ( THRE_TaskID_InputIRDup == pcc_OneImgTransInfo->en_TaskID ) {
									// 裏面の場合はページ番号を減算.
									ss_DupPage--;
								} else if ( THRE_TaskID_InputIR == pcc_OneImgTransInfo->en_TaskID ) {
									// 表面の場合はページ番号を加算.
									ss_DupPage++;
								}
								preAllocFilemem( pcc_OneImgTransInfo->ul_JobID, ss_DupPage, pcc_OneImgTransInfo->en_ThreadID,
									rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->m_IMGC_ImageImp->e_MPID, 
									rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->m_IMGC_ImageImp->ul_CompressSize );
							}
						} else {
							comMemoryManager.AllocCompressImage( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
						}
					}
					break;
				case THRE_ThrID_BufToFile:
					if( IMGE_BlockSizeConvertStatePushImage == IMGG_getBlockSizeConvertRestoreDataState() ){
						comMemoryManager.AllocCompressImage( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() );
						break;
					}
					// ファイルメモリ確保タイミング変更有効/無効判定.
					if( True == isAllocFileMemoryTimingChange() ){
						if( pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_InputIRDup ){
							// 裏面IR入力の場合は、BufToFileのタイミングで確保する.
							IMGC_Image* pc_Image = rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage();
							comMemoryManager.AllocCompressImage( pc_Image );
							THRL_SetThLog( 644, THRE_DebugLogType_ThCtrLog, 0, False, pcc_OneImgTransInfo->en_ThreadID, pcc_OneImgTransInfo->en_TaskID, 
								                (uintptr_t)&(pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory) ,
								                	pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory.getMemSize());
						}else{
							// 表面IR入力/Fiery入力の場合は、既にExtToBufの時点で確保済み.
						}
					}
					break;
				default:
					THRL_ThAssert( False, "AllocResource File Thid error ThId %d", pcc_OneImgTransInfo->en_ThreadID , 0, 0, 0, CFA14_DetailCode0x03F4 );
					break;
			}
		} else {
			///////////// 出力のとき /////////////////.
			register CC_OneExpandMode* pc_LocalOneExpandMode = CC_ImgTransInfoSingletonIf::newInstance().getLocalOneExpandMode( pcc_OneImgTransInfo->en_ThreadID, rs_ThreadComPara );;
			switch( pcc_OneImgTransInfo->en_ThreadID ){
				case THRE_ThrID_BufToFile:
					// 圧縮する全ページのメモリ確保.
					for( usIdx=0; usIdx < InputPageNumMax ; usIdx++ )
					{
						//  メモリ確保サイズ計算時に利用したイメージ分のメモリ確保 (NULLチェックはisImageOnMemory2()で行う).
						if( (pc_LocalOneExpandMode->III[usIdx].pOIP != NULL) 
							&& (pc_LocalOneExpandMode->III[usIdx].pOIP->getImage() != NULL) ){
							IMGC_Image* pc_Image = pc_LocalOneExpandMode->III[usIdx].pOIP->getImage();
							// 1バンド目、かつ、確保済みでないイメージのみチェックする.
							if( (pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) 
								&& ((pcc_OneImgTransInfo->us_StartTransNum == 0) || (pcc_OneImgTransInfo->bl_PageTrans == True) ) ){
								// 圧縮するアレイ分のメモリを確保.
								comMemoryManager.AllocCompressImage( pc_Image );
							}
						}
					}
					break;
				case THRE_ThrID_FileToBuf:
					// 伸張シーケンス.
					// 伸張する全ページのメモリ確保.
					for( usIdx=0; usIdx < InputPageNumMax ; usIdx++ )
					{
						//  メモリ確保サイズ計算時に利用したイメージ分のメモリ確保 (NULLチェックはisImageOnMemory2()で行う).
						if( (pc_LocalOneExpandMode->III[usIdx].pOIP != NULL) 
							&& (pc_LocalOneExpandMode->III[usIdx].pOIP->getImage() != NULL) ){
							IMGC_Image* pc_Image = pc_LocalOneExpandMode->III[usIdx].pOIP->getImage();

							// メモリ上に無い、かつ、確保済みでないイメージのみチェックする.
							if( (comMemoryManager.isImageOnMemory( pc_Image ) == False) && (pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) )
							{
								// mod-oikawa WP522 str.
								// WP:522
								if( THRE_ImgProcMode_PreConvert == pcc_OneImgTransInfo->en_ThreadImgProcMode
									&& True == pcc_OneImgTransInfo->b_SplitTrans ) {
									// 1次伸張で分割読み出しであるとき
									// 画像サイズを保持する
									uint32_t ul_tempSize = 0;
									ul_tempSize = pc_Image->m_IMGC_ImageImp->ul_CompressSize;
									
									// 分割転送フラグがONの場合、ファイルメモリからの確保サイズを (4バンド+SSD保存単位)×2 に変更する.
									pc_Image->m_IMGC_ImageImp->ul_CompressSize = (getBandImageSize( pc_Image, DEF_CmpExpLineUnit, chk1200DpiWrapInOut( rs_ThreadComPara ) ) + IMGD_SSDWorkingArraySize) * 2;

									// ログ追加.
									setDebugLowSpeedSeq( 825, pc_Image->m_IMGC_ImageImp->ul_CompressSize );

									// 2部目はSplitの画像状態が残るため、リリースをしておく.
									pc_Image->m_IMGC_ImageImp->releaseWorkingArray( pc_Image );	

									// 伸張するアレイ分のメモリを確保.
									comMemoryManager.AllocExpandImage( pc_Image );

									// 画像サイズを戻す
									pc_Image->m_IMGC_ImageImp->ul_CompressSize = ul_tempSize;
									
									// 分割転送フラグがONの場合、転送作業用アレイの初期化(確保)を行う
									// (4バンド+SSD保存単位)×2をサイズとして渡す
									pc_Image->m_IMGC_ImageImp->allocWorkingArray( pc_Image, (getBandImageSize( pc_Image, DEF_CmpExpLineUnit, chk1200DpiWrapInOut( rs_ThreadComPara ) ) + IMGD_SSDWorkingArraySize) * 2 );
									
								} else {
									// 分割読み出しでないとき
									// 伸張するアレイ分のメモリを確保.
									comMemoryManager.AllocExpandImage( pc_Image );
								}
								// mod-oikawa WP522 end.
							}
						}
					}
					// オーバーレイが設定されている場合、Form画像のメモリ確保.
					if( theModeInfoLib.chkExecMode( THRE_ChkMode_OverLay, *pc_LocalOneExpandMode ) == True ){
						IMGC_Image* pc_Image = pc_LocalOneExpandMode->s_OverLayInfo.pc_Leaf->getImage();
						// メモリ上に無い、かつ、確保済みでないイメージのみチェックする.
						if( (comMemoryManager.isImageOnMemory( pc_Image ) == False) && (pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) ){
							// 伸張するアレイ分のメモリを確保.
							comMemoryManager.AllocExpandImage( pc_Image );
						}
					}
					// CQ-311887 先行変倍用のファイルメモリ確保.
					if( pcc_OneImgTransInfo->en_ThreadImgProcMode == THRE_ImgProcMode_PreConvert			// 一次伸張時の変換.
						|| theModeInfoLib.getOverlayType( rs_ThreadComPara ) == THRE_OverlayType_Binarize ){// または2値化オーバーレイ.
						// CQ-311887 先行変倍対象は、FileToBufの画像変換前モード.
						if( chkPreCnvMode( rs_ThreadComPara ) == True ){
							// CQ-311887 先行変倍対象.
							DOCC_Leaf *pc_PreCnvLeaf = getPreCnvLocalLeaf();
							THRL_ThAssert( pc_PreCnvLeaf != NULL, "AllocFileMemory pc_PreCnvLeaf Null error!" , 0, 0, 0, 0, CFA14_DetailCode0x03F5 );
							IMGC_Image* pc_PreCnvImage = pc_PreCnvLeaf->getImage();
							THRL_ThAssert( pc_PreCnvImage != NULL, "AllocFileMemory pc_PreCnvImage Null error!" , 0, 0, 0, 0, CFA14_DetailCode0x03F6 );
							// CQ-311887 メモリ上に無い、かつ、確保済みでないイメージのみチェックする.
							if( (pc_PreCnvImage->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) 
								&& ((pcc_OneImgTransInfo->us_StartTransNum == 0) || (pcc_OneImgTransInfo->bl_PageTrans == True) ) ){
								// CQ-311887 圧縮するアレイ分のメモリを確保.
								comMemoryManager.AllocCompressImage( pc_PreCnvImage );
							}
						}
					}
					break;
				case THRE_ThrID_FileToApp:
					// 伸張シーケンス.
					// 伸張する全ページのメモリ確保.
					for( usIdx=0; usIdx < InputPageNumMax ; usIdx++ )
					{
						//  メモリ確保サイズ計算時に利用したイメージ分のメモリ確保 (NULLチェックはisImageOnMemory2()で行う).
						if( (pc_LocalOneExpandMode->III[usIdx].pOIP != NULL) 
							&& (pc_LocalOneExpandMode->III[usIdx].pOIP->getImage() != NULL) ){
							IMGC_Image* pc_Image = pc_LocalOneExpandMode->III[usIdx].pOIP->getImage();
							// メモリ上に無い、かつ、確保済みでないイメージのみチェックする.
							if( (comMemoryManager.isImageOnMemory( pc_Image ) == False) && (pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) )
							{
								// 伸張するアレイ分のメモリを確保.
								comMemoryManager.AllocExpandImage( pc_Image );
							}
						}
					}
					break;
				default:
					THRL_ThAssert( False, "AllocResource File Thid error ThId %d", pcc_OneImgTransInfo->en_ThreadID , 0, 0, 0, CFA14_DetailCode0x03F7 );
					break;
			}
		}
		// 必要な分は無くなった.
		pcc_OneImgTransInfo->ul_usedFileMem = 0;
		// FileMemoryの操作が終わったので、セマフォを開放する.
		comMemoryManager.semGive_FileMemAlloc( THRD_SemLog_MultiThread_AllocFileMemory );
	}

	return( b_Ret );
}

// ================================================================================================.
//! <!--機能--> 【内部関数】同時両面ファイルメモリ事前確保.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uint32_t ul_JobID ... 事前確保ファイルメモリ識別用.
//! \param short ss_InPageID ... 事前確保ファイルメモリ識別用.
//! \param THRE_ThrID en_ThreadID ... 事前確保ファイルメモリ識別用.
//! \param EN_MPID e_MPID ... 事前確保ファイルメモリ ID.
//! \param uint32_t ul_CompressSize ... 事前確保ファイルメモリサイズ.
//! <!--戻値-->.
//! \return  Bool  True=事前確保成功, False=事前確保失敗.
//! <!--詳細-->.
//! <!--履歴-->.
//!  2015/06/05 伊藤史 新規作成. CQ512749 同時両面ファイルメモリ事前確保対応.
// ================================================================================================.
Bool CC_MultiThreadProfile::preAllocFilemem( uint32_t ul_JobID, short ss_InPageID, THRE_ThrID en_ThreadID, EN_MPID e_MPID, uint32_t ul_CompressSize )
{
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();
	ushort	us_cnt = 0;
	ushort	us_index = us_ThreadPreAllocFilememIndex;
	Bool	b_ret = False;

	for( us_cnt=0; us_cnt<THRE_PREFILEALLOC_MAX; us_cnt++ ){
		us_index++;		// ログに残すため、最新の次から使用.
		if( THRE_PREFILEALLOC_MAX <= us_index ){
			us_index = 0;
		}
		if( (THRE_PREFILEALLOC_NONE == st_ThreadPreAllocFilemem[us_index].uc_state) ||
			(THRE_PREFILEALLOC_ASSIGNE == st_ThreadPreAllocFilemem[us_index].uc_state) ||
			(THRE_PREFILEALLOC_CANCEL == st_ThreadPreAllocFilemem[us_index].uc_state) ){
			// 未使用 -> 事前確保する.
			st_ThreadPreAllocFilemem[us_index].ul_tick = SYSF_tickGet();
			st_ThreadPreAllocFilemem[us_index].e_MPID = e_MPID;
			st_ThreadPreAllocFilemem[us_index].cc_Array = comMemoryManager.preAllocCompressImage( e_MPID, ul_CompressSize );
			st_ThreadPreAllocFilemem[us_index].ul_CompressSize = st_ThreadPreAllocFilemem[us_index].cc_Array.getMemSize();
			st_ThreadPreAllocFilemem[us_index].pc_Image = NULL;
			st_ThreadPreAllocFilemem[us_index].en_ThreadID = en_ThreadID;
			st_ThreadPreAllocFilemem[us_index].ul_JobID = ul_JobID;
			st_ThreadPreAllocFilemem[us_index].ss_InPageID = ss_InPageID;
			st_ThreadPreAllocFilemem[us_index].uc_state = THRE_PREFILEALLOC_PREALLOC;
			us_ThreadPreAllocFilememIndex = us_index;
			b_ret = True;
			break;
		}
	}
	return b_ret;
}

// ================================================================================================.
//! <!--機能--> 【内部関数】同時両面ファイルメモリ事前確保確認.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uint32_t ul_JobID ... 事前確保ファイルメモリ識別用.
//! \param short ss_InPageID ... 事前確保ファイルメモリ識別用.
//! \param THRE_ThrID en_ThreadID ... 事前確保ファイルメモリ識別用.
//! <!--戻値-->.
//! \return  Bool  True=事前確保有り, False=事前確保無し.
//! <!--詳細-->.
//! <!--履歴-->.
//!  2015/06/05 伊藤史 新規作成. CQ512749 同時両面ファイルメモリ事前確保対応.
// ================================================================================================.
Bool CC_MultiThreadProfile::isPreAllocFilemem( uint32_t ul_JobID, short ss_InPageID, THRE_ThrID en_ThreadID )
{
	ushort	us_cnt = 0;
	ushort	us_index = us_ThreadPreAllocFilememIndex;
	Bool	b_ret = False;

	for( us_cnt=0; us_cnt<THRE_PREFILEALLOC_MAX; us_cnt++ ){
		if( (st_ThreadPreAllocFilemem[us_index].ul_JobID == ul_JobID) &&
			(st_ThreadPreAllocFilemem[us_index].ss_InPageID == ss_InPageID) &&
			(st_ThreadPreAllocFilemem[us_index].en_ThreadID == en_ThreadID) &&
			(THRE_PREFILEALLOC_PREALLOC == st_ThreadPreAllocFilemem[us_index].uc_state) ){
			b_ret = True;
			break;
		}
		us_index++;
		if( THRE_PREFILEALLOC_MAX <= us_index ){
			us_index = 0;
		}
	}
	return b_ret;
}

// ================================================================================================.
//! <!--機能--> 【内部関数】事前確保ファイルメモリ割当.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uint32_t ul_JobID ... 事前確保ファイルメモリ識別用.
//! \param short ss_InPageID ... 事前確保ファイルメモリ識別用.
//! \param THRE_ThrID en_ThreadID ... 事前確保ファイルメモリ識別用.
//! \param IMGC_Image* pc_Image ... 割当先 pc_Image.
//! <!--戻値-->.
//! \return  Bool  True=事前確保有り, False=事前確保無し.
//! <!--詳細-->.
//! <!--履歴-->.
//!  2015/06/05 伊藤史 新規作成. CQ512749 同時両面ファイルメモリ事前確保対応.
// ================================================================================================.
Bool CC_MultiThreadProfile::assignPreAllocFilemem( uint32_t ul_JobID, short ss_InPageID, THRE_ThrID en_ThreadID, IMGC_Image* pc_Image )
{
	ushort	us_cnt = 0;
	ushort	us_index = us_ThreadPreAllocFilememIndex;
	Bool	b_ret = False;

	for( us_cnt=0; us_cnt<THRE_PREFILEALLOC_MAX; us_cnt++ ){
		if( (st_ThreadPreAllocFilemem[us_index].ul_JobID == ul_JobID) &&
			(st_ThreadPreAllocFilemem[us_index].ss_InPageID == ss_InPageID) &&
			(st_ThreadPreAllocFilemem[us_index].en_ThreadID == en_ThreadID) &&
			(THRE_PREFILEALLOC_PREALLOC == st_ThreadPreAllocFilemem[us_index].uc_state) ){
			// 事前確保有り.
			st_ThreadPreAllocFilemem[us_index].pc_Image = pc_Image;
			pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory = st_ThreadPreAllocFilemem[us_index].cc_Array;
			st_ThreadPreAllocFilemem[us_index].uc_state = THRE_PREFILEALLOC_ASSIGNE;
			st_ThreadPreAllocFilemem[us_index].ul_tick = SYSF_tickGet();
			b_ret = True;
			if( 0 < us_debug_WorkingArrayLog ){
				debug_Set_workArrayDebugLog( 98, (uintptr_t)pc_Image, (uintptr_t)(pc_Image->m_IMGC_ImageImp), ss_InPageID, st_ThreadPreAllocFilemem[us_index].ul_CompressSize );
			}
			break;
		}
		us_index++;
		if( THRE_PREFILEALLOC_MAX <= us_index ){
			us_index = 0;
		}
	}
	return b_ret;
}

// ================================================================================================.
//! <!--機能--> 【内部関数】事前確保ファイルメモリの解放.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uint32_t ul_JobID ... 事前確保ファイルメモリ識別用.
//! <!--戻値-->.
//! \return  無し.
//! <!--詳細-->.
//!		指定された JobID の事前確保ファイルメモリ（未割当のもの）を解放する.
//! <!--履歴-->.
//!  2015/06/05 伊藤史 新規作成. CQ512749 同時両面ファイルメモリ事前確保対応.
// ================================================================================================.
void CC_MultiThreadProfile::cancelPreAllocFilemem( uint32_t ul_JobID )
{
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();
	ushort	us_cnt = 0;

	for( us_cnt=0; us_cnt<THRE_PREFILEALLOC_MAX; us_cnt++ ){
		if( (ul_JobID == st_ThreadPreAllocFilemem[us_cnt].ul_JobID) &&
			(THRE_PREFILEALLOC_PREALLOC == st_ThreadPreAllocFilemem[us_cnt].uc_state) ){
			// 事前確保有り.
			comMemoryManager.freeArray( st_ThreadPreAllocFilemem[us_cnt].cc_Array, st_ThreadPreAllocFilemem[us_cnt].e_MPID );
			st_ThreadPreAllocFilemem[us_cnt].uc_state = THRE_PREFILEALLOC_CANCEL;
			st_ThreadPreAllocFilemem[us_cnt].ul_tick = SYSF_tickGet();
			if( 0 < us_debug_WorkingArrayLog ){
				debug_Set_workArrayDebugLog( 99, 0, 0, ul_JobID, st_ThreadPreAllocFilemem[us_cnt].ss_InPageID );
			}
		}
	}
}
	
