// ================================================================================================.
//! <!--機能--> 【内部関数】リソース予約.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... リソースを予約する管理情報.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  05/05/30 yokoi	 新規作成.
//  06/09/08 yokoi	 ファイルメモリは、予約時は確保するように処理を追加.
//	14/06/02 ogura	 CQ.390862 セマフォログ追加.
// ================================================================================================.
Bool CC_MultiThreadProfile::ReserveResource( const ST_ThreadComPara& rs_ThreadComPara, CC_OneImgTransInfo* pcc_OneImgTransInfo )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "ReserveResource OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03F8 );
	THRL_ThAssert( (pcc_OneImgTransInfo->b_IsReservedResource == False), "ReserveResource duplicated" , 0, 0, 0, 0, CFA14_DetailCode0x03F9 );
	Bool b_Ret = False;
	ushort us_Index = 0;

	// DMAリソース予約.
	for( us_Index = 0; us_Index < THRD_MAX_DMA_USE; us_Index++ ){
		if( pcc_OneImgTransInfo->e_usedDma[us_Index] != THRE_DmaId_None ){
			b_Ret = pc_DmaResMan[pcc_OneImgTransInfo->e_usedDma[us_Index]]->reserve( pcc_OneImgTransInfo );
			THRL_ThAssert( b_Ret, "ReserveResource Dma error" , 0, 0, 0, 0, CFA14_DetailCode0x03FA );
		}
	}

	// バッファリソース予約.
	for( us_Index = 0; us_Index < THRD_MAX_BUF_USE; us_Index++ ){
		if( pcc_OneImgTransInfo->s_usedBuf[us_Index].e_usedBuf != THRE_BufId_None ){
			b_Ret = pc_BufResMan[pcc_OneImgTransInfo->s_usedBuf[us_Index].e_usedBuf]->reserve( pcc_OneImgTransInfo, pcc_OneImgTransInfo->s_usedBuf[us_Index].b_isWrite );
			THRL_ThAssert( b_Ret, "ReserveResource Buf error" , 0, 0, 0, 0, CFA14_DetailCode0x03FB );
		}
	}

	// 2006/09/08 yokoi add ファイルメモリは、一つ前のスレッドが終わってもリソースが空かない可能性があるので、しっかり確保しておく.
	AllocFileMemory( rs_ThreadComPara, pcc_OneImgTransInfo );

	// リソース予約フラグを立てる.
	pcc_OneImgTransInfo->b_IsReservedResource = True;

	return ( b_Ret );
}

/*================================================================================================
［機能］	【内部関数】禁止組み合わせチェック処理（バッファ確保要否とモード選択）
--------------------------------------------------------------------------------------------------
［引数］
	CC_OneImgTransInfo* : 画像転送管理情報へのポインタ
	Bool& bl_ReqAllocBuf（出力） : バッファメモリ確保要否　True：確保必要、False：不要
	Bool& bl_PreAllocEnable（出力） : 予測制御の可否　True：予測確保制御可能、False：不可能　
［戻値］
	Bool True:動作可能、False：動作禁止
［詳細］ 
［ｳｫｰｸｽﾙｰ］	実施未：2003/4/1：morikawa
［履歴］	05/05/17 yokoi Mosel用に修正
================================================================================================*/
Bool CC_MultiThreadProfile::chkAllocBufSelMode( CC_OneImgTransInfo* pcc_OneImgTransInfo, Bool& bl_ReqAllocBuf, Bool& bl_PreAllocEnable )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkAllocBufSelMode OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03FC );

#if 1
	// バッファを利用していれば.
	if( pcc_OneImgTransInfo->s_usedBuf[0].e_usedBuf != THRE_BufId_None ){
		bl_ReqAllocBuf = True;
	} else {
		bl_ReqAllocBuf = False;
	}
	bl_PreAllocEnable = False;

	return True;
#else
	struct ST_SelAllocBuf {
		uchar 				uc_chkElementNum;		// 検索要素数（いくつまで検索するか).
		// ★入力.
		THRE_TaskID			en_ThreadID;			// スレッドID.
		THRE_AppID	en_AppIDSelThread;		// アプリ種類.
		EN_ThreadImgProcMode	en_ThreadImgProcMode;	// 画像処理モード.
		Bool	bl_ModeFileNonStore;	// ファイルメモリに入れないモード.
		// ★出力.
		THRE_BufId	e_BufId[THRD_MAX_BUF_USE];	// バッファID.
		Bool	bl_ReqAllocBuf;			// バッファメモリ確保要否　True：確保必要、False：不要.
		Bool	bl_PreAllocEnable;		// 予測制御の可否　True：予測確保制御可能、False：不可能.
		EN_BufModePageBand	en_BufModePageBand;			// バッファメモリ確保ページバンドモード.
		EN_BufStatContDisCont	en_BufStatContDisCont;	// バッファ連続or不連続確保状態.
		EN_BufAllocKind			en_BufAllocKind;		// バッファ確保種類.
	};
	static ST_SelAllocBuf st_SelTbl[] = {
	// 外部→バッファメモリ.
		{ 2, THRE_ThrID_ExtToBuf, THRE_AppID_Copy, 0, 0, 
		{THRE_BufId_Main, THRE_BufId_Main_Combine, THRE_BufId_Main_CombineJimon, THRE_BufId_Main_Rot,THRE_BufId_None},
		True, False, EN_BufInPageOutPage, EN_BufDisContWait, EN_BufAllocPageArray },
	// 外部→ファイルメモリ.
	// 外部→バッファ＆ファイルメモリ.
	// バッファメモリ→ファイルメモリ.
	// ＩＲ→外部メモリメモリ.
	// アプリ→バッファメモリ.
	// アプリ→ファイルメモリ.
	// アプリ→バッファ＆ファイルメモリ.
	// ファイルメモリ→バッファメモリ.
		// 内部プリントアプリ（通常プリント、画像処理モードを一時的に変更して判断する）.
		// 内部JPEGプリントアプリ（通常プリントのみ）.
		// 内部プリントアプリ（Boxプリント、画像処理モードを一時的に変更して判断する）.
		// FAX受信.
	// バッファメモリ→外部.
	// バッファメモリ→バッファメモリ.
		// 内部スキャン、ＪＰＥＧ.
		// 内部プリント、ＢＴＣ伸張.
		// 内部スキャン、ＢＴＣ伸張.
		// ＦＡＸ、解像度変換.
		// 内部プリント、ＣＰＳ経由ＢＴＣ圧縮　フルバッファとする.
	// バッファメモリ→アプリ.
	// ファイル→アプリ.
	// アプリ→アプリ.
	// 外部メモリ→外部.
	};		
	// 検索対象となるモードテーブル設定.
	ST_SelAllocBuf st_ChkTbl;
	// スレッド選択共通設定.
	st_ChkTbl.en_ThreadID = pcc_OneImgTransInfo->en_ThreadID;
	st_ChkTbl.en_AppIDSelThread = pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread;
	st_ChkTbl.en_ThreadImgProcMode = pcc_OneImgTransInfo->en_ThreadImgProcMode;
	st_ChkTbl.bl_ModeFileNonStore = bl_ModeFileNonStore;
	
	Bool bl_Ans = True;	// 戻り値を正常終了で初期化.
	ushort i = 0;
	for( i=0; i<sizeof(st_SelTbl)/sizeof(ST_SelAllocBuf); ++i ) {
		uchar uc_chkNum = st_SelTbl[i].uc_chkElementNum;	// 検索回数代入.
		if( st_ChkTbl.en_ThreadID == st_SelTbl[i].en_ThreadID ) {
			if( --uc_chkNum == 0 ) break;
			if( st_ChkTbl.en_AppIDSelThread == st_SelTbl[i].en_AppIDSelThread ) {
				if( --uc_chkNum == 0 ) break;
				if( st_ChkTbl.en_ThreadImgProcMode == st_SelTbl[i].en_ThreadImgProcMode ) {
					if( --uc_chkNum == 0 ) break;
					if( st_ChkTbl.bl_ModeFileNonStore == st_SelTbl[i].bl_ModeFileNonStore ) {
						break;
					}
				}		
			}
		}
	}

	// 見つからなかった場合にはアサート.
	THRL_ThAssert( (i < sizeof(st_SelTbl)/sizeof(ST_SelAllocBuf)), "ST_SelAllocBuf Error" , 0, 0, 0, 0, CFA14_DetailCode0x03FD );

	// スレッド選択決定値格納.
	bl_ReqAllocBuf = st_SelTbl[i].bl_ReqAllocBuf; 
	bl_PreAllocEnable = st_SelTbl[i].bl_PreAllocEnable; 
	pcc_OneImgTransInfo->en_BufModePageBand = st_SelTbl[i].en_BufModePageBand;
	pcc_OneImgTransInfo->en_BufStatContDisCont = st_SelTbl[i].en_BufStatContDisCont;
	pcc_OneImgTransInfo->en_BufAllocKind = st_SelTbl[i].en_BufAllocKind;
	for( i = 0; i < THRD_MAX_BUF_USE; i++ ){
		pcc_OneImgTransInfo->s_usedBuf[i].e_usedBuf = st_SelTbl[i].e_BufId[i];
	}

// 2004/06/18 伊藤(史) バッファメモリ確保・開放ログ start.
	dbgBufMemLogWrite(pcc_OneImgTransInfo->en_BufStatContDisCont+10,(uintptr_t)pcc_OneImgTransInfo,0);		//10-14.
// 2004/06/18 伊藤(史) バッファメモリ確保・開放ログ end.
	return( bl_Ans );
#endif
}
/*================================================================================================
［機能］	【内部関数】禁止組み合わせチェック処理（バッファページバンドモード動作可否チェック）
--------------------------------------------------------------------------------------------------
［引数］
	CC_OneImgTransInfo* : 画像転送管理情報へのポインタ
	ST_ThreadComPara	:スレッド共通パラメータ
［戻値］
	Bool True:動作可能、False：動作禁止
［詳細］起動しようとするスレッドが入力のスレッドでかつバンドで入力してページで出力時に
	現在動作中のその他のスレッドでバンドで入力してページで出力がないかどうかチェックし、なければOK
［ｳｫｰｸｽﾙｰ］	実施未：2003/4/1：morikawa
［履歴］	04/06/09：arakawa 不要な処理を削除 
================================================================================================*/
Bool CC_MultiThreadProfile::chkPageBandMode( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool bl_Ans = True;	
	// 03/09/01 morikawa タスク層デバッグ待ち.
	// 起動しようとするスレッドが入力の判断必要であるが.
	// これを入れると、ファイル→バッファの画像転送開始の２回目がスレッドに来るが.
	// この時にバッファ→バッファのＢＴＣ伸張の画像転送パラメータの画像処理モードを書き換えてしまい例外発生するため.
	// 暫定で処理を変更しておく.
	// 03/09/09 morikawa タスク層が修正されたので正式仕様投入.
	// 伸張のためにFileMemoryの空きをまっている場合は、確保しているFileMemoryを使いきるように、ここでは制限をかけない判定を追加 05/03/10 yokoi mod.
	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL && pcc_OneImgTransInfo->en_BufModePageBand == EN_BufInBandOutPage ) {
		if( CC_ImgTransInfoSingletonIf::newInstance().chkBusyBufInPageOutPage( pcc_OneImgTransInfo ) == True ) {
			bl_Ans = False;	// 動作不可.
			_dbg_setChkTransExecNGPoint( 14 );	// 【修正:橋本昌】2004/05/28 デバッグ用 実行開始確認NG ログ取得.
		} else {
			bl_Ans = True;		// 動作可能.
		}
	}
	return( bl_Ans );
}
/*================================================================================================
［機能］	【内部関数】禁止組み合わせチェック処理（バッファ連続、不連続モード動作可否決定）
--------------------------------------------------------------------------------------------------
［引数］
	CC_OneImgTransInfo* : 画像転送管理情報へのポインタ
	ST_ThreadComPara	:スレッド共通パラメータ
［戻値］
	Bool True:動作可能、False：動作禁止
［詳細］ 
［ｳｫｰｸｽﾙｰ］	実施未：2003/4/1：morikawa
================================================================================================*/
Bool CC_MultiThreadProfile::chkBufStatContDisCont( CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool bl_Ans = True;	// 戻り値　動作可能で初期化.
	// 起動しようとするスレッドを除いて、現在のバッファ連続、不連続確保状態を取得.
	EN_BufStatContDisCont en_BusyBufStatContDisCont 
// 2004/06/18 伊藤（史） 連続バッファ確保可否判定の不具合修正 start.
	// = CC_ImgTransInfoSingletonIf::newInstance().getBusyBufStatContDisCont( pcc_OneImgTransInfo->en_ThreadID );.
	 = CC_ImgTransInfoSingletonIf::newInstance().getBusyBufStatContDisCont( pcc_OneImgTransInfo );
// 2004/06/18 伊藤（史） 連続バッファ確保可否判定の不具合修正 end.

// 2004/06/18 伊藤(史) バッファメモリ確保・開放ログ start.
	dbgBufMemLogWrite((uchar)(en_BusyBufStatContDisCont+30),(uintptr_t)pcc_OneImgTransInfo,0);
// 2004/06/18 伊藤(史) バッファメモリ確保・開放ログ end.
	
	if( en_BusyBufStatContDisCont == EN_BufContWait ) {
	// 連続領域確保待ちの時は無条件に動作禁止.
		bl_Ans = False;
		_dbg_setChkTransExecNGPoint( 15 );	// 【修正:橋本昌】2004/05/28 デバッグ用 実行開始確認NG ログ取得.
	}
	if( pcc_OneImgTransInfo->en_BufStatContDisCont == EN_BufContWait 
	 || chkNextThAllocJpeg( pcc_OneImgTransInfo, rs_ThreadComPara ) != NULL
	 || chkNextThAllocResolCnv(pcc_OneImgTransInfo, rs_ThreadComPara ) != NULL	//【修正:橋本昌】2004/01/26 FAX対策.
	 || chkNextThAllocBTC( pcc_OneImgTransInfo, rs_ThreadComPara ) != NULL ) {
		// 動作開始しようとするスレッドor連続するスレッドがJPEG BTC確保の時は、その他のスレッドが不連続領域確保中は動作禁止.
		// 不連続領域が開放されて、初期化後実行する.
		//連続確保中はinitBufMemを行わない為、不連続確保時のみ動作禁止 [修正] kuroda 04/04/12.
	 	if( en_BusyBufStatContDisCont == EN_BufDisContBusy && bl_EnableBufContAlloc == False ) {
			bl_Ans = False;
			_dbg_setChkTransExecNGPoint( 16 );	// 【修正:橋本昌】2004/05/28 デバッグ用 実行開始確認NG ログ取得.
		}
	} 
	return( bl_Ans );
}
/*================================================================================================
［機能］	【内部関数】バッファ確保プレーン数計算（２値）
--------------------------------------------------------------------------------------------------
［引数］
	CC_OneImgTransInfo* : 画像転送管理情報へのポインタ
	IMGE_ImageColor:画像カラー情報
	Bool:1200dpiかどうか [True]1200dpiである [False]1200dpiでない 
［戻値］
	Bool True:計算成功、False：計算失敗
［詳細］ 
［ｳｫｰｸｽﾙｰ］	実施未：2003/4/1：morikawa
［履歴］	04/06/09：arakawa 不要な処理を削除 
			09/07/16 yashiro Emperorプリント1200dpi対応.
================================================================================================*/
Bool CC_MultiThreadProfile::calBufPlaneNum1bit( CC_OneImgTransInfo* pcc_OneImgTransInfo, IMGE_ImageColor ec_ImageColor, Bool b_1200dpi )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "calBufPlaneNum1bit OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x03FE );

	uchar uc_ColorNum = 0;
	uchar uc_PlaneNum = 0;
	uchar uc_TotalPlaneNum = 0;
	uchar uc_AttColorNum = 0;

	for( uchar j=0; j<THRD_MAXBUF_COLORNUM; ++j ) {
		//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加(なお、1200dpiのときのプレーン数は1色につき4プレーン).
		uc_TotalPlaneNum = theColorInformation.getColorPlaneCount( uc_ColorNum, uc_PlaneNum, uc_AttColorNum, j, ec_ImageColor, IMGE_ImageTone_1bit, IMGE_ImageCompress_Non, b_1200dpi );
		pcc_OneImgTransInfo->uc_PlaneNum[j] = uc_PlaneNum;
		if( (j+1) >= uc_ColorNum ){
			break;
		}
	}
	pcc_OneImgTransInfo->uc_AllPlaneNum = uc_TotalPlaneNum;
	pcc_OneImgTransInfo->uc_AllColorNum = uc_ColorNum;
	//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加(なお、1200dpiのときの属性数は0).
	pcc_OneImgTransInfo->uc_AllAttNum = theColorInformation.calcAttributeNum( ec_ImageColor, b_1200dpi );

	return( True );
}
