// ================================================================================================.
//! <!--機能--> DMA/バッファリソースが開放されているかどうかチェック.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pc_OneImgTransInfo ... 指定の画像転送管理情報.
//! <!--戻値-->.
//! \return True:開放されている False:開放されていない.
//! <!--詳細-->.
//! 指定の管理情報が利用する、DMA/バッファリソースが.
//! 開放されているかどうかチェック\n.
//! <!--履歴-->.
//  05/05/26 yokoi	 新規作成.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkResourceFree( CC_OneImgTransInfo* pc_OneImgTransInfo )
{
	THRL_ThAssert( (pc_OneImgTransInfo != NULL), "chkResourceFree OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x040D );
	Bool b_Ans = True;
	ushort us_Idx = 0;
	THRE_DmaId e_DmaId;
	THRE_BufId e_BufId;

	// DMAリソースの開放チェック.
	for( us_Idx = 0; (us_Idx < THRD_MAX_DMA_USE) && (b_Ans == True); us_Idx++ ){
		e_DmaId = pc_OneImgTransInfo->e_usedDma[us_Idx];
		if( (e_DmaId < THRE_DmaId_Num)	// pc_DmaResMan[] のサイズ内かチェック.
				&& (pc_DmaResMan[e_DmaId]->getOwner() == pc_OneImgTransInfo) ){
			b_Ans = False;
		}
	}

	// バッファリソースの開放チェック.
	for( us_Idx = 0; (us_Idx < THRD_MAX_BUF_USE) && (b_Ans == True); us_Idx++ ){
		e_BufId = pc_OneImgTransInfo->s_usedBuf[us_Idx].e_usedBuf;
		if( (e_BufId < THRE_BufId_Num)
			&& (pc_BufResMan[e_BufId]->getOwner( pc_OneImgTransInfo->s_usedBuf[us_Idx].b_isWrite ) == pc_OneImgTransInfo) ){
			b_Ans = False;
		}
	}

	return ( b_Ans );
}

