uchar CC_MultiThreadProfile::getThBusyNum( const ST_ThreadComPara& rs_ThreadComPara, THRE_ThrID en_ThreadID )
{
	uchar uc_Ans = 0, uc_ThInorOutNum = 0;

	CC_ImgTransInfoSingletonIf::newInstance().getOneImgIndexNumFromTh( uc_ThInorOutNum, uc_Ans, rs_ThreadComPara, en_ThreadID );
	THRL_ThAssert( (uc_Ans < THRD_MaxThreadBusy), "getThBusyNum BusyIdx error %d", uc_Ans , 0, 0, 0, CFA14_DetailCode0x043D );

	return ( uc_Ans );
}

