// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな伸張情報を初期化する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara st_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/07/12 橋本昌	新規作成.
// 2006/04/18 yokoi 	ラッパをかますように変更.
// ================================================================================================.
void CC_MultiThreadProfile::initLocalOneExpandMode( const ST_ThreadComPara& rs_ThreadComPara )
{
	uchar uc_InOut = DEF_InOutThread;
	if( rs_ThreadComPara.pcc_OneImageOutputMode != NULL ){
		uc_InOut = DEF_OutputThread;
	} else {
		uc_InOut = DEF_InputThread;
	}

	initLocalOneExpandMode( rs_ThreadComPara.ss_TransIndexNum, uc_InOut );
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな伸張情報を初期化する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param short ss_TransIndex.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2006/04/18 yokoi 	新規作成.
// ================================================================================================.
void CC_MultiThreadProfile::initLocalOneExpandMode( short ss_TransIndex, uchar uc_InOut )
{
	if( uc_InOut == DEF_InputThread ){
			// 入力時は開放不要.
			return;
	}
	
	for( register uchar uc_ModeID = 0; uc_ModeID < THRE_LocalExpandModeID_Max; uc_ModeID++ ){
		for( register uchar ucPage = 0; ucPage < InputPageNumMax; ucPage++ ){
			if( CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ ss_TransIndex ][ uc_ModeID ][ ucPage ] != NULL ){
				// 伸張情報設定されている.
				Bool bl_Result = rc_LocalOneExpandModeManager.free( CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ ss_TransIndex ][ uc_ModeID ][ ucPage ] );	// ローカルな伸張情報を開放.
				
				THRL_ThAssert( bl_Result == True , "CC_MultiThreadProfile::initLocalOneExpandMode Error %d %d %d", 
					ss_TransIndex, uc_ModeID, ucPage , 0, CFA14_DetailCode0x046C );
				
				CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ ss_TransIndex ][ uc_ModeID ][ ucPage ] = NULL;
			}
		}
	}
	CC_ImgTransInfoSingletonIf::newInstance().e_LastExpandModeID[ ss_TransIndex ] = THRE_LocalExpandModeID_0;
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな入力画像情報に必要な情報を設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param DOCC_Leaf* pc_LocalLeaf.
//! \param DOCC_Leaf* pc_OriginalLeaf.
//! \param ST_ThreadComPara* rs_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/07/12 橋本昌	新規作成.
// ================================================================================================.
void CC_MultiThreadProfile::makeLocalLeaf( DOCC_Leaf* pc_LocalLeaf, DOCC_Leaf* pc_OriginalLeaf, const ST_ThreadComPara& rs_ThreadComPara )
{
	// まず、変換前の Leafをコピーする.
	IMGC_Image* pc_Image = pc_LocalLeaf->getImage();	// Imageのポインタ退避.
	THRL_ThAssert( ( pc_Image != NULL ), "CC_MultiThreadProfile::makeLocalLeaf(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x046D );
	IMGC_ImageImp* pc_ImageImpColor = pc_LocalLeaf->getImage()->m_IMGC_ImageImp;	// ImageImpColorの退避.
	
	_memcpy( pc_LocalLeaf, pc_OriginalLeaf, sizeof(DOCC_Leaf));
	pc_LocalLeaf->addImage( pc_Image );	// 退避させてていたImageのポインタをもどす.
	
	_memcpy( pc_LocalLeaf->getImage(), pc_OriginalLeaf->getImage(), sizeof(IMGC_Image) );
	pc_LocalLeaf->getImage()->m_IMGC_ImageImp = pc_ImageImpColor;	// 退避させていたImageImpColorのポインタを戻す.
	// ここまでで、変換前の Leafをコピー完了.
	
	// Leaf以下の情報の設定は ローカルな伸張情報と一緒に行う CC_MultiThreadProfile::setLocalLeafInfo() にて.
	
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな入力画像情報に必要な情報を設定(白紙用).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param DOCC_Leaf* pc_LocalLeaf.
//! \param ST_ThreadComPara* rs_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! 白紙時のローカル入力画像情報を設定する\n.
//! <!--履歴-->.
// 2007/04/18 takamoto	新規作成.
// 2008/06/11 tadamasa  CQ304804 ProcessIDが設定されていなかった為、AllocPageWitｈWait()にてOIPなしでNGとなっていた.
//								 それによりallocImageInfo()でpc_OneImageInfoDataの設定が行われておらずAssertしていた.
// ================================================================================================.
void CC_MultiThreadProfile::makeLocalLeafWhite( DOCC_Leaf* pc_Leaf, const ST_ThreadComPara& rs_ThreadComPara )
{
	DOCC_Leaf* pc_OriginalLeaf = pc_Leaf;

	// 画像情報設定.
	// 画像回転角度、色情報、階調情報はとりあえず指定しているが、最終的には上位からもらう.
	setLocalLeafInfo( pc_Leaf, pc_OriginalLeaf,
					  rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].ct_ImageSize,
					  rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution,
					  getImageDir( rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].uc_ImageDir ),
					  rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].ec_ImageColor,
					  rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].ec_ImageTone );

	THRL_ThAssert( ( pc_Leaf->getImage() != NULL ), "CC_MultiThreadProfile::makeLocalLeafWhite: getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0A63 );
	// 設定する為の情報がない為、固定で画像情報設定(設定値に意味はない).
	pc_Leaf->getImage()->c_ImageInfo.e_DocLP = TYPE_OrientationAuto;			//ポートレート/ランドスケープ指定.
	pc_Leaf->getImage()->c_ImageInfo.e_FileFormat = TYPE_FileFormatRAW;			//ファイル形式（Text,Tiff,Pdf,Jpeg）.
	pc_Leaf->getImage()->c_ImageInfo.ct_ReadMag.x = 100;						//読み込み倍率.
	pc_Leaf->getImage()->c_ImageInfo.ct_ReadMag.y = 100;						//読み込み倍率.
	//ProcessIDの設定、現状、表表紙ありでBox保存した画像を仕上がりプレビュー表示した場合にしか.
	//ここの処理を通らないので決めうちでプレビューのul_ImageProcessIDをセットしている.
	pc_Leaf->getImage()->c_ImageInfo.ul_ImageProcessID = rs_ThreadComPara.c_ThreadIF.ul_ProcessID;
}

