// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな入力画像情報(Leaf)の初期化.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara ST_ThreadComPara.
//! \param st_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2006/04/18 yokoi 新規作成.
// 2006/05/31 yoshii 画像削除の際、排他制御とするため、deletePageからdeleteImageに呼び換える。.
// 2013/03/18 Sky Emperorプリント1200Dpi対応.
// ================================================================================================.
void CC_MultiThreadProfile::initLocalLeaf( short ss_TransIndex, uchar uc_InOut )
{
	register uchar ucPage = 0;
	// デバッグ用情報をクリア. 
	for( ucPage = 0; ucPage < InputPageNumMax; ucPage++ ){
		CC_ImgTransInfoSingletonIf::newInstance().dbg_pc_LeafLocal[ ss_TransIndex ][ ucPage ] = NULL;
	}

	if( uc_InOut == DEF_InputThread ){
		for( ucPage = 0; ucPage < 2; ucPage++ ){
			if( CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocalForInput[ ss_TransIndex ][ ucPage ] != NULL ){
				DOCC_Leaf* pc_LocalLeaf = CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocalForInput[ ss_TransIndex ][ ucPage ];
				IMGC_Image* pc_Image = pc_LocalLeaf->getImage();
				THRL_ThAssert( ( pc_Image != NULL ), "CC_MultiThreadProfile::initLocalLeaf(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0C2A );
				(void)pc_Image->m_IMGC_ImageImp->deleteImage( IMGD_DeletePage, pc_Image );

				Bool bl_Result = rc_LocalLeafManager.free( pc_LocalLeaf );
				THRL_ThAssert( bl_Result == True , "CC_MultiThreadProfile::initLocalLeaf Error %d %d",ss_TransIndex, ucPage , 0, 0, CFA14_DetailCode0x0C5E );
				CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocalForInput[ ss_TransIndex ][ ucPage ] = NULL;
			}
		}
	}else{
		for( ucPage = 0; ucPage < InputPageNumMax; ucPage++ ){
			if( CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocal[ ss_TransIndex ][ ucPage ] != NULL ){
				
				DOCC_Leaf* pc_LocalLeaf = CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocal[ ss_TransIndex ][ ucPage ];
				IMGC_Image* pc_Image = pc_LocalLeaf->getImage();
				THRL_ThAssert( ( pc_Image != NULL ), "CC_MultiThreadProfile::initLocalLeaf(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x046F );
//				IMGC_ImageImp* pc_ImageImpColor = pc_LocalLeaf->getImage()->m_IMGC_ImageImp;.
				
//				comMemoryManager.deletePage( pc_Image, True );.
				(void)pc_Image->m_IMGC_ImageImp->deleteImage( IMGD_DeletePage, pc_Image );		// 06/05/31 yoshii.

				Bool bl_Result = rc_LocalLeafManager.free( pc_LocalLeaf );
				
				THRL_ThAssert( bl_Result == True , "CC_MultiThreadProfile::initLocalLeaf Error %d %d", 
							ss_TransIndex, ucPage , 0, 0, CFA14_DetailCode0x0470 );
				
				CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocal[ ss_TransIndex ][ ucPage ] = NULL;
			}
		}
	}
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル 拡大&回転モードのローカルな伸張情報決定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara& rs_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/07/16 橋本昌		新規作成.
// 2006/06/20 yokoi			拡大後のサイズを、イメージサイズからとるのではなく、出力サイズからとるように修正。.
//							( 回転&拡大は、２次伸張がないため。).
// 2008/05/09 世古			エンジン出力時判定用の画像サイズ変換チェック追加(CQ:302518).
// 2009/02/03 堀内(Sky)		CQ314878：上位から取得した伸張情報において、先頭に画像がない場合は2番目に設定するように修正。.
//						　　　　　(小冊子の時は配列データの2番目に入ってるため).
// 2009/06/10 T.Shima(Sky)	倍率計算処理統合.
//							・画像サイズ変換チェック関数の置き換え.
//							・ct_Ratio取得方法変更.
// 2009/09/11 陰山		Soc対応.
// 2009/10/15 太田		CT2問題点対応(Gaia問題点リストNo.196) NULLアクセスにより、パネルロックが発生.
//							小冊子で1番目が白紙の場合、III[0]下のpOIPはNULLがセットされる.
//							しかし、CQ314878の対応で、pOIPのgetImage()をコ－ルして画像有無のチェックを行っており.
//							1番目のチェックにてNULLアクセスしていたのが原因.
//							NULLチェックはpOIPのgetImage()でなく、pOIPを見るよう修正.
// 2011/12/15 板倉		静的解析.
// 2016/04/27 oka       CQ528071 スキャナ倍率調整値+パネル倍率設定が0になるときがあるためVenusMLKはAssertコメントアウト.
// ================================================================================================.
void CC_MultiThreadProfile::setLocalExpandMode_ForRotAndMagnifyMode( const ST_ThreadComPara& rs_ThreadComPara )
{
	register uchar ucPos=0;
	for( ucPos=0; ucPos < InputPageNumMax; ucPos++ ){
		if( rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[ucPos].pOIP != NULL ){
			// 有効データ発見 ucPos 確定.
			break;
		}
	}
	THRL_ThAssert( (ucPos < InputPageNumMax), "setLocalExpandMode_ForRotAndMagnifyMode() ucPos error %d" , ucPos, 0, 0, 0, CFA14_DetailCode0x09C4 );

	SC_InputImageInfo& rs_III = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[ucPos];
	///// 拡大倍率設定.
	register TYPC_Point<float> ct_Ratio = TYPC_Point<float> ( 1.0f, 1.0f );	// 拡大倍率.
	register TYPC_Point<float> ct_OriginalSize = TYPC_Point<float>( 0.0f, 0.0f );
	CC_OneImgTransInfo* pcc_OneImageTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][0];

	register DOCC_Leaf* pc_OriginalLeaf = rs_III.pOIP;
	
// AR1058205 ワーニング除去：A4機ではb_SizeChangを使用しない.
#ifdef DEF_A4_Cus
	theModeInfoLib.getImageSizeChange(	pcc_OneImageTransInfo,
										pc_OriginalLeaf,
										ct_OriginalSize,
										rs_III.ct_ImageSize,
										rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution,
										rs_III.uc_ImageDir,
										False);
#else
	register Bool b_SizeChang = theModeInfoLib.getImageSizeChange(	pcc_OneImageTransInfo,
																	pc_OriginalLeaf,
																	ct_OriginalSize,
																	rs_III.ct_ImageSize,
																	rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution,
																	rs_III.uc_ImageDir,
																	False);
#endif // DEF_A4_Cus
	ct_Ratio = pcc_OneImageTransInfo->ct_RatioOrg;

/* 2016/04/27 CQ528071 FCOT時にJAMになる. */
#ifdef DEF_A4_Cus
	/* スキャナ倍率調整値+パネル倍率設定が0になるときがある. */
#else /* DEF_A4_Cus */
	THRL_ThAssert( b_SizeChang == True , "CC_MultiThreadProfile::setLocalExpandMode_ForRotAndMagnifyMode Error" , 0, 0, 0, 0, CFA14_DetailCode0x0471 );
#endif /* DEF_A4_Cus */
	
	///// 変換前の画像サイズ決定.
	register CC_OneExpandMode* pc_1stOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
	THRL_ThAssert( ( pc_1stOneExpandMode != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForRotAndMagnifyMode(): allocation error." , 0, 0, 0, 0, CFA14_DetailCode0x0472 );
	// まず、上位からもらった伸張情報をコピー.
	// 拡大＆回転モードの時は１次伸張でシフト、トリミングを行う.
	_memcpy( pc_1stOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode , sizeof(CC_OneExpandMode));

	uchar uc_ExpandNum = 0; 
	
	//1番目に画像がなく、2番目に画像が入っている場合(小冊子).
	//091015 太田 CT2不具合対応(詳細は履歴参照).
	if ( (NULL == pc_1stOneExpandMode->III[ 0 ].pOIP) && (NULL != pc_1stOneExpandMode->III[ 1 ].pOIP) )	{
		uc_ExpandNum = 1;
	}

	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_Start = rs_III.ct_Start / ct_Ratio;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_Offst = rs_III.ct_Offst / ct_Ratio;
	THRL_ThAssert( ( pc_OriginalLeaf->getImage() != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForRotAndMagnifyMode(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0473 );
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_EffectSize.e_SizeCode = pc_OriginalLeaf->getImage()->c_ImageInfo.ct_ImageSize.e_SizeCode;	// サイズコード.
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_EffectSize.c_SizeMM = rs_III.ct_EffectSize.c_SizeMM / ct_Ratio;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_EffectSize.b_WideOn = pc_OriginalLeaf->getImage()->c_ImageInfo.ct_ImageSize.b_WideOn;	// ワイド紙指定.
	pc_1stOneExpandMode->III[ uc_ExpandNum ].uc_ImageDir = rs_III.uc_ImageDir;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].uc_Nin1ImageDir = rs_III.uc_Nin1ImageDir;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ct_SerialNumStart = rs_III.ct_SerialNumStart / ct_Ratio;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ec_ImageColor = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageColorResult;
	pc_1stOneExpandMode->III[ uc_ExpandNum ].ec_ImageTone = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageTone;

	pc_1stOneExpandMode->bl_RotateAndMagnifyMode = False;	// 回転＆拡大プリントモードではないとする.
	pc_1stOneExpandMode->ct_OutputSize = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize / ct_Ratio;
	for( register uchar ucPage=0; ucPage < InputPageNumMax; ucPage++ ){
		pc_1stOneExpandMode->ct_ImageArea[ ucPage ] = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_ImageArea[ ucPage ] / ct_Ratio;
	}
	
	CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_0 ][ 0 ] = pc_1stOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
	
	// 変換後の画像サイズ決定.
	setLocalLeafInfo( CC_ImgTransInfoSingletonIf::newInstance().getLocalLeaf( THRE_ThrID_BufToExt, rs_ThreadComPara),
//		2006/06/20 yokoi mod 通常の画像変換と違い、２次伸張が無いので、出力サイズで変倍する.
//		pc_OriginalLeaf, pc_1stOneExpandMode->III[ 0 ].ct_ImageSize, pc_1stOneExpandMode->c_Resolution,.
		pc_OriginalLeaf, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize, pc_1stOneExpandMode->c_Resolution, 
		getImageDir( pc_1stOneExpandMode->III[ uc_ExpandNum ].uc_ImageDir ),
		pc_1stOneExpandMode->III[ uc_ExpandNum ].ec_ImageColor,
		pc_1stOneExpandMode->III[ uc_ExpandNum ].ec_ImageTone );	// ローカルな入力画像情報(Leaf)設定.
		
	// 拡大＆回転モードの時は２次伸張は行わないが設定しておく.
	register CC_OneExpandMode* pc_2ndOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
	_memcpy( pc_2ndOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode , sizeof(CC_OneExpandMode));
	pc_2ndOneExpandMode->III[ uc_ExpandNum ].uc_ImageDir = ROT0;
	
	CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_1 ][ 0 ] = pc_2ndOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル Fax送信2in1用のローカルな伸張情報の設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara& rs_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/10/31 yokoi			新規作成.
// 2006/03/08 Koshino(Sky)	小冊子対応.
// 2009/03/12 安田 			Linux新規実装.
// 2009/06/10 T.Shima		倍率計算処理統合：画像サイズ変換チェック関数置き換え、ct_Ratio取得方法変更、ct_ConvertSize、ct_OriginalSize設定処理の変更.
//	09/09/11 陰山			Soc対応.
// ================================================================================================.
void CC_MultiThreadProfile::setLocalExpandMode_ForFax2in1( const ST_ThreadComPara& rs_ThreadComPara )
{
	//2009/03/30 newInstance対応 comMemoryManagerのインスタンス生成.
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();

	// とりあえず、利用しないようにしてあります。.
	THRL_ThAssert( False, "Fax2in1 Not used function" , 0, 0, 0, 0, CFA14_DetailCode0x0474 );
	register CC_OneExpandMode* pc_1stOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
	THRL_ThAssert( ( pc_1stOneExpandMode != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForFax2in1(): allocation error." , 0, 0, 0, 0, CFA14_DetailCode0x0475 );
	register CC_OneExpandMode* pc_2ndOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
	register uchar ucPos=0;
	register uchar uc_ImageNum = 0;
	// 初期値設定.
	_memcpy( pc_1stOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
	_memcpy( pc_2ndOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.

	CC_OneImgTransInfo* pcc_OneImageTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][0];


	for( ucPos=0; ucPos < InputPageNumMax; ucPos++ ){
		SC_InputImageInfo& rs_III = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[ucPos];
		if( rs_III.pOIP != NULL ){
			// 有効データ発見 ucPos 確定.
			uc_ImageNum++;

			/////////////// 変換前の伸張情報決定 ////////////.
//			register CC_OneExpandMode* pc_1stOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
			
			////// 解像度変換、変倍があるか否か.
			register TYPC_Point<float> ct_Ratio = TYPC_Point<float> ( 1.0f, 1.0f );	// 拡大倍率.
			register TYPC_Point<float> ct_ConvertSize = TYPC_Point<float>( 0.0f, 0.0f );
			register TYPC_Point<float> ct_OriginalSize = TYPC_Point<float>( 0.0f, 0.0f );
			register DOCC_Leaf* pc_OriginalLeaf = rs_III.pOIP;
			register Bool b_getImageSizeChange = 
					theModeInfoLib.getImageSizeChange(	pcc_OneImageTransInfo,
														pc_OriginalLeaf,
														ct_OriginalSize,
														rs_III.ct_ImageSize,
														rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution,
														rs_III.uc_ImageDir,
														False );
			ct_ConvertSize = rs_III.ct_ImageSize;
			ct_Ratio = pcc_OneImageTransInfo->ct_RatioOrg;

			////// 回転処理実行タイミング決定.
			register bool b_RotateExecOn1stExpand = True;	// True: １次伸張で回転 , False: ２次伸張で回転.
			register uchar uc_1stExpandImageDir = rs_III.uc_ImageDir;
			register uchar uc_2ndExpandImageDir = ROT0;
			if( b_getImageSizeChange == True ){
				//// 解像度変換、変倍の設定.
				if( ct_Ratio.x < 1.0 ){
					// 縮小.
					b_RotateExecOn1stExpand = False;	// False: ２次伸張で回転 解像度変換前のデータが主走査方向 8Kbit 超える恐れがあるため.
					uc_1stExpandImageDir = ROT0;
					uc_2ndExpandImageDir = rs_III.uc_ImageDir;
				} else {
					// 拡大.
					b_RotateExecOn1stExpand = True;	// True: １次伸張で回転 解像度変換後のデータが主走査方向 8Kbit 超える恐れがあるため.
					uc_1stExpandImageDir = rs_III.uc_ImageDir;
					uc_2ndExpandImageDir = ROT0;
				}
			}
			
			////// １次伸張後の画像サイズ決定.
			if( b_RotateExecOn1stExpand == False 
				&& ( rs_III.uc_ImageDir == ROT90
					|| rs_III.uc_ImageDir == ROT270 ) ){
					// 回転を２次伸張で行うときは回転してないときの画像サイズを求める.
					ct_ConvertSize = ct_ConvertSize.xyReverse();
			}
			THRL_ThAssert( ( rs_III.pOIP->getImage() != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForFax2in1(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0476 );
			register TYPC_Resolution c_1stExpandResolution = rs_III.pOIP->getImage()->c_ImageInfo.c_Resolution;
			if( uc_1stExpandImageDir == ROT90 || uc_1stExpandImageDir == ROT270 ){
				c_1stExpandResolution.setDpi( TYPC_Point<float>( c_1stExpandResolution.getDpi().y, c_1stExpandResolution.getDpi().x ) );
			}
			
			////// 画像サイズ関係決定.
			// １次伸張では変倍前/解像度変換前の画像サイズを伸張する.
			// １次伸張では、シフト、トリミング、余白を作成しない.
			// 連番、オーバーレイ、地紋、文字印字(日付、ページ、RTI)は１次伸張では行わない.
//			_memcpy( pc_1stOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
			// 【課題】05/11/02 yokoi Nin1の画像が全て同じ変倍率/解像度であることが前提。解像度変換しか無い予定なので現状OK?.
			CC_OneExpandMode* pc_OEM = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode;
			ct_OriginalSize.x = DOTtoMM( (short)(MMtoDOT( pc_OEM->ct_OutputSize.x, (float)(pc_OEM->c_Resolution.getDpi().x ) / ct_Ratio.x)), pc_1stOneExpandMode->III[ ucPos ].pOIP->getImage()->c_ImageInfo.c_Resolution.getDpi().x );
			ct_OriginalSize.y = DOTtoMM( (short)(MMtoDOT( pc_OEM->ct_OutputSize.y, (float)(pc_OEM->c_Resolution.getDpi().y ) / ct_Ratio.y)), pc_1stOneExpandMode->III[ ucPos ].pOIP->getImage()->c_ImageInfo.c_Resolution.getDpi().y );
			pc_1stOneExpandMode->III[ ucPos ].pOIP = pc_OriginalLeaf;	// 変換前のLeafを設定.
			pc_1stOneExpandMode->III[ ucPos ].ct_Start = TYPC_Point<float>( pc_1stOneExpandMode->III[ucPos].ct_Start.x/ct_Ratio.x, pc_1stOneExpandMode->III[ucPos].ct_Start.y/ct_Ratio.y );	// １画像の伸張開始座標.
			pc_1stOneExpandMode->III[ ucPos ].ct_Offst = TYPC_Point<float>( pc_1stOneExpandMode->III[ucPos].ct_Offst.x/ct_Ratio.x, pc_1stOneExpandMode->III[ucPos].ct_Offst.y/ct_Ratio.y );	// １画像の伸張開始座標から有効画像領域（左上）までのオフセット.
			pc_1stOneExpandMode->III[ ucPos ].ct_ImageSize = ct_OriginalSize;		// １画像の画像サイズ（IMG_SIM用）.
			pc_1stOneExpandMode->III[ ucPos ].ct_EffectSize = ct_OriginalSize;		// １画像の有効画像領域の大きさ.
			pc_1stOneExpandMode->III[ ucPos ].uc_ImageDir = uc_1stExpandImageDir;	// １画像の伸張時の回転角度.
			pc_1stOneExpandMode->III[ ucPos ].uc_Nin1ImageDir = ROT0;
			pc_1stOneExpandMode->III[ ucPos ].ct_SerialNumStart = TYPC_Point<float>( 0.0f, 0.0f );		// 連番印字伸張開始座標.
//			pc_1stOneExpandMode->III[ ucPos ].ec_ImageColor = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageColorResult;			// 出力時 画像カラー情報（Lab,YMCK,RGB.....）.
			pc_1stOneExpandMode->III[ ucPos ].ec_ImageColor = theColorInformation.selectImageColor( pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageColorResult,
						rs_III.ec_ImageColor, rs_III.ec_ImageTone );
			pc_1stOneExpandMode->III[ ucPos ].ec_ImageTone = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageTone;			// 出力時 画像階調情報（1bit-4bit,8bit）.
			pc_1stOneExpandMode->ec_SystemSpeed = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ec_SystemSpeed;	// システムスピード.
			pc_1stOneExpandMode->bl_RotateAndMagnifyMode = False;				// 回転＆拡大プリントモード(コピー時の 高速で拡大出力して出力するモード) True: 回転＆拡大プリントFalse : その他.
			pc_1stOneExpandMode->ct_OutputSize = ct_OriginalSize;		// 出力エリアサイズ.
//			pc_1stOneExpandMode->ct_OutputSize.y = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize.y / ct_Ratio.y;.
			pc_1stOneExpandMode->c_Resolution = c_1stExpandResolution;	// 解像度.
			pc_1stOneExpandMode->bl_ImageRepeat = False;			// イメージリピート情報.
			pc_1stOneExpandMode->bl_CenterErase = False;			// センターイレース要求.
//			pc_1stOneExpandMode->ss_SerialNum = -1;							// 連番印字番号 連番なし(-1) ← エンジン出力の時のみクリアするよう変更 2005/10/25 Koshino.
			pc_1stOneExpandMode->ss_BackImageNum = -1;	// 背景画像ＩＤ.

			pc_1stOneExpandMode->bl_BookletMode = False;	// 週刊誌綴モード OFFのはず.
			
//			comImgTrans.pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_0 ][ ucPos ] = pc_1stOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
			
			/////////////// 変換後の伸張情報決定 ////////////.
//			register CC_OneExpandMode* pc_2ndOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
			
			////// 画像サイズ関係決定.
//			_memcpy( pc_2ndOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
			// 2in1の画像は、1つのImageにまとめる.
			pc_2ndOneExpandMode->uc_ImageNum = 1;
			if( ucPos == 0 ){
				pc_2ndOneExpandMode->III[ ucPos ].pOIP = CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocal[ rs_ThreadComPara.ss_TransIndexNum ][ ucPos ];	// // スレッド内部　ローカルな入力画像情報(Leaf)  確保済み.
				setLocalLeafInfo( pc_2ndOneExpandMode->III[ ucPos ].pOIP, pc_OriginalLeaf, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution, 
					getImageDir( (uchar)(( pc_OriginalLeaf->getImage()->c_ImageInfo.e_ImageDir + uc_1stExpandImageDir ) % ROT360) ),
					rs_III.ec_ImageColor,
					rs_III.ec_ImageTone );	// ローカルな入力画像情報(Leaf)設定.
				pc_2ndOneExpandMode->III[ ucPos ].uc_ImageDir = uc_2ndExpandImageDir;	// １画像の伸張時の回転角度.
				// 圧縮に必要なサイズを設定しておく.
				pc_2ndOneExpandMode->III[ ucPos ].pOIP->getImage()->m_IMGC_ImageImp->ul_CompressSize = comMemoryManager.getOnePageSize( pc_2ndOneExpandMode->III[ ucPos ].pOIP );
			} else {
				pc_2ndOneExpandMode->III[ ucPos ].pOIP = NULL; 
			}
			
			//------------------------------------------------------------------------------.
			// エンジン出力シーケンスなら、1次伸張合成画像用データのクリア、.
			// それ以外なら2次伸張合成画像用データをクリアする 2005/10/25 Koshino 追加.
			//------------------------------------------------------------------------------.
			// 出力シーケンスをチェックする.
			CC_OneExpandMode *pc_OneExpandMode;
			if( rs_ThreadComPara.c_ThreadIF.b_EngOut == True ){	// エンジン出力シーケンスの時.
				pc_OneExpandMode = pc_1stOneExpandMode;
			} else {	// エンジン出力シーケンス以外（アプリ出力シーケンスを想定）の時.
				pc_OneExpandMode = pc_2ndOneExpandMode;
			}

			// 1次伸張or2次伸張のクリア.
			pc_OneExpandMode->ss_SerialNum = -1;					// 連番印字番号 連番なし(-1).
			for( uchar uc_Cnt = 0;uc_Cnt < InputPageBookLet;uc_Cnt++){
				pc_OneExpandMode->s_PageStamp.s_PageStamp1PageInfo[uc_Cnt].b_On = False;				// ページ印字 OFF.
				pc_OneExpandMode->s_DateStamp.s_DateStamp1PageInfo[uc_Cnt].b_On = False;				// 日付印字 OFF.
				pc_OneExpandMode->s_Stamp.s_Stamp1PageInfo[uc_Cnt].b_On = False;						// 定型スタンプ OFF.
				pc_OneExpandMode->s_HeaderFooterInfo.s_Header.s_HeaderFooter1PageInfo[uc_Cnt].b_isSetHeaderFooter = False;	// ヘッダ OFF.
				pc_OneExpandMode->s_HeaderFooterInfo.s_Footer.s_HeaderFooter1PageInfo[uc_Cnt].b_isSetHeaderFooter = False;	// フッタ OFF.
				pc_OneExpandMode->s_FilingNumberInfo.s_FilingNumber1PageInfo[uc_Cnt].b_On = False;							// ファイリングナンバー OFF.
			}
			pc_OneExpandMode->s_Stamp.b_ThreadOn = False;
			pc_OneExpandMode->s_PrtWatermark.b_On = False;			// ウォーターマーク OFF.
			pc_OneExpandMode->s_PrtSampleCopy.b_On = False;			// サンプルコピー OFF.
			pc_OneExpandMode->s_TTIInfo.b_blExec = False;			// True： TTI/RTI画像描画あり , False : 画像描画なし.
// 2005/12/12 Koshino(Sky) OEM変更に伴う追加.
			pc_OneExpandMode->s_OverLayInfo.b_isOverLay = False;					// True： オーバーレイ画像描画あり , False : 画像描画なし.
//			pc_OneExpandMode->s_HeaderFooterInfo.s_Header.b_isSetHeaderFooter = False;	// 2006/03/08 Koshino(Sky) 小冊子対応.
//			pc_OneExpandMode->s_HeaderFooterInfo.s_Footer.b_isSetHeaderFooter = False;	// 2006/03/08 Koshino(Sky) 小冊子対応.
			pc_OneExpandMode->s_JimonPatternIn.uc_JimonFlagTheread = 0;				// 1： 地紋画像描画あり , 0 : 画像描画なし.
// 2005/12/12 Koshino(Sky).
//			pc_OneExpandMode->s_FilingNumberInfo.b_On = False;	// 2006/03/08 Koshino(Sky) 小冊子対応.
		}
	}
	CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_0 ][ 0 ] = pc_1stOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
	CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_1 ][ 0 ] = pc_2ndOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
	THRL_ThAssert( (uc_ImageNum == 2), "setLocalExpandMode_ForFax2in1 ImageNum error %d", uc_ImageNum , 0, 0, 0, CFA14_DetailCode0x0477 );
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル 変倍Nin1用のローカルな伸張情報の設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara& rs_ThreadComPara.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/11/01 yokoi			新規作成.
// 2006/03/08 Koshino(Sky)	小冊子対応.
// 2009/06/10 T.Shima		倍率計算処理統合：画像サイズ変換チェック関数置き換え、ct_Ratio取得方法変更、ct_ConvertSize、ct_OriginalSize設定処理の変更.
//	09/09/11 陰山			Soc対応.
// ================================================================================================.
void CC_MultiThreadProfile::setLocalExpandMode_ForNin1AndMag( const ST_ThreadComPara& rs_ThreadComPara )
{
	//2009/03/30 newInstance対応 comMemoryManagerのインスタンス生成.
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();

	// とりあえず、利用しないようにしてあります。.
	THRL_ThAssert( False, "Fax2in1 Not used function" , 0, 0, 0, 0, CFA14_DetailCode0x0478 );
	THRL_ThAssert( rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->uc_ImageNum > 1 , "setLocalExpandMode_ForNin1AndMag Mode Error Nin1!!" , 0, 0, 0, 0, CFA14_DetailCode0x0479 );
	
	// ページ単位での繰り返し起動回数を設定しておく(ここでは、ページ/バンド単位によらず設定しておき、ページ/バンド単位決定時に修正する).
	for( uchar i = 0; i < THRD_MaxThreadBusy; i++ ){
		CC_OneImgTransInfo& rc_OneImgTransInfo = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][i];
		switch( rc_OneImgTransInfo.st_TransModePara.en_AppIDSelThread ){
		case THRE_AppID_FaxSend:
		case THRE_AppID_IFaxSend:
			// Fax送信時は、特別に2in1で伸張した後に変倍するので、繰り返し回数は1のまま。.
			break;
		default:
			rc_OneImgTransInfo.us_RepeatPageExecNum = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->uc_ImageNum;
			break;
		}
	}
	register CC_OneExpandMode* pc_2ndOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
	THRL_ThAssert( ( pc_2ndOneExpandMode != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForNin1AndMag(): allocation error." , 0, 0, 0, 0, CFA14_DetailCode0x047A );
	_memcpy( pc_2ndOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
	register uchar ucPos=0;
	register uchar uc_ImageNum = 0;

	CC_OneImgTransInfo* pcc_OneImageTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[rs_ThreadComPara.ss_TransIndexNum][DEF_OutputThread][0];

	for( ucPos = 0; ucPos < InputPageNumMax; ucPos++ ){
		SC_InputImageInfo& rs_III = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[ucPos];
		if( rs_III.pOIP != NULL ){
			// 有効データ発見 ucPos 確定.
			uc_ImageNum++;
			
			/////////////// 変換前の伸張情報決定 ////////////.
			register CC_OneExpandMode* pc_1stOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
			
			////// 解像度変換、変倍があるか否か.
			register TYPC_Point<float> ct_Ratio = TYPC_Point<float> ( 1.0f, 1.0f );	// 拡大倍率.
			register TYPC_Point<float> ct_ConvertSize = TYPC_Point<float>( 0.0f, 0.0f );
			register TYPC_Point<float> ct_OriginalSize = TYPC_Point<float>( 0.0f, 0.0f );
			register DOCC_Leaf* pc_OriginalLeaf = rs_III.pOIP;
			register Bool b_getImageSizeChange = 
					theModeInfoLib.getImageSizeChange( 	pcc_OneImageTransInfo,
														pc_OriginalLeaf,
														ct_OriginalSize,
														rs_III.ct_ImageSize,
														rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution,
														rs_III.uc_ImageDir,
														False );
			ct_ConvertSize = rs_III.ct_ImageSize;
			ct_Ratio = pcc_OneImageTransInfo->ct_RatioOrg;

			////// 回転処理実行タイミング決定.
			register bool b_RotateExecOn1stExpand = True;	// True: １次伸張で回転 , False: ２次伸張で回転.
			register uchar uc_1stExpandImageDir = rs_III.uc_ImageDir;
			register uchar uc_2ndExpandImageDir = ROT0;
			if( b_getImageSizeChange == True ){
				//// 解像度変換、変倍の設定.
				if( ct_Ratio.x < 1.0 ){
					// 縮小.
					b_RotateExecOn1stExpand = False;	// False: ２次伸張で回転 解像度変換前のデータが主走査方向 8Kbit 超える恐れがあるため.
					uc_1stExpandImageDir = ROT0;
					uc_2ndExpandImageDir = rs_III.uc_ImageDir;
				} else {
					// 拡大.
					b_RotateExecOn1stExpand = True;	// True: １次伸張で回転 解像度変換後のデータが主走査方向 8Kbit 超える恐れがあるため.
					uc_1stExpandImageDir = rs_III.uc_ImageDir;
					uc_2ndExpandImageDir = ROT0;
				}
			}
			
			////// １次伸張後の画像サイズ決定.
			if( b_RotateExecOn1stExpand == False 
				&& ( rs_III.uc_ImageDir == ROT90
					|| rs_III.uc_ImageDir == ROT270 ) ){
					// 回転を２次伸張で行うときは回転してないときの画像サイズを求める.
					ct_ConvertSize = ct_ConvertSize.xyReverse();
			}
			THRL_ThAssert( ( rs_III.pOIP->getImage() != NULL ), "CC_MultiThreadProfile::setLocalExpandMode_ForNin1AndMag(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x047B );
			register TYPC_Resolution c_1stExpandResolution = rs_III.pOIP->getImage()->c_ImageInfo.c_Resolution;
			if( uc_1stExpandImageDir == ROT90 || uc_1stExpandImageDir == ROT270 ){
				c_1stExpandResolution.setDpi( TYPC_Point<float>( c_1stExpandResolution.getDpi().y, c_1stExpandResolution.getDpi().x ) );
			}
			
			////// 画像サイズ関係決定.
			// １次伸張では変倍前/解像度変換前の画像サイズを伸張する.
			// １次伸張では、シフト、トリミング、余白を作成しない.
			// 連番、オーバーレイ、地紋、文字印字(日付、ページ、RTI)は１次伸張では行わない.
			_memcpy( pc_1stOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
			for( uchar i = 0; i < InputPageNumMax; i++ ){
				// 一旦、画像を削除.
				pc_1stOneExpandMode->III[i].pOIP = NULL;
			}
			pc_1stOneExpandMode->uc_ImageNum = 1;
			pc_1stOneExpandMode->III[0].pOIP = pc_OriginalLeaf;	// 変換前のLeafを設定.
			pc_1stOneExpandMode->III[0].ct_Start = TYPC_Point<float>( 0.0f, 0.0f );	// １画像の伸張開始座標.
			pc_1stOneExpandMode->III[0].ct_Offst = TYPC_Point<float>( 0.0f, 0.0f );	// １画像の伸張開始座標から有効画像領域（左上）までのオフセット.
			pc_1stOneExpandMode->III[0].ct_ImageSize = ct_OriginalSize;		// １画像の画像サイズ（IMG_SIM用）.
			pc_1stOneExpandMode->III[0].ct_EffectSize = ct_OriginalSize;		// １画像の有効画像領域の大きさ.
			pc_1stOneExpandMode->III[0].uc_ImageDir = uc_1stExpandImageDir;	// １画像の伸張時の回転角度.
			pc_1stOneExpandMode->III[0].uc_Nin1ImageDir = ROT0;
			pc_1stOneExpandMode->III[0].ct_SerialNumStart = TYPC_Point<float>( 0.0f, 0.0f );		// 連番印字伸張開始座標.
//			pc_1stOneExpandMode->III[0].ec_ImageColor = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageColorResult;			// 出力時 画像カラー情報（Lab,YMCK,RGB.....）.
			pc_1stOneExpandMode->III[0].ec_ImageColor = theColorInformation.selectImageColor( pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageColorResult,
						rs_III.ec_ImageColor, rs_III.ec_ImageTone );
			pc_1stOneExpandMode->III[0].ec_ImageTone = pc_OriginalLeaf->getImage()->c_ImageInfo.ec_ImageTone;			// 出力時 画像階調情報（1bit-4bit,8bit）.
			pc_1stOneExpandMode->ec_SystemSpeed = rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ec_SystemSpeed;	// システムスピード.
			pc_1stOneExpandMode->bl_RotateAndMagnifyMode = False;				// 回転＆拡大プリントモード(コピー時の 高速で拡大出力して出力するモード) True: 回転＆拡大プリントFalse : その他.
			pc_1stOneExpandMode->ct_OutputSize = ct_OriginalSize;		// 出力エリアサイズ.
			pc_1stOneExpandMode->c_Resolution = c_1stExpandResolution;	// 解像度.
			pc_1stOneExpandMode->bl_ImageRepeat = False;			// イメージリピート情報.
			pc_1stOneExpandMode->bl_CenterErase = False;			// センターイレース要求.
//			pc_1stOneExpandMode->ss_SerialNum = -1;							// 連番印字番号 連番なし(-1) ← エンジン出力の時のみクリアするよう変更 2005/10/25 Koshino.
			pc_1stOneExpandMode->ss_BackImageNum = -1;	// 背景画像ＩＤ.

			pc_1stOneExpandMode->bl_BookletMode = False;	// 週刊誌綴モード OFFのはず.
			
//			comImgTrans.pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_0 ][ ucPos ] = pc_1stOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
			
			/////////////// 変換後の伸張情報決定 ////////////.
//			register CC_OneExpandMode* pc_2ndOneExpandMode = allocLocalOneExpandMode( rs_ThreadComPara );	// ローカルな伸張情報を確保.
			
			////// 画像サイズ関係決定.
//			_memcpy( pc_2ndOneExpandMode, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode, sizeof( CC_OneExpandMode ) );	// まず伸張情報をコピー.
			pc_2ndOneExpandMode->III[ ucPos ].pOIP = CC_ImgTransInfoSingletonIf::newInstance().pc_LeafLocal[ rs_ThreadComPara.ss_TransIndexNum ][ ucPos ];	// // スレッド内部　ローカルな入力画像情報(Leaf)  確保済み.
			setLocalLeafInfo( pc_2ndOneExpandMode->III[ ucPos ].pOIP, pc_OriginalLeaf, ct_ConvertSize, rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution, 
				getImageDir( (uchar)(( pc_OriginalLeaf->getImage()->c_ImageInfo.e_ImageDir + uc_1stExpandImageDir ) % ROT360 )),
				rs_III.ec_ImageColor,
				rs_III.ec_ImageTone );	// ローカルな入力画像情報(Leaf)設定.
			pc_2ndOneExpandMode->III[ ucPos ].uc_ImageDir = uc_2ndExpandImageDir;	// １画像の伸張時の回転角度.
			// 圧縮に必要なサイズを設定しておく.
			pc_2ndOneExpandMode->III[ ucPos ].pOIP->getImage()->m_IMGC_ImageImp->ul_CompressSize = comMemoryManager.getOnePageSize( pc_2ndOneExpandMode->III[ ucPos ].pOIP );
			
			//------------------------------------------------------------------------------.
			// エンジン出力シーケンスなら、1次伸張合成画像用データのクリア、.
			// それ以外なら2次伸張合成画像用データをクリアする 2005/10/25 Koshino 追加.
			//------------------------------------------------------------------------------.
			// 出力シーケンスをチェックする.
			CC_OneExpandMode *pc_OneExpandMode;
			if( rs_ThreadComPara.c_ThreadIF.b_EngOut == True ){	// エンジン出力シーケンスの時.
				pc_OneExpandMode = pc_1stOneExpandMode;
			} else {	// エンジン出力シーケンス以外（アプリ出力シーケンスを想定）の時.
				pc_OneExpandMode = pc_2ndOneExpandMode;
			}

			// 1次伸張or2次伸張のクリア.
			pc_OneExpandMode->ss_SerialNum = -1;			// 連番印字番号 連番なし(-1).
			for( uchar uc_Cnt = 0;uc_Cnt < InputPageBookLet;uc_Cnt++){
				pc_OneExpandMode->s_PageStamp.s_PageStamp1PageInfo[uc_Cnt].b_On = False;				// ページ印字 OFF.
				pc_OneExpandMode->s_DateStamp.s_DateStamp1PageInfo[uc_Cnt].b_On = False;				// 日付印字 OFF.
				pc_OneExpandMode->s_Stamp.s_Stamp1PageInfo[uc_Cnt].b_On = False;						// 定型スタンプ OFF.
				pc_OneExpandMode->s_HeaderFooterInfo.s_Header.s_HeaderFooter1PageInfo[uc_Cnt].b_isSetHeaderFooter = False;	// ヘッダ OFF.
				pc_OneExpandMode->s_HeaderFooterInfo.s_Footer.s_HeaderFooter1PageInfo[uc_Cnt].b_isSetHeaderFooter = False;	// フッタ OFF.
				pc_OneExpandMode->s_FilingNumberInfo.s_FilingNumber1PageInfo[uc_Cnt].b_On = False;							// ファイリングナンバー OFF.
			}
			pc_OneExpandMode->s_Stamp.b_ThreadOn = False;
			pc_OneExpandMode->s_PrtWatermark.b_On = False;	// ウォーターマーク OFF.
			pc_OneExpandMode->s_PrtSampleCopy.b_On = False;	// サンプルコピー OFF.
			pc_OneExpandMode->s_TTIInfo.b_blExec = False;	// True： TTI/RTI画像描画あり , False : 画像描画なし.
			pc_OneExpandMode->s_OverLayInfo.b_isOverLay = False;					// True： オーバーレイ画像描画あり , False : 画像描画なし.

			pc_OneExpandMode->s_JimonPatternIn.uc_JimonFlagTheread = 0;				// 1： 地紋画像描画あり , 0 : 画像描画なし.
			CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_0 ][ ucPos ] = pc_1stOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
		}
	}
	CC_ImgTransInfoSingletonIf::newInstance().pc_OneExpandModeLocal[ rs_ThreadComPara.ss_TransIndexNum ][ THRE_LocalExpandModeID_1 ][ 0 ] = pc_2ndOneExpandMode;	// スレッド内部　ローカルなCC_OneExpandMode.
	THRL_ThAssert( (uc_ImageNum > 1), "setLocalExpandMode_ForImageDataConvert ImageNum error %d", uc_ImageNum , 0, 0, 0, CFA14_DetailCode0x047C );
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル ローカルな入力画像情報(Leaf)設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param DOCC_Leaf* pc_Leaf ........................【出力】.
//! \param DOCC_Leaf* pc_OriginalLeaf.
//! \param TYPC_Point<float> ct_ImageSize.
//! \param TYPC_Resolution c_Resolution.
//! \param IMGE_ImageDir e_ImageDir.
//! \param IMGE_ImageColor ec_ImageColor.
//! \param IMGE_ImageTone ec_ImageTone.
//! \param Bool b_Block512.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/07/18 橋本昌	新規作成.
// 2006/06/26 morikawa	元となるLeafのImageが蓄積領域の時に、ローカルLeaf作成時はresteImageが起動後になるため、b_RestoreBusyがセットされており.
//			これがセットされているがためにdeleteImageした時に削除できなくなっていた不具合修正。.
//			対策として、スレッドのローカルImageはb_RestoreBusyを強制的にリセットする。.
//			(補足、本来はdeleteInstanceではb_RestoreBusyの設定によらず削除されるが、スレッドローカルはnewInstance及びdeleteInstanceは行わない）.
// 06/11/13 morikawa Donau初版　ImageImpColor->b_BoxJobをFalseに処理する処理は削除.
// 06/11/21 morikawa Donau 不要メンバ削除.
// 08/06/02 morikawa CQ.303435 画像出力状態の設定追加.
// 09/07/16 yashiro Emperorプリント1200dpi対応.
// 12/06/21 佐々木	1200dpiパフォーマンス改善(getImage関数のコール数削減).
// 17/04/28 日立     OP/PP共通化.
// ================================================================================================.
void CC_MultiThreadProfile::setLocalLeafInfo( DOCC_Leaf* pc_Leaf, DOCC_Leaf* pc_OriginalLeaf, TYPC_Point<float> ct_ImageSize, TYPC_Resolution c_Resolution, IMGE_ImageDir e_ImageDir, 
	IMGE_ImageColor ec_ImageColor, IMGE_ImageTone ec_ImageTone )
{
	//! 解像度が1200dpiの場合、600dpi相当に変換する(1200dpiでなければ、変換しない).
	register TYPC_Point<uint32_t> c_ImageDotSize 
	 = TYPC_Point<uint32_t>( MMtoDOT( ct_ImageSize.x, theModeInfoLib.ReCalcResolution_DPI( c_Resolution.getDpi().x ) ), 
	 					  MMtoDOT( ct_ImageSize.y, theModeInfoLib.ReCalcResolution_DPI( c_Resolution.getDpi().y ) ) );
	 Bool b_1200dpi = theModeInfoLib.chk1200Dpi( c_Resolution );
	IMGC_Image* pc_Image = pc_Leaf->getImage();	//Imageインスタンスアドレス.

	THRL_ThAssert( ( pc_Image != NULL ), "CC_MultiThreadProfile::setLocalLeafInfo(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x047D );
	pc_Image->c_ImageInfo.ct_DocSize.c_SizeMM = ct_ImageSize;	//原稿サイズ.
	pc_Image->c_ImageInfo.ct_DocSize.b_WideOn = False;	// ワイド紙指定なしとする.
	pc_Image->c_ImageInfo.ct_ImageSize.c_SizeMM = ct_ImageSize;	//画像サイズ（mm）.
	pc_Image->c_ImageInfo.ct_ImageSize.b_WideOn = False;	// ワイド紙指定なしとする.
	pc_Image->c_ImageInfo.ct_ImageDotSize = TYPC_Point<short> ( (short)c_ImageDotSize.x, (short)c_ImageDotSize.y );	//画像サイズ（dot）.
	pc_Image->c_ImageInfo.ct_TransSize = pc_Image->c_ImageInfo.ct_ImageDotSize;	//画像転送サイズ.
	pc_Image->c_ImageInfo.e_ImageDir = e_ImageDir;	//画像の向き（回転結果）：反時計回りの角度.
	pc_Image->c_ImageInfo.e_DocLP = pc_OriginalLeaf->getImage()->c_ImageInfo.e_DocLP;	//ポートレート/ランドスケープ指定.
	// 解像度.
	if( b_1200dpi == True ) {
		//! 600dpi相当への2重変換を防止するため、解像度が1200dpiの場合は、ローカルなLeaf情報の解像度も600dpi相当とする.
		//! 同時に、シーケンス層で1200dpiを判定する時は、必ずオリジナルのLeaf情報を参照するように変更.
		pc_Image->c_ImageInfo.c_Resolution.setDpi( TYPC_Point<float>( 600.0f, 600.0f ) );
	} else  {
		pc_Image->c_ImageInfo.c_Resolution = c_Resolution;
	}
	pc_Image->c_ImageInfo.ec_ColorMode = (TYPE_ColorMode)(( theColorInformation.isBlack( ec_ImageColor ) == True )?TYPE_ColorModeBlack:TYPE_ColorModeFullColor);	//カラーモード（未選択、フルカラー、ブラック）.
	pc_Image->c_ImageInfo.ec_ImageColorOrg = ec_ImageColor;		//元画像カラー情報（Lab,YMCK,RGB.....）.
	pc_Image->c_ImageInfo.ec_ImageColorResult = ec_ImageColor;	//ファイルメモリ内画像カラー情報（Lab,YMCK,RGB.....）.
	pc_Image->c_ImageInfo.ec_ImageTone = ec_ImageTone;		//画像階調情報（1bit-4bit,8bit）.
	// OP/PP共通化.
	pc_Image->c_ImageInfo.ec_ImageCompressOrg = ( ec_ImageTone == IMGE_ImageTone_1bit )?IMGE_ImageCompress_JBIG:IMGE_ImageCompress_BTCxxxAndJBIG;	//元画像圧縮情報（BTCXXX,BTC+JBIG.......）.
	pc_Image->c_ImageInfo.ec_ImageCompressResult = pc_Image->c_ImageInfo.ec_ImageCompressOrg;	//ファイルメモリ内画像圧縮状態（BTC333,BTC+JBIG......）.
	pc_Image->c_ImageInfo.e_FileFormat = pc_OriginalLeaf->getImage()->c_ImageInfo.e_FileFormat;	//ファイル形式（Text,Tiff,Pdf,Jpeg）.
	pc_Image->c_ImageInfo.uc_BandDivNum = (uchar)_roundup( (uint32_t)c_ImageDotSize.y, (uint32_t)DEF_BasicTransLine );	//分割バンド数（最大５０個）.
	pc_Image->c_ImageInfo.ss_BandLineBasic = DEF_BasicTransLine;	//基本バンドライン数.
	pc_Image->c_ImageInfo.LinkCounter = (short)IMGD_ImgNull;	//リンクカウンタ（バイナリ） スレッドでは使用しないのでNULLでよい.
	//// 【暫定】 ここから.
	//! 1200dpiの場合、1200dpi用の色テーブル情報を使用するため、引数に判定フラグを追加(なお、1200dpiのときの色数は色情報に準拠).
	pc_Image->c_ImageInfo.uc_ColorNum = theColorInformation.calcColorNum( ec_ImageColor, b_1200dpi );	// カラー成分数取得 //【暫定】.
	register uchar ucColorNo = 0;
	for( ucColorNo = 0; ucColorNo < pc_Image->c_ImageInfo.uc_ColorNum; ucColorNo++ ) {	// プレーン数設定.
		pc_Image->c_ImageInfo.uc_PlaneNum[ ucColorNo ] = theColorInformation.calcPlaneNum( ec_ImageColor, ec_ImageTone, pc_Image->c_ImageInfo.ec_ImageCompressResult ); //使用プレーン数.
	}
	//// 【暫定】 ここまで.
	pc_Image->c_ImageInfo.bl_ImageLock = False;	//画像ロック状態.
	pc_Image->c_ImageInfo.ec_ImagePlace = IMGE_ImagePlace_None;	//画像の場所（メモリ/ＨＤＤ/メモリ＆ＨＤＤ）.
	pc_Image->c_ImageInfo.ct_ReadMag = pc_OriginalLeaf->getImage()->c_ImageInfo.ct_ReadMag;	//読み込み倍率.
	pc_Image->c_ImageInfo.ss_TopMargineLineNumber = 0;	//トップマージンライン数.
	pc_Image->c_ImageInfo.ss_BottomMargineLineNumber = 0;	//ボトムマージンライン数.
	pc_Image->c_ImageInfo.ss_LeftMargineLineNumber = 0;	//レフトマージンライン数.
	pc_Image->c_ImageInfo.ss_RightMargineLineNumber = 0;	//ライトマージンライン数.
	pc_Image->c_ImageInfo.bl_LossyCompress = False;	//非可逆圧縮指定  True:非可逆圧縮.
	pc_Image->c_ImageInfo.bl_MemoryReserved = False;	//メモリ確保確認フラグ.
	pc_Image->c_ImageInfo.bl_TransPixel = False;	//点順次転送指定.
	pc_Image->c_ImageInfo.FileID = -1;	//ファイルＩＤ.
	pc_Image->c_ImageInfo.bl_TransPixelAtr = False;	//属性bit点順次転送指定.
	//// ここから　スレッド未使用 とりあえず設定する.
	pc_Image->c_ImageInfo.c_PageMemoryPointer = IMGD_ImgNull;	//画像メモリポインタ（バイナリ）.
	pc_Image->c_ImageInfo.c_PageMemorySize = 0;	//画像メモリサイズ（バイナリ）.
	pc_Image->c_ImageInfo.e_CompressEndMode = IMGE_CompressNotEnd;	//圧縮完了モード.
	pc_Image->c_ImageInfo.ct_RotationTransSize = pc_Image->c_ImageInfo.ct_ImageDotSize;	// スレッド未使用.
	pc_Image->c_ImageInfo.PageMemoryPointerOffset = 0;	//画像メモリポインタオフセット（バイナリ）.
	pc_Image->c_ImageInfo.PageMemoryOffsetPlaceSize = 0;	//画像メモリオフセット先サイズ（バイナリ）.
	pc_Image->c_ImageInfo.uc_BandDivNumAfter = 0;		//画像回転後、分割バンド数.
	pc_Image->c_ImageInfo.uc_BandDivLineBasicAfter = 0;	//画像回転後、基本バンドライン数.
	pc_Image->c_ImageInfo.uc_BandDivLineNumberAfter = 0;	//画像回転後、バンド番号.
	pc_Image->c_ImageInfo.ct_RotaionImageSize = pc_Image->c_ImageInfo.ct_ImageDotSize;	// スレッド未使用.
	pc_Image->c_ImageInfo.e_RotationImageDir = IMGE_ImageDir0;		//画像回転後の回転角度.
	///// ここまで　スレッド未使用 とりあえず設定する.
	
	_memcpy( pc_Image->m_IMGC_ImageImp, pc_OriginalLeaf->getImage()->m_IMGC_ImageImp, sizeof( IMGC_ImageImp ) );	// まずコピー.
	register short i = 0;
	pc_Image->m_IMGC_ImageImp->uc_IJCBandDivNum = (uchar)_roundup( c_ImageDotSize.y , THRD_JBIG_BLOCK_HEIGHT );	// 【内部】分割バンド数.
	pc_Image->m_IMGC_ImageImp->ss_IJCBandDivLineBasic = THRD_JBIG_BLOCK_HEIGHT;		// 【内部】分割バンド基本ライン数.
	pc_Image->m_IMGC_ImageImp->ss_IJCBandDivLineLast = (short)( c_ImageDotSize.y % THRD_JBIG_BLOCK_HEIGHT );	// 【内部】分割バンド最終ライン数.
	pc_Image->m_IMGC_ImageImp->uc_IJCBlockDivNum = (uchar)_roundup( c_ImageDotSize.x, THRD_JBIG_BLOCK_WIDTH );		// 【内部】分割ブロック数.
	pc_Image->m_IMGC_ImageImp->ss_IJCBlockDivWidthBasic = THRD_JBIG_BLOCK_WIDTH;		// 【内部】分割ブロック基本幅.
	pc_Image->m_IMGC_ImageImp->ss_IJCBlockDivWidthLast = (short)( c_ImageDotSize.x % THRD_JBIG_BLOCK_WIDTH );		// 【内部】分割ブロック最終幅.
	pc_Image->m_IMGC_ImageImp->uc_JbigColorNum = theColorInformation.getColorNum( pc_Leaf, True );	// カラー成分数取得 //【暫定】.
	for( ucColorNo = 0; ucColorNo < pc_Image->m_IMGC_ImageImp->uc_JbigColorNum; ucColorNo++ ) {	// プレーン数設定.
		pc_Image->m_IMGC_ImageImp->uc_JbigPlaneNum[ ucColorNo ] = theColorInformation.getPlaneNum( pc_Image, ucColorNo, True ); //使用プレーン数.
	}
	pc_Image->m_IMGC_ImageImp->e_CompressColorMode = pc_Image->c_ImageInfo.ec_ColorMode;	// 圧縮時のカラーモード.
	pc_Image->m_IMGC_ImageImp->ss_BandLineLast = (short)( c_ImageDotSize.y % DEF_BasicTransLine );	// 最終バンドライン数.
	pc_Image->m_IMGC_ImageImp->b_CompressSeq = False;	// 圧縮フラグ.
	pc_Image->m_IMGC_ImageImp->e_HDDTransKind = IMGE_HDDTransKind_None;		// 詳細転送種別（ビット列）.
	pc_Image->m_IMGC_ImageImp->uc_TransDataKindNum = 0;	// 転送種別キュー数(Max=2).
	for( i = 0; i < IMGE_TransDataKindNum; i++ ) {
		pc_Image->m_IMGC_ImageImp->em_TransDataKind[ i ] = IMGE_TransDataKind_None;
	}
	pc_Image->m_IMGC_ImageImp->e_InputPagePlace = IMGE_ImagePlace_None;	// 管理の場所（メモリ／ＨＤＤ／メモリ＆HDD）初:alloc時決定.
	pc_Image->m_IMGC_ImageImp->c_ImageDataHDDBlock = CC_HDDBlock();	// 画像管理情報HDD用（１ページ単位）【注意】ページ転送完了時にかならず開放.
	pc_Image->m_IMGC_ImageImp->c_HDDBlock = CC_HDDBlock();			// ＨＤＤの管理用（１ページ単位）【注意】ページ転送完了時にかならず開放.
	pc_Image->m_IMGC_ImageImp->pc_OneImageInfoData = NULL;		// 画像管理情報ポインタ(NULL=無し).
	pc_Image->m_IMGC_ImageImp->c_ArrayGetMemory = NULL;		// メモリ取得時のアレイ情報（使用後は必ずNULLにすること）.
	pc_Image->m_IMGC_ImageImp->uc_OneBandCompress = 0;	// PCプリント時のバンド圧縮処理用.
	pc_Image->m_IMGC_ImageImp->b_ColorSetSeq = False;	// COLOR SETフラグ.
	pc_Image->m_IMGC_ImageImp->b_LockDelete = False;
	pc_Image->m_IMGC_ImageImp->b_ImageBufExist = False;		// 画像がバッファメモリに存在するとき：True、存在しないとき：False.
	pc_Image->m_IMGC_ImageImp->e_MPID = EN_MPID_0;	// メモリプール指定.
	pc_Image->m_IMGC_ImageImp->b_ImageDelete = False;	// Image削除フラグ.
	pc_Image->m_IMGC_ImageImp->e_DeleteMode = IMGE_DeleteMode_Non;
	pc_Image->m_IMGC_ImageImp->ul_CompressSize = 0;	// 圧縮サイズ.

// CQ.303435 Start.
	pc_Image->m_IMGC_ImageImp->e_OutputStatus = IMGE_OutputStatusUnKnown;	// 画像出力状態.
// CQ.303435 End.
	
	// 再度BOX保存されないように初期値を代入.
	pc_Image->m_IMGC_ImageImp->e_IPETypeInfo = IMGE_IPEType_Non;  
	pc_Image->m_IMGC_ImageImp->e_IPEType = IMGE_IPEType_Non; 	

	//【問題点55627対応】060410 太田(慎) ロ－カル設定 状態変数追加(S).
	pc_Image->m_IMGC_ImageImp->b_isThreadLocal = True;
	//【問題点55627対応】060410 太田(慎) ロ－カル設定 状態変数追加(E).

	// 2006/06/26 morikawa　履歴参照.
	pc_Image->m_IMGC_ImageImp->b_RestoreBusy = False;
	
	pc_Image->attachPool( IMGC_ImageMemoryPool::newInstance(IMGE_FileMemory) );

	// 2019/2/28 SCD2 伊藤史. EagleL MR1 制御構成変更No.1 BOX画像(KM形式)インポート対応（Eagle世代越リストア).
	IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();
	comMemoryManager.pc_OneImageInfoData512 = NULL;		// 画像管理情報ポインタ(NULL=無し).

}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル 画像回転角度(反時計回り)取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_ImageDir.
//! <!--戻値-->.
//! \return IMGE_ImageDir e_ImageDir.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
// 2005/07/18 橋本昌	新規作成.
// ================================================================================================.
IMGE_ImageDir CC_MultiThreadProfile::getImageDir( uchar uc_ImageDir )
{
	register IMGE_ImageDir e_ImageDir = IMGE_ImageDir0;	// 0度.
	switch( uc_ImageDir ){
		case ROT0:
		case ROT360:
			e_ImageDir = IMGE_ImageDir0;	// 0度.
			break;
		case ROT90:
			e_ImageDir = IMGE_ImageDir90;	// 90度.
			break;
		case ROT180:
			e_ImageDir = IMGE_ImageDir180;	// 180度.
			break;
		case ROT270:
			e_ImageDir = IMGE_ImageDir270;	// 270度.
			break;
		default:
			THRL_ThAssert( False ,"CC_MultiThreadProfile::getImageDir %d Error", uc_ImageDir , 0, 0, 0, CFA14_DetailCode0x047E );
			break;
	}
	
	return e_ImageDir;
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル DMAの開放（一部のみ開放）.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pc_OneImgTransInfo.
//! \param us_Index.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! 一部のDMAのみ開放（画像合成対応）.
//! <!--履歴-->.
// 2006/01/26 Koshino(Sky)	新規作成.
// 2006/05/17 Koshino(Sky)	戻り値をvoidからucharに変更した.
// 2007/05/16 yokoi			排他制御を追加.
// 2014/06/02 ogura	 		CQ.390862 セマフォログ追加.
// ================================================================================================.
Bool CC_MultiThreadProfile::releaseOneDMAResource(  CC_OneImgTransInfo* pc_OneImgTransInfo
												  , ushort				us_Index )
{
	semTake_Multithread( THRD_SemLog_MultiThread_releaseOneDMAResource );

	//----------------------------.
	// パラメータチェック.
	//----------------------------.
	THRL_ThAssert( pc_OneImgTransInfo != NULL ,"releaseOneDMAResource Param NG pc_OneImgTransInfo is Null" , 0, 0, 0, 0, CFA14_DetailCode0x047F );
	THRL_ThAssert( pc_OneImgTransInfo->e_usedDma[us_Index] != THRE_DmaId_None ,"releaseOneDMAResource Param NG usedDma = %d us_Index = %d" ,pc_OneImgTransInfo->e_usedDma[us_Index] , us_Index , 0, 0, CFA14_DetailCode0x0480 );

	//----------------------------.
	// リソース開放.
	//----------------------------.
	Bool b_Ret = pc_DmaResMan[pc_OneImgTransInfo->e_usedDma[us_Index]]->release( pc_OneImgTransInfo );

	semGive_Multithread( THRD_SemLog_MultiThread_releaseOneDMAResource );

	return b_Ret;
}

// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル バッファリソースの開放（一部のみ開放）.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pc_OneImgTransInfo.
//! \param us_Index            s_usedBufのインデックス.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! 一部のバッファリソースのみ開放（画像合成対応）.
//! <!--履歴-->.
// 2007/04/05 takamoto	新規作成.
// 2007/05/16 yokoi		排他制御を追加.
// 2014/06/02 ogura		CQ.390862 セマフォログ追加.
// ================================================================================================.
Bool CC_MultiThreadProfile::releaseOneBufferResource(  CC_OneImgTransInfo* pc_OneImgTransInfo, ushort us_Index )
{
	Bool b_Ret = False;
	
	semTake_Multithread( THRD_SemLog_MultiThread_releaseOneBufferResource );

	//----------------------------.
	// パラメータチェック.
	//----------------------------.
	THRL_ThAssert( pc_OneImgTransInfo != NULL ,"releaseOneBufferResource Param NG pc_OneImgTransInfo is Null" , 0, 0, 0, 0, CFA14_DetailCode0x0481 );

	//----------------------------.
	// リソース開放.
	//----------------------------.
	CC_OneImgTransInfo* pc_Owner = pc_BufResMan[pc_OneImgTransInfo->s_usedBuf[us_Index].e_usedBuf]->getOwner( pc_OneImgTransInfo->s_usedBuf[us_Index].b_isWrite );
	if( pc_Owner == pc_OneImgTransInfo ){
		// 所有者の場合.
		b_Ret = pc_BufResMan[pc_OneImgTransInfo->s_usedBuf[us_Index].e_usedBuf]->release( pc_OneImgTransInfo, pc_OneImgTransInfo->s_usedBuf[us_Index].b_isWrite );
	}

	semGive_Multithread( THRD_SemLog_MultiThread_releaseOneBufferResource );

	return b_Ret;
}

// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 START.
// ================================================================================================.
//! <!--機能--> クリアDMAリソース確保処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return クリアDMAリソース確保できたかどうか	True:確保可.
//! <!--詳細-->.
//! クリアDMAリソース確保処理.
//! <!--履歴-->.
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応.
// 2008/09/05 R.Suzuki CQ.309145 1Pass対応 Asic200 3枚目のDMA IDを追加.
// 2013/05/10 Sky Asic 3枚目, 4枚目のDMA IDを追加.
// 2014/06/02 ogura		CQ.390862 セマフォログ追加.
// 2014/06/20 伊藤史.  CQ500469,500471 分割読出マルチ問題対策. DMA調停問題対応.
// 2015/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
Bool CC_MultiThreadProfile::allocClrDmaResource( THRS_MsgMemoryClearInfo* ps_MsgMemClrInfo )
{
	Bool b_Ans = True;	// 戻り値を正常終了で初期化.
	uchar uc_DmaId = THRE_DmaId_None;	//	DmaID.
	
	if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_0){	//	ASIC 1枚目.
		uc_DmaId = THRE_DmaId_MemClr;	// クリアDMA.
	}else if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_1){	//	ASIC 2枚目.
		uc_DmaId = THRE_DmaId_MemClr_2;	// クリアDMA.
	}else if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_2){	//	ASIC 3枚目.
		uc_DmaId = THRE_DmaId_MemClr_3;	// クリアDMA.
	}else{
		b_Ans = False;	// クリアDMAのリソース確保不可.
		THRL_ThAssert( False , "CC_MultiThreadProfile::allocClrDmaResource : CtrID Error CtrID %d !!", ps_MsgMemClrInfo->e_CtrID , 0, 0, 0, CFA14_DetailCode0x0482 );
	}
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 START.
	//	クリア時はJobIDは0x1、AppIDをTHRE_AppID_ThreadInternalProc(スレッド内部処理)とする.
	cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].ul_JobID = 0x1;
	cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].st_TransModePara.en_AppIDSelThread = THRE_AppID_ThreadInternalProc;
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 END.
	semTake_Multithread( THRD_SemLog_MultiThread_allocClrDmaResource );
	switch( pc_DmaResMan[uc_DmaId]->check( &cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID] ) ){
		case THRE_ResourceCheck_EnableAllocation:
			// 確保/予約可能.
			// 2014/06/20 伊藤史.  CQ500469,500471 分割読出マルチ問題対策. DMA調停問題対応.
			b_Ans = pc_DmaResMan[uc_DmaId]->alloc( &cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID],0,0 );	// 2014/6/5 伊藤史.
			THRL_ThAssert( b_Ans, "AllocResource Dma error" , 0, 0, 0, 0, CFA14_DetailCode0x0483 );
			break;
		case THRE_ResourceCheck_EnableReservation:
			// 予約可能時.
			// リソース確保したままとする.
			b_Ans = False;
			break;
		case THRE_ResourceCheck_Disable:
			// 確保/予約不可.
			b_Ans = False;	// クリアDMAのリソース確保不可.
			break;
		default:
			THRL_ThAssert( False, "checkClrDmaQueue resCheck error" , 0, 0, 0, 0, CFA14_DetailCode0x0484 );
			break;
	}
	semGive_Multithread( THRD_SemLog_MultiThread_allocClrDmaResource );
	return b_Ans;
}
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 END.

// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 START.
// ================================================================================================.
//! <!--機能--> バッファメモリクリア完了.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! バッファメモリクリア完了.
//! <!--履歴-->.
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応.
// 2006/06/01 yokoi クリア完了処理と、ログ表示の順序を逆にした(完了後からNVRAMにログを取り出すので).
// 2007/05/28 yokoi スレッドのダミーアドレス取得を、initBufMem()からPCI側メモリクリア完了時にタイミングを変更(コード整理のため).
// 08/01/09 morikawa FPGA検証のためにメモリクリヤしない時はこの関数はコールされないのでダミーアドレスの設定は別関数で行うように修正.
// 08/09/04 R.Suzuki CQ.309145 1Pass対応 Asic200 3枚目のDMA IDを追加.
// 12/09/17 M.Koshimo CQ.371726 SDRAMの初期化完了が後になっても初期化完了状態へ移行するように修正.
// 2013/05/10 Sky Asic 3枚目, 4枚目のDMA IDを追加.
// 17/03/15 Matsuoka 排他制御漏れ修正.
// 2015/10/06 Sky システム統合SoC(S800)対応.
// 2021/12/17 日立 OP_BTS-36869：【SYSQA-MSSBK_028】スリープ復帰ランニング中にC-FE51発生問題対応.
// ================================================================================================.
void CC_MultiThreadProfile::MemClrComplete( THRS_MsgMemoryClearInfo* ps_MsgMemClrInfo )
{
	Bool b_Ret = False;
	uchar uc_DmaId = THRE_DmaId_None;	//	DmaID.
	ushort us_Index = 0;
	uchar uc_ClrCompleteNum = 0;	// クリア完了した数.

	if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_0){	//	ASIC 1枚目.
		uc_DmaId = THRE_DmaId_MemClr;	// クリアDMA.
	}else if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_1){	//	ASIC 2枚目.
		uc_DmaId = THRE_DmaId_MemClr_2;	// クリアDMA.
	}else if(ps_MsgMemClrInfo->e_CtrID == THRE_CtrID_2){	//	ASIC 3枚目.
		uc_DmaId = THRE_DmaId_MemClr_3;	// クリアDMA.
	}else{
		b_Ret = False;	// クリアDMAのリソース確保不可.
		THRL_ThAssert( False , "CC_MultiThreadProfile::MemClrComplete : CtrID Error CtrID %d !!", ps_MsgMemClrInfo->e_CtrID , 0, 0, 0, CFA14_DetailCode0x0485 );
	}

	// 2017/03/15 Matsuoka 排他制御漏れ修正.
	semTake_Multithread(THRD_SemLog_MultiThread_MemClrComplete);

	// 繰り返し起動の終了回数カウント.
	cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].us_RepeatEndNum++;
	THRL_SetThLog( 110, THRE_DebugLogType_MTCtrLog, 12, True, 
		ps_MsgMemClrInfo->e_CtrID, cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].us_StartTransNum, cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].us_RepeatEndNum );
	
	// クリア要求数完了したか.
	if( cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].us_RepeatEndNum >= cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].us_StartTransNum ){
		// 完了クリアDMA07 リソース開放.
		b_Ret = pc_DmaResMan[uc_DmaId]->release( &cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID] );
		THRL_ThAssert( b_Ret, "MemClrComplete resource release error" , 0, 0, 0, 0, CFA14_DetailCode0x0486 );
		
		for( us_Index = 0; us_Index < THRD_CLRDMANUM; us_Index++ ){
			if(cc_ClearOneImgTransInfo[us_Index].us_RepeatEndNum >= cc_ClearOneImgTransInfo[us_Index].us_StartTransNum){
				uc_ClrCompleteNum++;	// クリアが完了した数をカウントアップ(クリアDMA単位).
			}
		}
		if( ((uc_ClrCompleteNum == THRD_CLRDMANUM) && (getPciBufClrState() == EN_PciBufClrBusy) && (ps_MsgMemClrInfo->b_OutputPci == True) && (ps_MsgMemClrInfo->b_OutputSdram == False)) ||
				((uc_ClrCompleteNum == THRD_CLRDMANUM) && (getPciBufClrState() == EN_PciBufClrBusy) && (ps_MsgMemClrInfo->b_OutputPci == False) && (ps_MsgMemClrInfo->b_OutputSdram == True)) ){	//	初期化クリア中ならば.
			
			// クリアDMA分クリア完了かつクリアPCI上のメモリクリア中 かつ 出力先がPCI かつ 出力先がSDRAMではないとき.
			THRL_SetThLog( 111, THRE_DebugLogType_MTCtrLog, 15, True);
			setPciBufClrState( EN_PciBufClrComplete );// PCI上のバッファメモリ初期化クリア完了とする.
			if( ss_Wait == 0 ) {
				comMultiThreadProfile.setMemoryClearReqState( EN_MemoryClearReqOff );	// 省電力復帰メモリクリア要求なし設定.
			} else {
				printf(">>>MemClrComplete():Not Change EN_MemoryClearReqOff\n");		// デバッグ用ルート.
			}
		}
		cc_ClearOneImgTransInfo[ps_MsgMemClrInfo->e_CtrID].init();	// 初期化.
		searchTransExec();
	}
	// 2017/03/15 Matsuoka 排他制御漏れ修正.
	semGive_Multithread(THRD_SemLog_MultiThread_MemClrComplete);
//2019/12/02 Sky 【自動測定】起動イベントの通知対応(Step2) start.
	/* メモリクリア終了を通知 */
	THRF_setEventRecord(THRD_EventRecord_MemoryClearEnd);
//2019/12/02 Sky 【自動測定】起動イベントの通知対応(Step2) end.
}
// 2006/04/27 sugimoto DMA03バッファアンダーラン対応 END.

