// ================================================================================================.
//! <!--機能--> マルチスレッドプロファイル スレッドMsg送信遅延 Msg送信処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! Msg遅延が発生しているどうかの確認は影響範囲を次の場合に限定する。\n.
//! ・IRからの画像データの入力のときの入力の最終スレッド \n.
//! ・Fieryからの入力のときの入力の最終スレッド \n.
//! 以上をまとめると スレッド外部→バッファの時 \n.
//! \n.
//! <!--履歴-->.
// 2006/04/27 橋本昌	新規作成.
// 2012/11/05 山内 CQ374002対応(BufToBufとBufToExtの逆転防止)
// 2020/06/04 Sky		FA17発生時にエンジン制御JAMにする対応.
// ================================================================================================.
void CC_MultiThreadProfile::sendThreadDelayMsg( CC_OneImgTransInfo* pcc_OneImgTransInfo )
{
	THRL_ThAssert( pcc_OneImgTransInfo != NULL  ,"CC_MultiThreadProfile::sendThreadDelayMsg Error!! pcc_OneImgTransInfo NULL!!" , 0, 0, 0, 0, CFA14_DetailCode0x0487 );
	THRL_ThAssert( pcc_OneImgTransInfo->ps_DelayMsgParameter != NULL  ,"CC_MultiThreadProfile::sendThreadDelayMsg Error!! ps_DelayMsgParameter NULL!!" , 0, 0, 0, 0, CFA14_DetailCode0x0488 );
	
	// スレッド外部→バッファ転送以外は現状使用外.
	// 	FA16の回避（FileToBufとBufToExtの逆転防止）対応 2011/03/04 Sky越野（ES2基板検証時の問題対応のためマージした）.
	//	CQ374002対応 (BufToBufとBufToExtの逆転防止) THRE_ThrID_BufToBufをAsert条件から除外.
	// comment 2017/04/24 Sky-西村 AR1019531 5ジョブ投入後にジャム発生直後FA14発生する問題の対応.
	THRL_ThAssert( ( (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_ExtToBuf) 
				  || (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_FileToBuf) 
				  || (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_BufToBuf)
				  || (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_BufToFile) ) ,"CC_MultiThreadProfile::sendThreadDelayMsg Error!! ThId %d", pcc_OneImgTransInfo->en_ThreadID , 0, 0, 0, CFA14_DetailCode0x0489 );
	
	if( pcc_OneImgTransInfo->ps_DelayMsgParameter->b_Send == False ){
		// 遅延Msg送信済みフラグ が未送信(False)の時.
		pcc_OneImgTransInfo->ps_DelayMsgParameter->b_Send = True;	// 遅延Msg送信済みフラグ True:送信済み に設定.
		
		register THRS_ThreadDelayMsgParameter* ps_MsgPara = pcc_OneImgTransInfo->ps_DelayMsgParameter;
		sendMessage( ps_MsgPara->ev_TaskID, ps_MsgPara->message, (uintptr_t)ps_MsgPara->option );
		
		extern uchar guc_ctrlJAMFlg;

		THRL_SetThLog( 112, THRE_DebugLogType_MTCtrLog, 255, False,
			ps_MsgPara->ev_TaskID, ps_MsgPara->message, ps_MsgPara->option, guc_ctrlJAMFlg );

		// BufToExtのendTransが遅延している場合、FA17の制御JAMを発生させるため.
		// エンジン出力バッファのリソースを解放する.
		if( guc_ctrlJAMFlg == 1 && ps_MsgPara->ev_TaskID == TID_BufToExt &&  ps_MsgPara->message == DEF_TM_ThTransEnd )
		{
			guc_ctrlJAMFlg = 0;
			SYSF_logMsg("(%010u)sendThreadDelayMsg \n", SYSF_tickGet());
			pc_BufResMan[THRE_BufId_EngOut]->clearBuf_forCtrlJAM( getCtrId(pcc_OneImgTransInfo->e_usedDma[0]) );
		}
	}
}

// 2006/08/10 Koshino TTI印字対応  Start.
// ================================================================================================.
//! <!--機能--> 印字開始位置の補正関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param IMGE_ImageDir e_Dir           ... 回転角度.
//! \param TYPC_Point<float> ct_PictPoint... 算出前の位置.
//! \param TYPC_Point<float> ct_PictSize ... 絵のサイズ.
//! \param TYPC_Point<float> ct_AreaSize ... 領域のサイズ.
//! <!--戻値-->.
//! \return TYPC_Point<float> ct_RetPoint ... 補正後の座標.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  06/08/11 Koshino(Sky) 新規作成.
// ================================================================================================.
TYPC_Point<float>  CC_MultiThreadProfile::correctLineStartPoint( IMGE_ImageDir e_Dir
															   , TYPC_Point<float> ct_PictPoint
															   , TYPC_Point<float> ct_PictSize
															   , TYPC_Point<float> ct_AreaSize
																) 
{

	THRL_SetThLog( 113, THRE_DebugLogType_Combine, 255, False );

	// 補正処理.
	TYPC_Point<float> ct_RetPoint = calcCorrectLineStartPoint( e_Dir
															 , ct_PictPoint
															 , ct_PictSize
															 , ct_AreaSize
															 );
	return( ct_RetPoint );

}

/*==================================================================================================
［機能］	画像縮小時の印字開始位置の補正値算出関数 
----------------------------------------------------------------------------------------------------
［引数]		IMGE_ImageDir e_Dir           ... 回転角度
			TYPC_Point<float> ct_PictPoint... 算出前の位置
			TYPC_Point<float> ct_PictSize ... 絵のサイズ
			TYPC_Point<float> ct_AreaSize ... 領域のサイズ
［戻値］	ミリ値
［ウォークスルー］ 未実施
----------------------------------------------------------------------------------------------------
 [履歴]	2006/08/11	Koshino(Sky)	新規作成 
 		2006/08/23	Koshino(Sky)	180度の時の回転後の座標を用紙サイズで補正する処理が 
 									間違っていたので修正した。 
==================================================================================================*/
TYPC_Point<float> CC_MultiThreadProfile::calcCorrectLineStartPoint( IMGE_ImageDir e_Dir
																  , TYPC_Point<float> ct_PictPoint
																  , TYPC_Point<float> ct_PictSize
																  , TYPC_Point<float> ct_AreaSize
																  ) 

{
	THRL_SetThLog( 114, THRE_DebugLogType_Combine, 255, False );

	// 回転前の補正座標を求める.
	TYPC_Point<float> ct_Before = calcCorrectLineStartBeforePoint( e_Dir
																 , ct_PictPoint
																 , ct_PictSize );

	// 回転後の座標を求める.
	TYPC_Point<float> ct_After = calcCorrectLineStartAfterPoint( e_Dir
															   , ct_Before );

	// 回転後の座標を用紙サイズで補正する.
	switch( e_Dir % IMGE_ImageDir360 ){
		case IMGE_ImageDir0:
			break;
		case IMGE_ImageDir90:
			ct_After.y += ct_AreaSize.x;
			break;
		case IMGE_ImageDir180:
			ct_After.x += ct_AreaSize.x;	// 2006/08/23 Koshino 修正.
			ct_After.y += ct_AreaSize.y;	// 2006/08/23 Koshino 修正.
			break;
		case IMGE_ImageDir270:
			ct_After.x += ct_AreaSize.y;
			break;
		default:
			THRL_ThAssert( False, "THRC_MakeCombineImage::calcCorrectLineStartPoint NG" , 0, 0, 0, 0, CFA14_DetailCode0x048A );
			break;
	}
	//用紙サイズ.
	return( ct_After );

}
/*==================================================================================================
［機能］	位置の補正値算出関数 
----------------------------------------------------------------------------------------------------
［引数]		IMGE_ImageDir e_Dir           ... 回転角度
			TYPC_Point<float> ct_PictPoint... 算出前の位置
			TYPC_Point<float> ct_PictSize ... 絵のサイズ
［戻値］	ミリ値
［ウォークスルー］ 未実施
----------------------------------------------------------------------------------------------------
 [履歴]	2006/08/11	Koshino(Sky)	新規作成
==================================================================================================*/
TYPC_Point<float> CC_MultiThreadProfile::calcCorrectLineStartBeforePoint( IMGE_ImageDir e_Dir
																		, TYPC_Point<float> ct_PictPoint
																		, TYPC_Point<float> ct_PictSize ) 
{
	THRL_SetThLog( 115, THRE_DebugLogType_Combine, 255, False );
	TYPC_Point<float>	ct_wCorrectStart;
	float f_xb = ct_PictPoint.x;
	float f_yb = ct_PictPoint.y;


	// ＜座標算出手順＞.
	// 1.入力画像の角度ΘIをチェックし、どこの座標を算出するかを求める.
	// ↓図のようになる。.
	// 0°_________________________90°-.
	// |                            |  |.
	// |          合成画像          |  Y.
	// |____________________________|  |.
	// 270°                      180°-.
	// |------------X---------------|.
	//.

	switch( e_Dir % IMGE_ImageDir360 ){
		case IMGE_ImageDir0:
			break;
		case IMGE_ImageDir90:
			f_xb += ct_PictSize.x;
			break;
		case IMGE_ImageDir180:
			f_xb += ct_PictSize.x;
			f_yb += ct_PictSize.y;
			break;
		case IMGE_ImageDir270:
			f_yb += ct_PictSize.y;
			break;
		default:
			THRL_ThAssert( False, "THRC_MakeCombineImage::calcCorrectLineStartBeforePoint invalid param e_InputImageDir = %d",e_Dir , 0, 0, 0, CFA14_DetailCode0x048B );
			break;
	}
	ct_wCorrectStart.x = f_xb;
	ct_wCorrectStart.y = f_yb;
	return( ct_wCorrectStart );
}

/*==================================================================================================
［機能］	画像縮小時の印字開始位置の補正値算出関数 
----------------------------------------------------------------------------------------------------
［引数]		IMGE_ImageDir     e_Dir       ... 回転角度
			TYPC_Point<float> ct_Before   ... 算出前の位置
［戻値］	ミリ値
［ウォークスルー］ 未実施
----------------------------------------------------------------------------------------------------
 [履歴]	2006/08/11	Koshino(Sky)	新規作成
==================================================================================================*/
TYPC_Point<float> CC_MultiThreadProfile::calcCorrectLineStartAfterPoint( IMGE_ImageDir e_Dir
																	   , TYPC_Point<float> ct_Before ) 
{
	THRL_SetThLog( 116, THRE_DebugLogType_Combine, 255, False );
	float f_xa = 0;
	float f_ya = 0;
	TYPC_Point<float> ct_After;

	switch( e_Dir % IMGE_ImageDir360 ){	// 2006/04/21 Koshino(Sky) パラメータの型を変更.
		case IMGE_ImageDir0:
			f_xa = ct_Before.x;
			f_ya = ct_Before.y;
			break;
		case IMGE_ImageDir90:
			f_xa = ct_Before.y;
			f_ya = (-1) * ct_Before.x;
			break;
		case IMGE_ImageDir180:
			f_xa = (-1) * ct_Before.x;
			f_ya = (-1) * ct_Before.y;
			break;
		case IMGE_ImageDir270:
			f_xa = (-1) * ct_Before.y;
			f_ya = ct_Before.x;
			break;
		default:
			THRL_ThAssert( False, "THRC_MakeCombineImage::calcCorrectLineStartAfterPoint invalid param us_Dir = %d",e_Dir , 0, 0, 0, CFA14_DetailCode0x048C );	// 2006/04/21 Koshino(Sky) パラメータの型を変更.
			break;
	}
	ct_After.x = f_xa;
	ct_After.y = f_ya;
	return( ct_After );
}

