ushort CC_MultiThreadProfile::getAppInConvDiv1200dpiBasicTransLine( void )
{
	static ushort us_BasicTransLine = 0;

	if( us_BasicTransLine == 0 ) {
		// Asic2014DS装着時は64lineで転送する.
		us_BasicTransLine = DEF_BasicTransLine / 4;
	}
	return us_BasicTransLine;
}

