// ================================================================================================.
//! <!--機能--> 画像制御部(高速タスク)ID設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_DmaId e_DmaId .......................... DMAID.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ..... 画像転送管理情報のポインタ.
//! \param const ST_ThreadComPara& rs_ThreadComPara .... スレッドパラメータへのポインタ.
//! <!--戻値-->.
//! \return THRE_ArbiID アービタID.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/13 Sky ZeusS対応 selCtrArbiIdから移動.
//  15/10/06 Sky システム統合SoC(S800)対応.
//  18/11/22 Sky EagleHのPCFAX多値(AirPrintFax)対応.
// ================================================================================================.
THRE_ArbiID CC_MultiThreadProfile::getArbiId( THRE_DmaId e_DmaId, const CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRE_ArbiID   e_RetArbiId = THRE_ArbiID_None;
	
	// アプリ種別で調停器IDを決定.
	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ){
		// 入力側.
		switch( pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread )
		{
			case THRE_AppID_Copy:
			case THRE_AppID_InternalScan:
			case THRE_AppID_FaxSend:
			case THRE_AppID_IFaxSend:
				if( pcc_OneImgTransInfo->en_TaskID == THRE_TaskID_InputIRDup ){
					e_RetArbiId = THRE_ArbiID_IRDup;
				}else{
					e_RetArbiId = THRE_ArbiID_IR;
				}
				break;
			case THRE_AppID_InternalPrint:
			case THRE_AppID_PCFax:
				if(( THRE_DmaId_CmpExpStart_2 <= e_DmaId ) && ( THRE_DmaId_CmpExpEnd_2 >= e_DmaId )){		//! Asic2枚目の圧縮伸張器.
					e_RetArbiId = THRE_ArbiID_App2;
				}else{
					e_RetArbiId = THRE_ArbiID_App;
				}
				break;
			case THRE_AppID_PushImage:
				if( IMGE_BlockSizeConvertStatePushImage == IMGG_getBlockSizeConvertRestoreDataState() ){
						e_RetArbiId = THRE_ArbiID_IR;
				} else {
				if(( THRE_DmaId_CmpExpStart_2 <= e_DmaId ) && ( THRE_DmaId_CmpExpEnd_2 >= e_DmaId )){		//! Asic2枚目の圧縮伸張器.
					e_RetArbiId = THRE_ArbiID_App2;
				}else{
					e_RetArbiId = THRE_ArbiID_App;
				}
				}
				break;
			case THRE_AppID_ExternalPrint:
				e_RetArbiId = THRE_ArbiID_Fiery;
				break;
			case THRE_AppID_FaxRecv:
			case THRE_AppID_IFaxRecv:
				if( chk1bitMode( rs_ThreadComPara.c_ThreadIF.pc_Leaf ) == True ){
					switch( rs_ThreadComPara.e_FaxLineID ){
						case EN_FaxLineID_0:
							e_RetArbiId = THRE_ArbiID_iFax;
							break;
						case EN_FaxLineID_1:
						case EN_FaxLineID_3:
							e_RetArbiId = THRE_ArbiID_Fax1;
							break;
						case EN_FaxLineID_2:
						case EN_FaxLineID_4:
							e_RetArbiId = THRE_ArbiID_Fax2;
							break;
						default:
							THRL_ThAssert( False, "getArbiId FaxId error Id=%d", rs_ThreadComPara.e_FaxLineID , 0, 0, 0, CFA14_DetailCode0x0816 );
							break;
					}
				} else {
					e_RetArbiId = THRE_ArbiID_App;
				}
				break;
			default:
				e_RetArbiId = THRE_ArbiID_None;
				break;
		}
	} else {
		// 出力側.
		switch( pcc_OneImgTransInfo->st_TransModePara.en_AppIDSelThread )
		{
			case THRE_AppID_Copy:
			case THRE_AppID_FaxRecv:
			case THRE_AppID_IFaxRecv:
			case THRE_AppID_InternalPrint:
			case THRE_AppID_ExternalPrint:
			case THRE_AppID_InternalJpegPrint:
				e_RetArbiId = THRE_ArbiID_Eng;
				break;
			case THRE_AppID_InternalScan:
			case THRE_AppID_Preview:
				e_RetArbiId = THRE_ArbiID_App;
				break;
			case THRE_AppID_PopImage:
				if( IMGE_BlockSizeConvertStatePopImage == IMGG_getBlockSizeConvertRestoreDataState() ){
					e_RetArbiId = THRE_ArbiID_Eng;
				} else {
				e_RetArbiId = THRE_ArbiID_App;
				}
				break;
			case THRE_AppID_FaxSend:
			case THRE_AppID_IFaxSend:
			case THRE_AppID_PCFax:
			case THRE_AppID_FaxCompTool:
				switch( rs_ThreadComPara.e_FaxLineID ){
					case EN_FaxLineID_0:
						e_RetArbiId = THRE_ArbiID_iFax;
						break;
					case EN_FaxLineID_1:
					case EN_FaxLineID_3:
						e_RetArbiId = THRE_ArbiID_Fax1;
						break;
					case EN_FaxLineID_2:
					case EN_FaxLineID_4:
						e_RetArbiId = THRE_ArbiID_Fax2;
						break;
					default:
						THRL_ThAssert( False, "getArbiId FaxId error Id=%d", rs_ThreadComPara.e_FaxLineID , 0, 0, 0, CFA14_DetailCode0x0817 );
						break;
				}
				break;
			default:
				e_RetArbiId = THRE_ArbiID_None;
				break;
		}
		// 例外的に、画像変換又は圧縮はArbiIDを再設定.
		// 07/01/15 拡大ローテーションの場合は対象外とする(73700) 河村.
		if( ((pcc_OneImgTransInfo->en_ThreadImgProcMode == THRE_ImgProcMode_PreConvert)
			|| (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_BufToFile))
			&& chkForRotAndMagnifyMode( rs_ThreadComPara ) == False ){
			e_RetArbiId = THRE_ArbiID_Conv;
		}

	}
	
	return (e_RetArbiId);
}


// ================================================================================================.
//! <!--機能--> 画像制御部(高速タスク)ID設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param short ss_Num .......................... 画像転送管理情報のインデックス番号.
//! \param ST_ThreadComPara& rs_ThreadComPara ... スレッドパラメータ.
//! <!--戻値-->.
//! \return.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野		Donau環境から分離して作成.
//  08/08/12 R.Suzuki	CQ.309145 1Pass対応 Asic200 3枚目用のDMAを追加.
//  08/09/17 S.Ohba		CQ.309145 UTでの不具合対応.
//  2010/12/13 tadamasa	 Fiery1200dpi対応.
//  2012/09/03 koshimo	 UV-00877 Fax3or4回線対応.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
//  13/03/13 Sky ZeusS対応 getCtrIdとgetArbiIdに分けて関数化(マルチスレッド以外からも呼べるように対応した).
// ================================================================================================.
Bool CC_MultiThreadProfile::selCtrArbiId( short ss_Num, const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool b_Ans = True;

	// 入出力決定.
	uchar uc_InOutThread = 0;
	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ) {
			uc_InOutThread = DEF_InputThread;
	} else {
			uc_InOutThread = DEF_OutputThread;
	}

	for( uchar k = 0; k < THRD_MaxThreadBusy; k++ ){
		CC_OneImgTransInfo* pc_ChkTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k];
		if( pc_ChkTransInfo->en_ThreadID != THRE_ThrID_None ){
			// 高速タスクIDを取得.
			pc_ChkTransInfo->e_CtrID = getCtrId( pc_ChkTransInfo->e_usedDma[0] );
			// アービタIDを取得.
			pc_ChkTransInfo->e_ArbiID = getArbiId( pc_ChkTransInfo->e_usedDma[0], pc_ChkTransInfo, rs_ThreadComPara );
		}
	}
	return ( b_Ans );
}

