// ================================================================================================.
//! <!--機能--> 実行開始確認のステート処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... マルチスレッドプロファイル共通パラメータ.
//! \param short& state .............................. 処理ステート.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... 画像転送管理情報へのポインタ.
//! \param Bool& bl_ReqAllocBuf ...................... バッファメモリ確保要否 True：確保必要、False：不要.
//! \param Bool& b_isAlloc ........................... リソース確認内容 True：確保処理、False：予約処理.
//! <!--戻値-->.
//! \return  True：正常終了　False：異常終了.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
//  13/06/26 岡部朋(日立JTE) 次世代アーキテクト スワップ分割転送対応.
//  13/08/13 ADS小林 CQ.382557(Act_67271) EDH不停止問題の対応.
//  13/12/10 岡部朋(日立JTE) CQ.383950 分割保存時、蓄積枚数が190枚になる問題対応.
//  14/04/10 ADS滕 CQ.384987(Act_72902) ソリューションモデル切替対応.
//  14/04/25 ADS竹内 CQ.389967(Act_73361) モデル切替の判定条件を変更.
//  14/05/09 国吉(日立JTE) 次世代アーキ スワップ分割読出対応.
//  14/06/26 伊藤史. CQ500312 分割保存＋ADFカバーオープンキャンセル問題対策.
// ================================================================================================.
Bool CC_MultiThreadProfile::stateProcChkTransExec( ST_ThreadComPara& rs_ThreadComPara, short& state, CC_OneImgTransInfo* pcc_OneImgTransInfo, Bool& bl_ReqAllocBuf, Bool& b_Alloc )
{
	Bool b_Ans = False;	// 戻り値初期化.
	short ss_BandID = rs_ThreadComPara.ss_BandID;

	switch( state ) {
		case THRE_CT_PS_ChkParam:			// パラメータチェック.
			b_Ans = chkParam( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_ChkFCOTNG;	
			break;
		case THRE_CT_PS_ChkFCOTNG:			// FCOT実行確認.
			b_Ans = chkFcotProc( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_SetCmpExp;	
			break;
		case THRE_CT_PS_SetCmpExp:			// 圧縮伸張器の割り振り.
			b_Ans = setCmpExp( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_ChkResource;	
			break;
		case THRE_CT_PS_ChkResource:		// リソースチェック.
			b_Ans = chkResource( pcc_OneImgTransInfo, rs_ThreadComPara, b_Alloc );
			state = THRE_CT_PS_ChkStartOutput;	
			break;
		case THRE_CT_PS_ChkStartOutput:		// 出力開始可否決定.
			b_Ans = chkStartOutput( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_ChkCombination;	
			break;
		case THRE_CT_PS_ChkCombination:		// 禁止組み合わせチェック処理.
			b_Ans = chkCombinationDMA( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_SelMemClrMode;
			break;
		case THRE_CT_PS_SelMemClrMode:		// メモリクリヤ有無モード、伸張速度選択処理.
		 	b_Ans = True;					// ファイル→バッファ、ファイル→アプリ時のみ検索しそれ以外はTrueとする.
			state = THRE_CT_PS_CalBufPlaneNum;	
			break;
		case THRE_CT_PS_CalBufPlaneNum:
			b_Ans = chkCalBufPlaneNum( pcc_OneImgTransInfo, rs_ThreadComPara );
			state = THRE_CT_PS_AllocFile;
			break;
		case THRE_CT_PS_AllocFile: // ファイルメモリ確保チェック.
			b_Ans = chkEnableFileAllocExec( pcc_OneImgTransInfo, rs_ThreadComPara );
			if( b_Alloc == True ){
				state = THRE_CT_PS_AllocBuf;
			} else {
				//  13/08/13 ADS小林 CQ.382557(Act_67271) EDH不停止問題の対応.
				if((b_Ans == True)
					&&(True == SYSF_getAppOptionStatus(TYPE_AppOptionSubMemSplitSave)) // 機能判定.
					&&(pcc_OneImgTransInfo->en_TaskID==THRE_TaskID_InputIR)
					&&(pcc_OneImgTransInfo->en_ThreadID==THRE_ThrID_ExtToBuf)){
						b_Ans = chkExtInBufSize( pcc_OneImgTransInfo, ss_BandID, rs_ThreadComPara );
				}
				// リソース予約時には、バッファ計算は行わない.
				state = THRE_CT_PS_ReserveResource;
			}
			break;
		case THRE_CT_PS_AllocBuf:					// バッファメモリ確保チェック.
			b_Ans = chkEnableAllocExec( pcc_OneImgTransInfo, ss_BandID, rs_ThreadComPara );
			state = THRE_CT_PS_AllocResource;
			break;
		case THRE_CT_PS_AllocResource:		// リソースの確保.
			b_Ans = AllocResource( rs_ThreadComPara, pcc_OneImgTransInfo );
			state = THRE_CT_PS_ChkFreeWorkingArray;	
			break;
		case THRE_CT_PS_ReserveResource:	// リソースの予約.
			b_Ans = ReserveResource( rs_ThreadComPara, pcc_OneImgTransInfo );
			state = THRE_CT_PS_END;	
			break;
		// スワップ分割転送対応.
		case THRE_CT_PS_ChkFreeWorkingArray:   // 空き作業用アレイが使用可能かチェック.
			// 2014/06/26 伊藤史. CQ500312 分割保存＋ADFカバーオープンキャンセル問題対策. 予約時は実行しない.
			if( (True == isSplitBufToFile( rs_ThreadComPara, pcc_OneImgTransInfo )) &&
				(True == b_Alloc) ){
				uint32_t chkSize = 0L;
				b_Ans = chkFreeWorkingArray( rs_ThreadComPara, chkSize );
			} else {
				b_Ans = True;
			}
			state = THRE_CT_PS_IsExistWorkingArray;
			break;
		case THRE_CT_PS_IsExistWorkingArray:		   // 伸長前保持アレイに伸長する圧縮済み画像データが2バンド以上存在するかチェック.
			if( True == pcc_OneImgTransInfo->b_SplitTrans && THRE_ThrID_FileToBuf == pcc_OneImgTransInfo->en_ThreadID
				&& THRE_ImgProcMode_PreConvert == pcc_OneImgTransInfo->en_ThreadImgProcMode ){
				//分割転送かつFileToBufかつ画像変換前の場合.
				if( 1 < rs_ThreadComPara.ss_BandID ){
					// 初回のバンド転送では無い場合.
					b_Ans = chkWorkingArray( rs_ThreadComPara, pcc_OneImgTransInfo );
				} else {
					b_Ans = True;
				}
			} else {
				b_Ans = True;
			}
			state = THRE_CT_PS_END;	
			break;
		default:							// エラー.
			THRL_ThAssert( False, "chkTrans PS error" , 0, 0, 0, 0, CFA14_DetailCode0x082A );
			break;
	}

	return( b_Ans );
}			

// ================================================================================================.
//! <!--機能--> 【内部関数】FCOT実行確認処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... チェックする画像転送管理情報.
//! \param ST_ThreadComPara& rs_ThreadComPara ....... スレッドパラメータ.
//! <!--戻値-->.
//! \return True:動作可能、False：動作禁止.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkFcotProc( const CC_OneImgTransInfo* pcc_OneImgTransInfo, const ST_ThreadComPara& rs_ThreadComPara )
{

	Bool b_Ans = True;		// 戻り値初期化.

	if( (rs_ThreadComPara.pcc_OneImageOutputMode != NULL)											// 出力.
	  && (rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->bl_ExpandInComp == True)		// 圧縮伸張同期モード.
	  && (pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_FileToBuf)									// 伸張処理.
	  && (st_ExpInCmpModeInfo.ul_ExecProcessID == rs_ThreadComPara.c_ThreadIF.ul_ProcessID)			// 同一プロセスID.
	){	
		THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() != NULL ), "CC_MultiThreadProfile::chkFcotProc(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x082B );
        if( (rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->m_IMGC_ImageImp->ss_PageNo > 1)       // JOBの先頭ページ以外.
         && (st_ExpInCmpModeInfo.bl_ExpExecNow == False)                                            // 圧縮伸張同期設定なし.
        ){	
    		// 圧縮伸張同期処理で同期がとれなくなったので同ページの圧縮完了を待つ必要がある.
    		if( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.e_CompressEndMode != IMGE_CompressAllEnd ){
    			// 圧縮未完了の場合.
    			b_Ans = False;							// 同期モードになっているので禁止.
    			_dbg_setChkTransExecNGPoint( 121 );		// 初期化されたパラメータ.
    		}
        }else if(rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->m_IMGC_ImageImp->ss_IJCBandDivLineBasic <= 0){
                //入力情報が未設定.
    			b_Ans = False;							
    			_dbg_setChkTransExecNGPoint( 124 );		// 圧縮伸張同期モードにて出力が先に動作している。.
        }
	}
	return( b_Ans );
}

