// ================================================================================================.
//! <!--機能--> 縮小FCOT 伸張開始の遅延バンド数算出処理.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_selUnitNTPara* pst_selUnitNTPara     転送単位と次画像転送可能タイミング計算共通パラメータ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! 縮小FCOTで必要な伸張開始の遅延バンド数を算出する.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  2009/09/03  sky_yashiro CT1対応 - Gaia問題点リストのNo.81.
//  2009/09/09  yashiro CT1対応 - Gaia問題点リストのNo.97.
//  2009/10/14  takamoto CT2対応 - 小冊子(III[0].pOIPがNull)時に副走査倍率を参照している為、.
//                                 FCOTチェックを先に行うよう修正.
//	2009/12/15	太田(慎) CT2対応 - CQ323196.
//								   テ－ブルデ－タから算出した遅延バンド数がイメ－ジサイズの.
//								   副走査長のバンド数を超えた場合、イメ－ジサイズの副走査長のバンド数を遅延バンド数とするよう修正.
//	2010/02/09	太田(慎) CQ323783  CQ323196で対応した丸め込み処理について、仕様より1バンド早く開始していた不具合の対応.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
//  12017/11/2 Sky西村 AR1032871 bizhub Pro 958で特定の手順(設定)でコピーを行うと、トラブルC-FA17発生.
//  19/03/29 Sky FCOT圧縮完了バンド数取得方法変更.
//  21/07/01 Sky	A800レス 線速対応.
//  22/01/07 日立	OP_BTS-37086 MinervaSSBK/IT6_2.2MR1 TAS000000008847問題水平展開対応.
// ================================================================================================.
void CC_MultiThreadProfile::selectDelayBandNum_ReducedFCOT( ST_selUnitNTPara* pst_selUnitNTPara )
{
	ushort us_SubLine = 0;			// 出力用紙の副走査ライン長.
	uchar uc_SubBand = 0;			// 出力用紙の副走査バンド長.
	ushort us_TablePosSubLine = 0;	// 用紙の副走査長のテーブル位置.
	ushort us_TablePosMag = 0;		// 倍率のテーブル位置.
	float f_SubMag = 0;				// 倍率の一時変数.
	ushort us_SearchTable = 0;		// テーブル検索用.

	// 白紙であれば遅延なし(遅延バンド数を0とする).
	if( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->isNonPrint() == True ) {
		pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = 0;
		return;
	}

	// FCOTでなければ遅延なし(遅延バンド数を0とする).
	//100209 soota CQ323783.
	if( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->bl_ExpandInComp == False
	 || st_ExpInCmpModeInfo.bl_ExpExecNow == False ) {	
		pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = 0;
		return;
	}

	// スレッド共通パラメータから、用紙の副走査長と読み込み倍率を取得.
	// なお、倍率は、副走査方向のみを考慮する（主走査方向の倍率は読み込み速度に影響しない）.
	us_SubLine = MMtoDOT( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize.y,
								theModeInfoLib.ReCalcResolution_DPI( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution.getDpi().y ) );
	THRL_ThAssert( ( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].pOIP->getImage() != NULL ), 
		"CC_MultiThreadProfile::selectDelayBandNum_ReducedFCOT(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x085B );
	f_SubMag =  pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].pOIP->getImage()->c_ImageInfo.ct_ReadMag.y;			

	// 縮小でなければ遅延なし(遅延バンド数を0とする).
	if( f_SubMag>= 1.0f ) {	
		pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = 0;
		return;
	}	
	
	// 有り得ないパターン(副走査長が10800Lineを上回る or 副走査長が3300Lineを下回る or 倍率が25%を下回る)を検出.
	// これらの値に該当しなければ、遅延テーブル内のデータに必ず一致する.
	if( us_SubLine > 10800 || us_SubLine < 3300  || f_SubMag < 0.25f ){	
		THRL_ThAssert( False, "selectDelayBandNum_ReducedFCOT(): SubLine=%d SubMag=%f ", us_SubLine, (uintptr_t)f_SubMag , 0, 0, CFA14_DetailCode0x085C );
	}	
	
	// 用紙の副走査長のテーブル位置を特定.
	for( us_SearchTable = 0; us_SearchTable < THRD_NUM_SLB; us_SearchTable++ ) {
       if( us_SubLine >= us_SubLineBorder[us_SearchTable] ) {
			us_TablePosSubLine = us_SearchTable;
			break;
		}
	}
	
	// 倍率のテーブル位置を特定.
	for( us_SearchTable = 0; us_SearchTable < THRD_NUM_MB; us_SearchTable++ ) {
		if( f_SubMag >= f_MagBorder[us_SearchTable] ) {
			us_TablePosMag = us_SearchTable;
			break;
		}
	}

	// 副走査長のバンド数を超えるようなら、遅延バンド数を丸める.
	uc_SubBand = (uchar)_roundup( (uint32_t)us_SubLine, DEF_BasicCompExpLine );
//091215 soota CQ323196 (S).
	uint32_t ul_SubImageLine = MMtoDOT( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->III[0].pOIP->getImage()->c_ImageInfo.ct_ImageSize.c_SizeMM.y,
								theModeInfoLib.ReCalcResolution_DPI( pst_selUnitNTPara->st_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->c_Resolution.getDpi().y ) );
	uchar uc_SubImageBand = (uchar)_roundup( ul_SubImageLine, DEF_BasicCompExpLine );

//2017/11/2 Sky西村 AR1032871 bizhub Pro 958で特定の手順(設定)でコピーを行うと、トラブルC-FA17発生.
	// MinervaSBK Xの縮小FCOTは高速機用のテーブルを使用.
	TYPE_MachineType e_MachineType = THRF_GetOriginalMachineTypeInfo();
	if( TYPE_MachineTypeMinervaSBKX == e_MachineType ) {
		if( uc_DelayBandNumTableHigh[us_TablePosMag][us_TablePosSubLine] >= uc_SubImageBand ){
			// テ－ブルデ－タから算出した遅延バンド数がイメ－ジサイズの副走査長のバンド数を超えた場合.
			// ⇒イメ－ジサイズの副走査長のバンド数を遅延バンド数として決定する.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_SubImageBand;
		}else if( uc_DelayBandNumTableHigh[us_TablePosMag][us_TablePosSubLine] >= uc_SubBand ){
			// テーブルデータから算出した遅延バンド数が出力用紙サイズの副走査長のバンド数を超えた場合.
			// ⇒出力用紙サイズの副走査長のバンド数を遅延バンド数として決定する.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_SubBand;
		}else{
			// テーブル位置から、遅延バンド数を決定する.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_DelayBandNumTableHigh[us_TablePosMag][us_TablePosSubLine];	
		}
	}
	else {
#ifndef DEF_A800
		// A800レスのEagleBKZのみテーブル変更.
		if( True == THRF_IsA800LessModel() && TYPE_MachineTypeEagleBKZ == e_MachineType )
		{
			memcpy( uc_DelayBandNumTable, uc_DelayBandNumTableLessZ, sizeof(uc_DelayBandNumTable));
		}
#endif // DEF_A800.

		if( uc_DelayBandNumTable[us_TablePosMag][us_TablePosSubLine] >= uc_SubImageBand ){
			// テ－ブルデ－タから算出した遅延バンド数がイメ－ジサイズの副走査長のバンド数を超えた場合.
			// ⇒イメ－ジサイズの副走査長のバンド数を遅延バンド数として決定する.
			//100209 soota CQ323783.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_SubImageBand;
		}else if( uc_DelayBandNumTable[us_TablePosMag][us_TablePosSubLine] >= uc_SubBand ){
			// テーブルデータから算出した遅延バンド数が出力用紙サイズの副走査長のバンド数を超えた場合.
			// ⇒出力用紙サイズの副走査長のバンド数を遅延バンド数として決定する.
			//100209 soota CQ323783.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_SubBand;
		}else{
			// テーブル位置から、遅延バンド数を決定する.
			pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = uc_DelayBandNumTable[us_TablePosMag][us_TablePosSubLine];	
		}
	}
//091215 soota CQ323196 (E).
//Str【OP_BTS-37086 MinervaSSBK/IT6_2.2MR1 TAS000000008847問題水平展開対応 : 2022.01.07】.
	// HeliosMLK機種限定にて遅延バンド数を＋１する.
	switch( e_MachineType ) {
		case TYPE_MachineTypeHeliosMLK2			:	// HeliosMLK 2.
		case TYPE_MachineTypeHeliosMLK2_5		:	// HeliosMLK 2.5.
		case TYPE_MachineTypeHeliosMLK3			:	// HeliosMLK 3.
		case TYPE_MachineTypeHeliosMLK2_5_CN	:	// HeliosMLK 2.5　[中国向け].
		case TYPE_MachineTypeHeliosMLK2_5_CNDF	:	// HeliosMLK 2.5　[その他向け].
		case TYPE_MachineTypeHeliosMLK3_CN		:	// HeliosMLK 3　[中国向け].
		case TYPE_MachineTypeHeliosMLK2_CNDF	:	// HeliosMLK 2　[中国向け]　DF標準.
			if( ss_ReducedFCOTSelect <= 1 ) {
				pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT = pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT + 1;
				if( ss_ReducedFCOTSelect == 1 ) {
					printf(">>>selectDelayBandNum_ReducedFCOT():e_MachineType=%d\n", e_MachineType);
					printf(">>>selectDelayBandNum_ReducedFCOT():uc_DelayBandNum_ReducedFCOT=%d\n", pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT);
				}
			} else {
				printf(">>>selectDelayBandNum_ReducedFCOT():uc_DelayBandNum_ReducedFCOT=%d\n", pst_selUnitNTPara->pcc_OneImgTransInfo->uc_DelayBandNum_ReducedFCOT);
			}
			break;
		default:
			break;
	}
//End【OP_BTS-37086 MinervaSSBK/IT6_2.2MR1 TAS000000008847問題水平展開対応 : 2022.01.07】.
}

// ================================================================================================.
//! <!--機能--> 先行変倍後圧縮ファイルメモリ確保(オーバーレイ原稿画像用).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return True 確保できた, False 確保できなかった.
//! <!--詳細-->.
//! 原稿先行変倍用のファイルメモリを確保する.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
//	14/08/25 fukuhara CQ.500317:5thマージ (CQ.390862 セマフォログ追加).
// ================================================================================================.
Bool CC_MultiThreadProfile::getPreCnvFileMemory_OverlayOriginal()
{
	Bool b_Ans = True;

	// 原稿先行変倍待ちのスレッド共通パラメータ退避用変数がNULLのときは.
	// 先行変倍待ちではないのでこの関数を抜ける.
	if( pst_PreCnvWaitThreadComPara == NULL ){
		return False;
	}

	// 原稿先行変倍ありのとき.
	if( chkPreCnvMode_OverlayOriginal( *pst_PreCnvWaitThreadComPara ) != THRE_OLPreCnvMode_None ){
		IMGC_ImageMemoryPoolImpColorFileMemoryInstance& comMemoryManager = IMGC_ImageMemoryPoolImpColorFileMemorySingletonIf::newInstance();
		// FileMemoryの操作を行うので、セマフォロック.
		comMemoryManager.semTake_FileMemAlloc( WAIT_FOREVER, THRD_SemLog_MultiThread_getPreCnvFileMemory_OverlayOriginal );
		// ファイルメモリが確保可能かどうか判断.
		DOCC_Leaf* pc_PreCnvLeaf = getPreCnvLocalLeaf();
		CC_OneImgTransInfo* pcc_OneImgTransInfo = &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[pst_PreCnvWaitThreadComPara->ss_TransIndexNum][1][0];
		if( pc_PreCnvLeaf != NULL ){
			IMGC_Image* pc_PreCnvImage = pc_PreCnvLeaf->getImage();
			THRL_ThAssert( ( pc_PreCnvImage != NULL ), "CC_MultiThreadProfile::getPreCnvFileMemory_OverlayOriginal(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x085D );
			if( comMemoryManager.AllocPageWithWait( pc_PreCnvImage->c_ImageInfo.ul_ImageProcessID, pc_PreCnvImage->c_ImageInfo.e_ImageType, pc_PreCnvImage, pc_PreCnvImage->m_IMGC_ImageImp->ul_CompressSize, True ) != IMGD_ImgOk ){
				if( comMemoryManager.isHDDReady() == True ){
					// Swap領域不足なので待つ.
				} else {
					// メモリ不足.
					THRL_ThAssert( False, "chkEnableFileAllocExec PreCnv alloc error!" , 0, 0, 0, 0, CFA14_DetailCode0x085E );
				}
				b_Ans = False;
			}		
			if( b_Ans == True ){
				// 変倍後の圧縮用ファイルメモリ確保チェック.
				b_Ans = chkEnableCompress( pcc_OneImgTransInfo, pc_PreCnvLeaf, False );
				if( (b_Ans == True) && (pcc_OneImgTransInfo->ul_usedFileMem > 0) ){
					uint32_t ul_usedFileMem = 0;							// 先行変倍用の使用ファイルメモリサイズ.
					ul_usedFileMem = pcc_OneImgTransInfo->ul_usedFileMem;
					s_WaitResState.ul_File[ pcc_OneImgTransInfo->e_MPID ] += ul_usedFileMem;
				}
			}
		}else{
			// 先行変倍時に先行変倍用のローカルLeafがなければAssert.
			THRL_ThAssert( False, "chkEnableFileAllocExec pc_PreCnvLeaf Null error!" , 0, 0, 0, 0, CFA14_DetailCode0x085F );
		}
		if( b_Ans == True ){
			//変倍後のイメージ情報を取得する.
			IMGC_Image* pc_PreCnvImage = pc_PreCnvLeaf->getImage();
			THRL_ThAssert( pc_PreCnvImage != NULL, "chkPreCnvMode_Original() pc_PreCnvImage error", 0, 0, 0, 0, CFA14_DetailCode0x0860 );
			// メモリ上に無い、かつ、確保済みでないイメージのみチェックする.
			if( (pc_PreCnvImage->m_IMGC_ImageImp->c_ArrayGetMemory == (uintptr_t)NULL) 
				&& ( (pcc_OneImgTransInfo->us_StartTransNum == 0) || (pcc_OneImgTransInfo->bl_PageTrans == True) ) ){
				// 圧縮するアレイ分のメモリを確保.
				comMemoryManager.AllocCompressImage( pc_PreCnvImage );
			}
			// 原稿先行変倍待ちのスレッド共通パラメータ退避用変数をNULLにする.
			pst_PreCnvWaitThreadComPara = NULL;
		}
		comMemoryManager.semGive_FileMemAlloc( THRD_SemLog_MultiThread_getPreCnvFileMemory_OverlayOriginal );
	}

	return b_Ans;
}

// ================================================================================================.
//! <!--機能--> 多値合成DMA04の転送元(原稿）バッファについてSDRAMかどうか判定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ST_ThreadComPara& rs_ThreadComPara     スレッド共通パラメータ.
//! <!--戻値-->.
//! \return True 転送元がSDRAMである, False 転送元がSDRAM以外である.
//! <!--詳細-->.
//! 多値合成DMA04の転送元(原稿）バッファについてSDRAMかどうかの判定結果を返す.
//! <!--履歴-->.
//  2010/04/05 太田	 新規作成(SoC1200 多値合成・強制付加印字対応).
//	2011/02/21 佐々木	  CQ:342529 オーバーレイ強制付加プリントでFA14発生対応.
//  13/02/28 Sky 機種共通化対応 THRC_MultithreadSoC.cppから移植.
// ================================================================================================.
Bool CC_MultiThreadProfile::isUseBufSDRAMForOverlayOriginal( const ST_ThreadComPara& rs_ThreadComPara )
{
	Bool b_Ans = False;

	b_Ans = theModeInfoLib.isOutColorYMCK( rs_ThreadComPara );							//出力色の判定を行う.

	return ( b_Ans );
}

