// ================================================================================================.
void CC_MultiThreadProfile::incScanImpInstanceListNum()
{
	semTake_Multithread( THRD_SemLog_MultiThread_incScanImpInstanceListNum );
	if( us_ScanImpInsListNum < us_ScanImpInstanceListNum ){
		us_ScanImpInsListNum++;
	}
	if( 0 < uc_DbgFlag_ScanImpInst ){
		THRL_SetThLog( 543, THRE_DebugLogType_MTCtrLog, 0, True, us_ScanImpInsListNum );
	}
	semGive_Multithread( THRD_SemLog_MultiThread_incScanImpInstanceListNum );
}
