//	14/08/22 fukuhara CQ.500317:5thマージ (CQ.390862 セマフォログ追加).
// ================================================================================================.
void CC_MultiThreadProfile::decScanImpInstanceListNum()
{
	semTake_Multithread( THRD_SemLog_MultiThread_decScanImpInstanceListNum );
	if( 0 < uc_DbgFlag_ScanImpInst ){
		THRL_SetThLog( 544, THRE_DebugLogType_MTCtrLog, 0, True, us_ScanImpInsListNum );
	}
	if( 0 < us_ScanImpInsListNum ){
		us_ScanImpInsListNum--;
	}
	semGive_Multithread( THRD_SemLog_MultiThread_decScanImpInstanceListNum );
}
