// ================================================================================================.
//! <!--機能--> 【内部関数】ファイルメモリ確保タイミング変更確認.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return True:タイミング変更有効、False：タイミング変更無効.
//! <!--詳細-->.
//! ファイルメモリ確保タイミング変更有効/無効を判定する\n.
//! <!--履歴-->.
//  15/10/26 Sky システム統合SoC(S800)対応.
// ================================================================================================.
#define FILEMEMORYSIZE_A3_4PAGE	0 // 516947968	/* A3(600dpi)両面同時読込 RGB_Att4 多値 4Page分＋FAX分のファイルメモリサイズ 493MB */
Bool CC_MultiThreadProfile::isAllocFileMemoryTimingChange( void )
{
	uint32_t ul_FileMemSize = 0;
	static Bool b_GetisAllocFileMemoryTimingChange = False;	//取得処理実行判定フラグ.
	static Bool b_ret = True;

	if( b_GetisAllocFileMemoryTimingChange == False ){
		if (APIC_Enabler::newInstance()->isExtendedMemory() == False) {
			// 拡張メモリ非装着の場合は、タイミング変更無効.
			b_ret= False;
		}else{
			// ファイルメモリサイズ取得.
			ul_FileMemSize = THRL_GetFileMemoryPool();

			// S800で両面パフォーマンスに影響をださないよう.
			// ファイルメモリの確保タイミング変更は無効にする.
			// ファイルメモリサイズを変更した場合を考慮して定義値を0にしておく.
			if( ul_FileMemSize >= FILEMEMORYSIZE_A3_4PAGE ){
				// ファイルメモリがA3 4ページ分以上ある場合はタイミング変更無効.
				b_ret= False;
			}
		}
		b_GetisAllocFileMemoryTimingChange = True;
	}
	
	return b_ret;
}

// ================================================================================================.
//! <!--機能--> 未実行BufToFile削除.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! IR入力のキャンセル完了時に未実行のBufToFileを検索して削除する\n.
//! <!--履歴-->.
//  2018/05/15 Sky AR1041579対応.
// ================================================================================================.
void CC_MultiThreadProfile::cancelUnexecutedBufToFile()
{
	THRC_TransExecCtrlQueue c_getQueue;

	// BufToFile検索.
	for( ushort us_index = 0; us_index < pc_TransCtrl->isNum(); us_index ++ ) {
		if( pc_TransCtrl->peekQueue( us_index, &c_getQueue ) != False ) {
			// IR用のBufToFileがあれば削除.
			if( (THRE_ThrID_BufToFile == c_getQueue.pcc_OneImgTransInfo->en_ThreadID) &&
				(THRE_TaskID_InputIR == c_getQueue.pcc_OneImgTransInfo->en_TaskID ||
				 THRE_TaskID_InputIRDup == c_getQueue.pcc_OneImgTransInfo->en_TaskID) )
			{
				pc_TransCtrl->deleteQueue(c_getQueue.pcc_OneImgTransInfo);
				THRL_SetThLog( 675, THRE_DebugLogType_CTLog, 0, True, 0);
			}
		}
	}
}

// ================================================================================================.
//! <!--機能--> 工程スキャン用バッファのクリア.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param b_DuplexScan  True：両面スキャン / False：片面スキャン.
//! <!--戻値-->.
//! \return True:クリア要求成功、False：クリア要求失敗.
//! <!--詳細-->.
//! 工程スキャン用バッファのクリアを行う.
//! <!--履歴-->.
//  17/4/27 日立 OP/PP共通化 工程スキャン対応による新規追加.
// ================================================================================================.
Bool CC_MultiThreadProfile::rawImageBufClrReq( Bool  b_DuplexScan)
{
	
	THRS_MsgMemoryClearInfo* ps_MsgMemClrInfo = NULL;
	
	// 両面、片面のどちらの指定の場合もまず、表面バッファをクリアする.
	ps_MsgMemClrInfo = pc_BufResMan[THRE_BufId_RawImageScan]->getMemoryClearMsg( THRE_BufId_RawImageScan );
		
	if( NULL == ps_MsgMemClrInfo ){
		return False;
	}
	
	MemClrReq(ps_MsgMemClrInfo );
	
	ps_MsgMemClrInfo = NULL;
		
	if( True == b_DuplexScan ){
		// 両面スキャン時、裏面バッファをクリア.
		ps_MsgMemClrInfo = pc_BufResMan[THRE_BufId_RawImageScan_Dup]->getMemoryClearMsg( THRE_BufId_RawImageScan_Dup );
		
		if( NULL == ps_MsgMemClrInfo ){
			return False;
		}
		MemClrReq(ps_MsgMemClrInfo );
	}
	
	return 	True;
}

// ================================================================================================.
//! <!--機能--> Raw画像バッファの先頭アドレスとバッファサイズを返す.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param pc_RawImageBufInfo  工程スキャンバッファ情報.
//! <!--戻値-->.
//! \return True:アドレス、サイズ取得成功、False：アドレス、サイズ取得失敗.
//! <!--詳細-->.
//! Raw画像バッファの先頭アドレスとバッファサイズを返す.
//! <!--履歴-->.
//  17/4/27 日立 OP/PP共通化 工程スキャン対応による新規追加.
// ================================================================================================.
Bool CC_MultiThreadProfile::getRawImageBufferInfo( THRS_RawImageBufInfo* pc_RawImageBufInfo )
{
	
	if( NULL == pc_RawImageBufInfo ){
	//	THRL_SetThLog( 216, THRE_DebugLogType_ThCtrLog, 3, True, pc_RawImageBufInfo );
		return False;
	}
	
	THRC_BufferResource* pst_BufResource = NULL;
	
	
	// 表面工程スキャンバッファ情報取得処理.
	pst_BufResource = THRC_BufMemorySingletonIf::newInstance( ).getBufferResourceInstance( THRE_BufId_RawImageScan );
	
	// 表面工程スキャンバッファの先頭アドレス取得.
	pc_RawImageBufInfo->ul_MemoryAddr = pst_BufResource->getAddr( );

	// 表面工程スキャンバッファサイズ取得.
	pc_RawImageBufInfo->ul_MemorySize = pst_BufResource->getSizeOfMemory( );


	// 裏面工程スキャンバッファ情報取得処理.
	pst_BufResource = THRC_BufMemorySingletonIf::newInstance( ).getBufferResourceInstance( THRE_BufId_RawImageScan_Dup );
	
	// 裏面工程スキャンバッファの先頭アドレス取得.
	pc_RawImageBufInfo->ul_MemoryAddr_Dup = pst_BufResource->getAddr( );

	// 裏面工程スキャンバッファサイズ取得.
	pc_RawImageBufInfo->ul_MemorySize_Dup = pst_BufResource->getSizeOfMemory( );

	return True;
}

