// ================================================================================================.
//! <!--機能--> 【内部関数】【Rembrandt/PP機用】メモリ確保可能かどうか判断.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param CC_OneImgTransInfo* pcc_OneImgTransInfo ... 画像転送管理情報へのポインタ.
//! \param short ss_BandID.
//! \param ST_ThreadComPara& rs_ThreadComPara.
//! <!--戻値-->.
//! \return True:確保可能、False：不可能.
//! <!--詳細-->.
//! エンジン出力用バッファを使用するスレッド転送の時には、1ページ分のバッファサイズの空きが必要となる.
//! その為、Rembrandt/PP機用に
//! \n.
//! <!--履歴-->.
//  17/05/18 Sky	 新規作成 OP/PP共通化.バッファの空きチェックを1ページ分で行う.
// ================================================================================================.
Bool CC_MultiThreadProfile::chkEnableAllocExecForPP( CC_OneImgTransInfo* pcc_OneImgTransInfo, short ss_BandID, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRL_ThAssert( (pcc_OneImgTransInfo != NULL), "chkEnableAllocExecForPP OITI error" , 0, 0, 0, 0, CFA14_DetailCode0x042B );

	Bool b_Ans = True;
	Bool b_chk = True;

	// 転送バンド数計算.
	uchar uc_UnitBandTrans = pcc_OneImgTransInfo->uc_UnitBandTrans;

	//  13/06/25 ADS小林  CQ.381621(Act_66306) SP-SAP-19	サブメモリ可変化 ExtToBuf 読み込み開始前制御の変更(No.2)対応.
	if((True == SYSF_getAppOptionStatus(TYPE_AppOptionSubMemSplitSave)) // 機能判定.
		&& (pcc_OneImgTransInfo->en_TaskID==THRE_TaskID_InputIR)
		&&(pcc_OneImgTransInfo->en_ThreadID==THRE_ThrID_ExtToBuf)){
		// 最小構成 かつ IR入力 かつ ExtToBuf.
		for( uchar uc_Idx2 = 0; uc_Idx2 < THRD_MAX_BUF_USE; uc_Idx2++ ){
			if(pcc_OneImgTransInfo->s_usedBuf[uc_Idx2].e_usedBuf == THRE_BufId_ScnInRaw){
				// IRバッファを使用する.
				//IR入力でpc_Leafが空ではいけないので、アサートする.
				THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf != NULL ), "CC_MultiThreadProfile::chkEnableAllocExecForPP(): pc_Leaf NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0B8B);
				THRC_BufferResource* pst_BufResource = THRC_BufMemorySingletonIf::newInstance().getBufferResourceInstance( THRE_BufId_ScnInRaw );
				THRL_ThAssert( pst_BufResource != NULL, "CC_MultiThreadProfile::chkEnableAllocExecForPP() : pst_BufResource NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0FED );
				if(((uint32_t)rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ct_TransSize.x > pst_BufResource->getBufWidth())
					|| ((uint32_t)rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ct_TransSize.x <= (pst_BufResource->getBufWidth()-1024))){
					// 入力ページ幅が変化した.
					// 2014/02/26 ADS小林 CQ.385390(Act_71491) 混載不具合対応.
					if( chkReserveExec( (ST_ThreadComPara&)rs_ThreadComPara, THRE_ThrID_BufToFile ) == False ){
						// IRバッファ使用中のため、一旦待機する.
						_dbg_setChkTransExecNGPoint( 150 );	// 2013/10/03 CQ.383151(Act_68265) ページ幅変更時、入力バッファ使用中.
						return(False);
					}
					// IRバッファ待機状態.
					// IRバッファ幅設定.
					THRS_SubBufParaCom s_param;
					THRC_BufMemorySingletonIf::newInstance().GetBufMemoryInfo( THRE_BufId_ScnInRaw, THRE_BufMode_Normal, s_param);
					short ImageWidth = 0;
					ImageWidth = (short)(_roundup((short)rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ct_TransSize.x, (short)(1024)) * 1024);
					pst_BufResource->setBuffer( THRE_BufMode_Normal, static_cast<uint32_t>(ImageWidth), (s_param.us_BandMax * (short)s_param.ul_BufWidth)/ImageWidth, s_param.us_PlaneMax );
				}
				// 1ページ必要ライン数計算.
				short Imagelines = 0;
				Imagelines = (short)(_roundup((short)rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.ct_TransSize.y, (short)(1024)) * 1024);
				//  13/08/28 ADS小林 CQ.382557(Act_67382) EDH不停止問題の対応.
				ul_ExtToBufTransStartLine = pc_BufResMan[THRE_BufId_ScnInRaw]->getWriteLineNum();
				// IRバッファメモリ空き判定.
				if( pc_BufResMan[THRE_BufId_ScnInRaw]->getFreeLineNum() < (uint32_t)(Imagelines) ){
					// 1ページのライン数分、バッファメモリが空いていない.
					_dbg_setChkTransExecNGPoint( 151 );	// 2013/10/03 CQ.383151(Act_68265) 入力バッファの空き不足.
					return(False);
				}
				else{
					return(True);
				}
			}
		}
	}
	
	// 画像がなければ、転送バンド数の再計算は行わない.
	if ( rs_ThreadComPara.c_ThreadIF.pc_Leaf != NULL ) {
		// CQ 322020対応：uc_UnitBandTransが1200dpi相当の場合は、600dpi相当に変換する.
		THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() != NULL ), "CC_MultiThreadProfile::chkEnableAllocExecForPP(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x042C );
		uc_UnitBandTrans =
			ReCalcUnitBandTrans( pcc_OneImgTransInfo->uc_UnitBandTrans, 
								 pcc_OneImgTransInfo->en_ThreadID,
								 rs_ThreadComPara.c_ThreadIF.pc_Leaf,
								 pcc_OneImgTransInfo->en_ThreadImgProcMode );
	}

	// 2006/02/20 Koshino(Sky) 白紙印字対応.
	if(  ( rs_ThreadComPara.pcc_OneImageOutputMode != NULL )
	  && ( rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->isNonPrint() == True ) ){	// 白紙.
		// 白紙の時はそのままリターンする.
		return( True );
	}

	if( ( pcc_OneImgTransInfo->en_ThreadID == THRE_ThrID_FileToBuf ) 
		&& (THRE_ImgProcMode_PreConvert == pcc_OneImgTransInfo->en_ThreadImgProcMode)
		&& ( pcc_OneImgTransInfo->b_SplitTrans == True )
		&& ( ( ( TYPE_Nin1_1in1 != rs_ThreadComPara.e_Nin1 ) && ( TYPE_PageShotNone !=rs_ThreadComPara.e_PageShot) )
				|| (0 < pcc_OneImgTransInfo->us_StartTransNum) )	// 先頭バンド以外.
		){
		// スワップ分割読出 暫定対策.
		// 分割転送時のページ連射小冊子は後スレッドが先行してしまうためメモリチェックを省く.
		// 2014/07/24 伊藤史. CQ501417,501419,501459 (縮小画像変換＋分割読出)で伸張停止問題対策. NgPoint 18 を迂回する.
	}else {
		
		for( uchar uc_Idx = 0; uc_Idx < THRD_MAX_BUF_USE; uc_Idx++ ){
			THRS_BufResource s_BufRes = pcc_OneImgTransInfo->s_usedBuf[uc_Idx];
			if( s_BufRes.e_usedBuf != THRE_BufId_None ){
				THRL_ThAssert( (s_BufRes.e_usedBuf < THRE_BufId_Num), "chkEnableAllocExecForPP BufId error" , 0, 0, 0, 0, CFA14_DetailCode0x042D );
				if( s_BufRes.b_isWrite == True ){
					// OP/PP共通化.
					//使用するバッファがエンジン出力用バッファだった場合には、1ページ分のバッファの空きをチェックするようにする.
					if( ( THRE_BufId_EngOut <= s_BufRes.e_usedBuf ) && ( s_BufRes.e_usedBuf <= THRE_BufId_EngOut3) ){
						//1ページの画像の高さ.この高さ分バッファの空きが必要となる.
						uint32_t u32_ImageHeight = 0;
						//チェックしているスレッド転送が入力か出力か判断.
						if(  rs_ThreadComPara.pcc_OneImageOutputMode == NULL ){
							//PP Fieryの場合は、出力用パラメータがないので、転送サイズでチェック.
							IMGC_Image* pc_Image = rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage();
							THRL_ThAssert( ( pc_Image != NULL ), "CC_MultiThreadProfile::chkEnableAllocExecForPP(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0xXXXX );
							u32_ImageHeight = (uint32_t) pc_Image->c_ImageInfo.ct_TransSize.y;
						}else{
							//出力サイズでチェックする.
							u32_ImageHeight = (uint32_t)rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode->ct_OutputSize.y;
						}
						// 書き込み側のバッファの空き容量をチェック.
						if( pc_BufResMan[s_BufRes.e_usedBuf]->getFreeLineNum() < u32_ImageHeight ){
							// 最低限必要なライン数分、バッファメモリが空いていない.
							b_Ans = False;
							_dbg_setChkTransExecNGPoint( 18 );
							THRL_SetThLog( 553, THRE_DebugLogType_MTCtrLog, 1, True, s_BufRes.e_usedBuf, pc_BufResMan[s_BufRes.e_usedBuf]->getFreeLineNum() );
							THRL_ThLogMsgDebug("==multi::chkEnableAllocExecForPP== NG. Not enough memory to write. BufId=%d\n", s_BufRes.e_usedBuf );
							break;
						}
					}else{
						// 書き込み側のバッファの空き容量をチェック.
						if( pc_BufResMan[s_BufRes.e_usedBuf]->getFreeLineNum() < (uint32_t)(uc_UnitBandTrans * DEF_BasicTransLine) ){
							// 最低限必要なライン数分、バッファメモリが空いていない.
							b_Ans = False;
							_dbg_setChkTransExecNGPoint( 18 );	// 【修正:橋本昌】2004/05/28 デバッグ用 実行開始確認NG ログ取得.
							THRL_SetThLog( 553, THRE_DebugLogType_MTCtrLog, 1, True, s_BufRes.e_usedBuf, pc_BufResMan[s_BufRes.e_usedBuf]->getFreeLineNum() );
							THRL_ThLogMsgDebug("==multi::chkEnableAllocExecForPP== NG. Not enough memory to write. BufId=%d\n", s_BufRes.e_usedBuf );
							break;
						}
					}
				}
			}
		}
	}

//060522 太田(慎) 読込みバッファチェックはBufToXXXのみ行うよう修正(S).
	switch( pcc_OneImgTransInfo->en_ThreadID){
	case THRE_ThrID_BufToExt:
	case THRE_ThrID_BufToApp:
		// 読み込みバッファチェック.
		if( pcc_OneImgTransInfo->c_TransLineMan.getPreTransLine() <= pcc_OneImgTransInfo->c_TransLineMan.getSrcLine() ){
			b_Ans = False;
			// 前スレッドの転送が終わっていない.
			_dbg_setChkTransExecNGPoint( 113 );
		}
		break;
	case THRE_ThrID_BufToBuf:
		// 2014/06/20 伊藤史.  CQ500469,500471 分割読出マルチ問題対策. NgPoint 113 を対象外にする.
		if( False == CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ rs_ThreadComPara.ss_TransIndexNum ][ DEF_OutputThread ][ 0 ].b_SplitTrans ){
			// 読み込みバッファチェック.
			if( pcc_OneImgTransInfo->c_TransLineMan.getPreTransLine() <= pcc_OneImgTransInfo->c_TransLineMan.getSrcLine() ){
				b_Ans = False;
				// 前スレッドの転送が終わっていない.
				_dbg_setChkTransExecNGPoint( 113 );
			}
		}
		break;
	case THRE_ThrID_BufToFile:
		// 2014/06/20 伊藤史.  CQ500469,500471 分割読出マルチ問題対策. NgPoint 113 を対象外にする.
		if( (NULL != rs_ThreadComPara.pcc_OneImageOutputMode) &&
			(NULL != rs_ThreadComPara.pcc_OneImageOutputMode->pcc_OneExpandMode) &&
			(True == CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ rs_ThreadComPara.ss_TransIndexNum ][ DEF_OutputThread ][ 0 ].b_SplitTrans) ){
			b_chk = False;	// 2014/6/4 伊藤史. 分割読出しを対象外にする.
		}
		if( True == b_chk ){
			//  2013/09/24 伊藤史. CQ383015 分割保存パフォーマンス改善. 非分割転送時にExtInバッファチェックを行う.
			if ( rs_ThreadComPara.c_ThreadIF.pc_Leaf != NULL ) {
				IMGC_Image* pc_Image = rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage();
				THRL_ThAssert( (NULL != pc_Image), "CC_MultiThreadProfile::chkEnableAllocExecForPP pc_Image is NULL." , 0, 0, 0, 0, CFA14_DetailCode0x0C02 );

				//非分割転送時に読み込みバッファチェックを行う.
				if( pc_Image->c_ImageInfo.b_SplitTrans == False ){
					// 読み込みバッファチェック.
					if( pcc_OneImgTransInfo->c_TransLineMan.getPreTransLine() <= pcc_OneImgTransInfo->c_TransLineMan.getSrcLine() ){
						b_Ans = False;
						// 前スレッドの転送が終わっていない.
						_dbg_setChkTransExecNGPoint( 113 );
					}
				}
			}
		}
		break;
	default:
		break;
	}
//060522 太田(慎) 読込みバッファチェックはBufToXXXのみ行うよう修正(E).

	return ( b_Ans );
}

// ================================================================================================.
//! <!--機能--> 【Rembrandt/PP機用】バッファ選択.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param short ss_Num ......................... 画像転送管理情報のインデックス番号.
//! \param ST_ThreadComPara& rs_ThreadComPara ... スレッドパラメータ.
//! <!--戻値-->.
//! \return True:成功、False：選択異常.
//! <!--詳細-->.
//! 最大７つの連続動作の使用バッファ及びバッファで最低限必要なライン数を決定する\n.
//! <!--履歴-->.
//  17/05/18 Sky	新規作成 OP/PP共通化.
//					ページモード判定用フラグとバッファ割り振り番号を追加したテーブルでのバッファ選択.
// ================================================================================================.
Bool CC_MultiThreadProfile::selBufferForPP( short ss_Num, const ST_ThreadComPara& rs_ThreadComPara )
{
	THRS_SelectBufferResource* ps_SelTbl = NULL;		// 2011/10/14 窪川add 選択したテーブルのポインタ.

	// 入出力決定.
	uchar uc_InOutThread = 0;
	if( rs_ThreadComPara.pcc_OneImageOutputMode == NULL ) {
			uc_InOutThread = DEF_InputThread;
	} else {
			uc_InOutThread = DEF_OutputThread;
	}
	// スレッド選択共通設定.
	THRS_SelectBufferResource st_ChkTbl;
	st_ChkTbl.en_taskID = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][0].en_TaskID;
	st_ChkTbl.en_AppIDSelThread = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][0].st_TransModePara.en_AppIDSelThread;
	st_ChkTbl.en_LineID = rs_ThreadComPara.e_FaxLineID;
	st_ChkTbl.b_RotAndMagnify = chkForRotAndMagnifyMode( rs_ThreadComPara );
	st_ChkTbl.e_OverlayType = theModeInfoLib.getOverlayType( rs_ThreadComPara );
	st_ChkTbl.b_isPageMode =  rs_ThreadComPara.b_isPageMode;	// ページモード判定用フラグ.
	st_ChkTbl.i64_selBufNo = rs_ThreadComPara.i64_selBufNo%4;	// バッファ割り振り番号.
	
	setFieryThLog( 458, THRE_DebugLogType_ThCtrLog, 3, True,2
					,st_ChkTbl.en_taskID
					,st_ChkTbl.en_AppIDSelThread
					,st_ChkTbl.en_LineID
					,st_ChkTbl.b_RotAndMagnify
					,st_ChkTbl.e_OverlayType);

	// 1200dpiかどうかを判定 13/03/13 ZeusS対応.
	if( rs_ThreadComPara.c_ThreadIF.pc_Leaf == NULL ){
		st_ChkTbl.b_is1200dpi = False;		// LeafがNULLの場合は1200dpiではない.
	}else{
		THRL_ThAssert( ( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage() != NULL ), "CC_MultiThreadProfile::selBuffer(): getImage NULL error." , 0, 0, 0, 0, CFA14_DetailCode0x0807 );
		st_ChkTbl.b_is1200dpi = theModeInfoLib.chk1200Dpi( rs_ThreadComPara.c_ThreadIF.pc_Leaf->getImage()->c_ImageInfo.c_Resolution );
	}
	// 出力色の判定(YMCK(属性も含め）かどうか) ※入力時はFalseをセット 10/04/05 太田 Add.
	st_ChkTbl.b_isOutColorYMCK = theModeInfoLib.isOutColorYMCK( rs_ThreadComPara );
	
	Bool b_Ans = True;	// 戻り値を正常終了で初期化.
	ushort us_Idx = 0;
	// 複数スレッド設定.
	for( uchar k=0; k<THRD_MaxThreadBusy; ++k ) {
		THRE_ThrID en_ThreadID = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].en_ThreadID;
		st_ChkTbl.en_ThreadImgProcMode = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].en_ThreadImgProcMode;
		if( en_ThreadID == THRE_ThrID_None ) {
			break;	// スレッド未選択の時は終了.
		}
		for( us_Idx = 0; us_Idx < v_SelBufferTbl[en_ThreadID].size(); us_Idx++ ) {
			// 動作モードはwild cardを許す.
			if( (st_ChkTbl.en_ThreadImgProcMode == v_SelBufferTbl[en_ThreadID][us_Idx]->en_ThreadImgProcMode) || (THRE_ImgProcMode_None == v_SelBufferTbl[en_ThreadID][us_Idx]->en_ThreadImgProcMode)){
				uchar uc_chkNum = v_SelBufferTbl[en_ThreadID][us_Idx]->uc_chkElementNum;	// 検索回数代入.
				if( --uc_chkNum == 0 ) break;
					if( st_ChkTbl.en_taskID == v_SelBufferTbl[en_ThreadID][us_Idx]->en_taskID ){
					if( --uc_chkNum == 0 ) break;
						if( st_ChkTbl.b_isPageMode == v_SelBufferTbl[en_ThreadID][us_Idx]->b_isPageMode ){
						if( --uc_chkNum == 0 ) break;
							if( st_ChkTbl.i64_selBufNo == v_SelBufferTbl[en_ThreadID][us_Idx]->i64_selBufNo ){
							if( --uc_chkNum == 0 ) break;
								// アプリ種別は、wild cardを許す.
								if( (st_ChkTbl.en_AppIDSelThread == v_SelBufferTbl[en_ThreadID][us_Idx]->en_AppIDSelThread) || (v_SelBufferTbl[en_ThreadID][us_Idx]->en_AppIDSelThread == THRE_AppID_None) ){
								if( --uc_chkNum == 0 ) break;
									// 回線IDも、wild cardを許す.
									if( (st_ChkTbl.en_LineID == v_SelBufferTbl[en_ThreadID][us_Idx]->en_LineID) || (v_SelBufferTbl[en_ThreadID][us_Idx]->en_LineID == EN_FaxLineID_Unknown) ){
									if( --uc_chkNum == 0 ) break;
										if( st_ChkTbl.b_RotAndMagnify == v_SelBufferTbl[en_ThreadID][us_Idx]->b_RotAndMagnify ){
										if( --uc_chkNum == 0 ) break;
											if( st_ChkTbl.e_OverlayType == v_SelBufferTbl[en_ThreadID][us_Idx]->e_OverlayType ){
											if( --uc_chkNum == 0 ) break;
												if( st_ChkTbl.b_is1200dpi == v_SelBufferTbl[en_ThreadID][us_Idx]->b_is1200dpi ){ //!< 1200dpiデータを判定 13/03/13 Sky ZeusS対応.
												if( --uc_chkNum == 0 ) break;
													if( st_ChkTbl.b_isOutColorYMCK == v_SelBufferTbl[en_ThreadID][us_Idx]->b_isOutColorYMCK ){ //!<出力色の判定(YMCK（属性も含め）かどうか) 10/04/05 太田 Add.
													uc_chkNum = 0;
													break;
												}
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}

		// 選択できたかどうかチェック // 2006/03/03 yokoi チェック内容を増加.
		THRL_ThAssert( (us_Idx < v_SelBufferTbl[en_ThreadID].size()), "selBuf Error AppID%d,Proc%d,ThID%d, en_LineID%d", st_ChkTbl.en_AppIDSelThread, st_ChkTbl.en_ThreadImgProcMode, en_ThreadID, st_ChkTbl.en_LineID , CFA14_DetailCode0x0808 );

		// 選択したテーブルをポインタにセット.
		ps_SelTbl = v_SelBufferTbl[en_ThreadID][us_Idx];

		THRL_ThAssert( (ps_SelTbl != NULL), "ps_SelTbl NULL pointer error", 0, 0, 0, 0, CFA14_DetailCode0x09B8 );

		// ジョブIDとページと出力モード情報から画像ライン数決定.
		ushort us_ImageLine = getTransLine( rs_ThreadComPara.c_ThreadIF.pc_Leaf, &CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k], rs_ThreadComPara.pcc_OneImageOutputMode );

		//スレッドID、スレッド画像処理モード初期化.
		for( uchar uc_Cnt=0; uc_Cnt<THRD_MAX_BUF_USE; uc_Cnt++ ){
			THRS_BufResource& rs_BufRes = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].s_usedBuf[uc_Cnt];
			rs_BufRes.e_usedBuf = THRE_BufId_None;
			rs_BufRes.b_isWrite = 0;
			rs_BufRes.ul_NeedLine = 0;
			rs_BufRes.ul_StartLine = 0;
			rs_BufRes.ul_EndLine = 0;
			rs_BufRes.pc_BufResMan = NULL;
		}

		// スレッド選択決定値格納.
		for( uchar m=0; m<THRD_MAX_BUF_USE; ++m ) {
			if( ps_SelTbl->s_usedBuf[m].e_usedBuf != THRE_BufId_None ){
				uint32_t ul_NeedLine = getWriteTransLine( en_ThreadID,
												  ps_SelTbl->s_usedBuf[m].e_usedBuf,
												  ps_SelTbl->s_usedBuf[m].b_isWrite);
				// 必要ライン数補正.
				if( ul_NeedLine == DEF_NextEnableSameImgLine ){
					ul_NeedLine = us_ImageLine;
				}
				THRS_BufResource& rs_BufRes = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].s_usedBuf[m];
				rs_BufRes.e_usedBuf = ps_SelTbl->s_usedBuf[m].e_usedBuf;
				rs_BufRes.b_isWrite = ps_SelTbl->s_usedBuf[m].b_isWrite;
				rs_BufRes.ul_NeedLine = ul_NeedLine;
				rs_BufRes.ul_StartLine = 0;
				rs_BufRes.ul_EndLine = 0;
				rs_BufRes.pc_BufResMan = pc_BufResMan[rs_BufRes.e_usedBuf];
				// バッファモード選択.
				rs_BufRes.e_BufMode = getBufMode( rs_ThreadComPara, rs_BufRes.e_usedBuf );
				rs_BufRes.e_shadowBuf = THRC_BufMemorySingletonIf::newInstance().chgShadowBufId( rs_BufRes.e_usedBuf );
			} else {
				// CQ-311887 先行変倍用のバッファを設定する.
				// 通常使用するバッファを設定した配列の未使用部分に画像変換後圧縮前バッファのRead/Writeの追加設定を行う.
				if( (en_ThreadID == THRE_ThrID_FileToBuf)
					&& (st_ChkTbl.en_ThreadImgProcMode == THRE_ImgProcMode_PreConvert
						|| theModeInfoLib.getOverlayType( rs_ThreadComPara ) == THRE_OverlayType_Binarize) ){
					// 1次伸張で画像変換を行う場合.
					if( chkPreCnvMode( rs_ThreadComPara ) == True ){
						// 1次伸張でForm単独変倍を行う場合.
						// 変換後圧縮前バッファのWrite設定.
						THRS_BufResource& rs_BufRes = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].s_usedBuf[m];
						rs_BufRes.e_usedBuf = THRE_BufId_ConvCmp;
						rs_BufRes.b_isWrite = True;
						rs_BufRes.ul_NeedLine = getWriteTransLine(en_ThreadID, THRE_BufId_ConvCmp, True);
						rs_BufRes.ul_StartLine = 0;
						rs_BufRes.ul_EndLine = 0;
						rs_BufRes.pc_BufResMan = pc_BufResMan[rs_BufRes.e_usedBuf];
						rs_BufRes.e_BufMode = getBufMode( rs_ThreadComPara, rs_BufRes.e_usedBuf );
						rs_BufRes.e_shadowBuf = THRC_BufMemorySingletonIf::newInstance().chgShadowBufId( rs_BufRes.e_usedBuf );
						m++;
						// 変換後圧縮前バッファのRead設定.
						THRL_ThAssert( ( m < THRD_MAX_BUF_USE ), "CC_MultiThreadProfile::selBuffer(): s_usedBuf error 1 m=%d", m, 0, 0, 0, CFA14_DetailCode0x0A7B );
						THRS_BufResource& rs_BufRes1 = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].s_usedBuf[m];
						rs_BufRes1.e_usedBuf = THRE_BufId_ConvCmp;
						rs_BufRes1.b_isWrite = False;
						rs_BufRes1.ul_NeedLine = getWriteTransLine(en_ThreadID, THRE_BufId_ConvCmp, False);
						rs_BufRes1.ul_StartLine = 0;
						rs_BufRes1.ul_EndLine = 0;
						rs_BufRes1.pc_BufResMan = pc_BufResMan[rs_BufRes1.e_usedBuf];
						rs_BufRes1.e_BufMode = getBufMode( rs_ThreadComPara, rs_BufRes1.e_usedBuf );
						rs_BufRes1.e_shadowBuf = THRC_BufMemorySingletonIf::newInstance().chgShadowBufId( rs_BufRes1.e_usedBuf );
						if( chkPreCnvMode_Original( rs_ThreadComPara ) == True ){
							// 変換前伸張後バッファのRead設定.
							m++;
							THRL_ThAssert( ( m < THRD_MAX_BUF_USE ), "CC_MultiThreadProfile::selBuffer(): s_usedBuf error 2 m=%d", m, 0, 0, 0, CFA14_DetailCode0x0A7C );
							THRS_BufResource& rs_BufRes2 = CC_ImgTransInfoSingletonIf::newInstance().ThInfo[ ss_Num ][uc_InOutThread][k].s_usedBuf[m];
							rs_BufRes2.e_usedBuf = THRE_BufId_ConvExp;
							rs_BufRes2.b_isWrite = False;
							rs_BufRes2.ul_NeedLine = getWriteTransLine(en_ThreadID, THRE_BufId_ConvExp, False);
							rs_BufRes2.ul_StartLine = 0;
							rs_BufRes2.ul_EndLine = 0;
							rs_BufRes2.pc_BufResMan = pc_BufResMan[rs_BufRes2.e_usedBuf];
							rs_BufRes2.e_BufMode = getBufMode( rs_ThreadComPara, rs_BufRes2.e_usedBuf );
							rs_BufRes2.e_shadowBuf = THRC_BufMemorySingletonIf::newInstance().chgShadowBufId( rs_BufRes2.e_usedBuf );
						}
					}
				}
				break;
			}
		}
		selCombineBuffer( ss_Num, rs_ThreadComPara, k );
	}
	return( b_Ans );
}

